		try {
			response = await fetch(`${chatBase(credential)}/v2/chat/completions`, {
				method: "POST",
				headers: {
					...chatHeaders(credential, userAgent, identity.clientVersion),
					"Authorization": `Bearer ${credential.accessToken}`
