      "path": "lib/providers/qoder/index.js",
      "content": "/**\n * dsh-qoder-connect —— 把 Qoder CN 订阅里的模型接入 DeepSeek Harness。\n *\n * 契约速查（完整背景见 docs/IMPLEMENTATION-NOTES.md「Qoder 渠道总览」）：\n *   · 凭据：App 会话（connect-auth/qoder-session.json，优先）或官方 PAT\n *     （connect-auth/qoder.pat），另有环境变量 QODERCN_PAT 等三条。\n *     PAT 不自动续期（官方明确不刷），jobToken 那层本模块自己刷。\n *   · 鉴权：COSY 签名而非裸 Bearer —— `buildCosyHeaders`；签名只覆盖\n *     实际发出的字节（先 encode 后 sign）。`sigPath` = pathname 去\n *     前导 `/algo`、不含 query。\n *   · 请求体经 `qoderEncodeBody` 双重编码（base64 + 自定义字母表 + 三段块旋转）。\n *   · 响应是**双层 SSE**：外层信封 `statusCodeValue/body`，内层才是 OpenAI delta；\n *     业务错误藏在信封里（HTTP 200 也可能失败）。\n *   · 两个平面别混：推理 `gateway.qoder.com.cn/algo/**`（COSY+Encode）；\n *     OpenAPI `openapi.qoder.com.cn/**`（裸 Bearer jobToken，额度/签到）。\n *   · 数据流：DSH ──OpenAI──▶ 回环 shim ──双层 SSE──▶ 网关（shim 与\n *     workbuddy/trae 同构：127.0.0.1 随机端口 + 随机 bearer）。\n *\n * @module dsh-qoder-connect\n */\n\nimport z from \"@deepseek-ai/schemastery\";\nimport { createCipheriv, createHash, publicEncrypt, randomBytes, randomUUID, timingSafeEqual } from \"node:crypto\";\nimport { existsSync, readFileSync, writeFileSync, mkdirSync } from \"node:fs\";\nimport { createServer } from \"node:http\";\nimport { homedir } from \"node:os\";\nimport { dirname, join } from \"node:path\";\nimport { Readable } from \"node:stream\";\nimport { createProvider } from \"@earendil-works/pi-ai\";\nimport { openAICompletionsApi } from \"@earendil-works/pi-ai/api/openai-completions.lazy\";\nimport { PiAiAdapter } from \"@deepseek-ai/dsh-llm-pi-ai\";\nimport { resolveRetryPolicy } from \"@deepseek-ai/dsh-llm\";\nimport { resolveDshHome } from \"@deepseek-ai/dsh-home-paths\";\nimport { abortOnClientDisconnect, briefMessage, hostIsLoopback, loopbackRequest, originIsLoopback, withLegacyImageBudget, writeJson } from \"../../shared/http.js\";\nimport { ProbeService, ProbeStore, probeModel } from \"../../shared/probe.js\";\nimport { pollInterval, readBody, writeState as writeChannelState } from \"../../shared/node.js\";\nimport { hiddenMatcher } from \"../../shared/hidden.js\";\nimport { diffCatalog } from \"../../shared/catalog-diff.js\";\n\n//#region 常量\n\n/** Cordis 插件名。必须与 cordis.patch.yml 里的 `id` 一致。 */\nexport const name = \"llm-qoder\";\n/** 注册 provider 之前必须先拿到模型注册表。 */\nexport const inject = [\"llm\"];\n\n/** DSH 里对用户展示的 provider id，也是模型选择器上那一组的名字（= 渠道名）。 */\nconst QODER_PROVIDER = \"qoder1\";\nconst QODER_DISPLAY_NAME = \"Qoder CN\";\n\n/** 推理平面（COSY 签名 + `Encode=1`）。 */\nconst DEFAULT_GATEWAY = \"https://gateway.qoder.com.cn\";\n/** OpenAPI 平面（普通 Bearer）：userinfo / 额度 / 签到活动。 */\nconst DEFAULT_OPENAPI = \"https://openapi.qoder.com.cn\";\n\n/** PAT → jobToken。**不需要签名**，也不带 Encode。 */\nconst PATH_EXCHANGE = \"/api/v1/jobToken/exchange\";\nconst PATH_USERINFO = \"/api/v1/userinfo\";\n/** 额度：参考实现那条路（COSY 签名）。 */\nconst PATH_QUOTA_LEGACY = \"/api/v2/quota/usage\";\n/** 额度：**App 自己**打的那条（OpenAPI 平面 + 普通 Bearer），字段更全。 */\nconst PATH_ACCOUNT_USAGE = \"/sash/api/v2/me/usage\";\n/** 「签到活动」状态：App 的 CampaignMainService 就是打这个。 */\nconst PATH_CAMPAIGNS = \"/sash/api/v1/me/campaigns\";\n/** 模型目录。`Encode=1` 只约束请求体，GET 的响应是明文 JSON。 */\n/**\n * [dsh-connect 2026-09-24 修正] 网关的模型目录在 **`/algo` 前缀**下。\n *\n * 实测：`/algo/api/v2/model/list?Encode=1` → 200（70KB 完整目录）；\n * 而少了 `/algo` 的老路径会被 ALB 挡成 **HTTP 503 Service Temporarily Unavailable**\n * （不是鉴权问题，所以很容易误判成\"token 不对\"）。同网关的 chat 路径本来就带 `/algo`，\n * 这条是唯一漏了前缀的。\n */\nconst PATH_MODELS = \"/algo/api/v2/model/list?Encode=1\";\n/** 对话。CN 渠道的 agent 入口（pathname 部分；签名只覆盖它，不含 query）。 */\nconst PATH_CHAT = \"/algo/api/v2/service/pro/sse/agent_chat_generation\";\n/**\n * 对话的完整路径 + 查询串。\n *\n * `Encode=1` 必须有（插件的请求体是编码过的）；`FetchKeys` / `AgentId` 是从\n * 社区 MIT 实现 `pi-provider-qoder` 抄来的，SDK 里的常量只有裸 pathname\n * （查询串由它的 wasm `prepareRequest` 补）。保险起见整串可配置：万一哪天服务端\n * 不认这两个参数，改配置即可，不用改代码。多带的查询参数一般会被忽略，\n * 而漏掉 `Encode=1` 是致命的，所以默认按「全带上」。\n */\nconst DEFAULT_CHAT_PATH = `${PATH_CHAT}?FetchKeys=llm_model_result&AgentId=agent_common&Encode=1`;\n/** CN 客户端身份。SDK 里 `Ji ? \"qoderclicn\" : \"qodercli\"`，CN 走前者。 */\nconst DEFAULT_SESSION_TYPE = \"qoderclicn\";\n\n//#endregion\n//#region COSY 客户端身份常量\n\n/**\n * COSY 内置 RSA 公钥（用来加密临时的 aesKey）。\n * 与 Qoder CLI 同一份；换 key 只会在服务端轮换时发生。\n */\nconst QODER_RSA_PUBLIC_KEY = `-----BEGIN PUBLIC KEY-----\nMIGfMA0GCSqGSIb3DQEBAQUAA4GNADCBiQKBgQDA8iMH5c02LilrsERw9t6Pv5Nc\n4k6Pz1EaDicBMpdpxKduSZu5OANqUq8er4GM95omAGIOPOh+Nx0spthYA2BqGz+l\n6HRkPJ7S236FZz73In/KVuLnwI8JJ2CbuJap8kvheCCZpmAWpb/cPx/3Vr/J6I17\nXcW+ML9FoCI6AOvOzwIDAQAB\n-----END PUBLIC KEY-----`;\n\n/**\n * 客户端身份版本号。\n *\n * ⚠️ 这是**硬编码契约**：`Cosy-Version` 落后于 Qoder CLI 当前版本时，服务端会\n * 返回被裁剪过的模型列表（本地实测：CLI 1.1.61 对应 1.1.38 可用）。\n * 随 CLI 升级要复核这里。\n */\nconst COSY_VERSION = \"1.1.38\";\n/** OpenAPI 平面用的是另一条版本线。 */\nconst COSY_OPENAPI_VERSION = \"1.0.1\";\n/**\n * **网关平面**的 `Cosy-Clienttype`（只给 `buildCosyHeaders` 用）。\n *\n * ⚠️ 它和 OpenAPI 平面的值**不是同一个**，别共用 —— 曾经共用过，正是 2026-09-27\n * 「签到活动读不到」那次误判的根因：两个平面各有各的契约。\n */\nconst COSY_CLIENT_TYPE = \"5\";\n/**\n * **OpenAPI 平面**的 `Cosy-ClientType`。\n *\n * App 主包里这是**全局唯一**常量，额度 / dataPolicy / partnerPlan / remoteControl /\n * 签到活动全都用它：\n *\n *   const Mh = Object.freeze({ clientType: 10, businessProduct: \"app\", sessionType: \"app\" });\n *   const YR = (t) => ({ …, \"Cosy-ClientType\": String(Mh.clientType), \"User-Agent\": \"Qoder\" });\n *\n * ## 为什么必须写 10\n *\n * `GET /sash/api/v1/me/campaigns`（签到活动）**按客户端类型门控**：用 5 会**稳定**返回\n * `{showCampaign:false, claimable:false, campaigns:[]}`。这个形状与「账号压根没有活动」\n * **完全一样**，于是被误判 —— 2026-09-27 实际踩到：据此把面板改成了\"不适用\"，\n * 而同一时刻桌面 App 用 10 拿到的是 `claimable:true`、`+100 credits`、`CLAIMABLE`。\n *\n * ## 换成 10 的副作用范围（已逐端点实测）\n *\n * 额度 / 成就 / 积分汇总 / 积分热力 / 活动限额 —— 两档响应**逐字节相同**；\n * 只有「签到活动」不同。验证脚本：`scripts/qoder-openapi-clienttype-compare.mjs`。\n */\nconst COSY_OPENAPI_CLIENT_TYPE = \"10\";\nconst COSY_DATA_POLICY = \"disagree\";\n\n//#endregion\n//#region Encode=1（Qoder 自定义 base64）\n\n/** 自定义字母表：第 i 个字符替代标准 base64 的第 i 个字符。 */\nconst CUSTOM_ALPHABET = \"_doRTgHZBKcGVjlvpC,@aFSx#DPuNJme&i*MzLOEn)sUrthbf%Y^w.(kIQyXqWA!\";\nconst STD_ALPHABET = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\";\n\nconst ENC_TABLE = new Uint8Array(256);\nfor (let i = 0; i < 256; i += 1) ENC_TABLE[i] = i;\nfor (let i = 0; i < 64; i += 1) ENC_TABLE[STD_ALPHABET.charCodeAt(i)] = CUSTOM_ALPHABET.charCodeAt(i);\n// Qoder 用 `$` 代替标准 base64 的 `=`。\nENC_TABLE[\"=\".charCodeAt(0)] = \"$\".charCodeAt(0);\n\n/**\n * 请求体编码：标准 base64 → 字母表重映射 → 三段块旋转。\n *\n *   标准串 std[0,n)，a = floor(n/3)\n *   密文 = map(std[n-a, n)) + map(std[a, n-a)) + map(std[0, a))\n *\n * 返回 Buffer 直接当请求体用。\n */\nexport function qoderEncodeBody(plain) {\n  const std = Buffer.isBuffer(plain) ? plain.toString(\"base64\") : Buffer.from(plain, \"utf8\").toString(\"base64\");\n  const n = std.length;\n  const a = Math.floor(n / 3);\n  const out = Buffer.allocUnsafe(n);\n  let dst = 0;\n  for (let i = n - a; i < n; i += 1) out[dst++] = ENC_TABLE[std.charCodeAt(i)];\n  for (let i = a; i < n - a; i += 1) out[dst++] = ENC_TABLE[std.charCodeAt(i)];\n  for (let i = 0; i < a; i += 1) out[dst++] = ENC_TABLE[std.charCodeAt(i)];\n  return out;\n}\n\n//#endregion\n//#region COSY 鉴权头\n\nconst md5 = (bytes) => createHash(\"md5\").update(bytes).digest(\"hex\");\n\n/**\n * 签名只覆盖 pathname 去掉前导 `/algo`，**不含 query**。\n *\n * 例：`/algo/api/v2/model/list?Encode=1` → `/api/v2/model/list`。\n * 这一点错了会拿到 401 而不是 404，很容易误判成 token 失效。\n */\nexport function sigPathOf(url) {\n  const p = new URL(url).pathname;\n  return p.startsWith(\"/algo\") ? p.slice(\"/algo\".length) : p;\n}\n\n/** 机器码：优先用 Qoder 已落盘的那份，保证跨次稳定（否则服务端会当成新设备）。 */\nexport function resolveMachineId() {\n  const candidates = [\n    process.env.QODERCN_MACHINE_ID,\n    join(homedir(), \".qoder-cn\", \".auth\", \"machine_id\"),\n    join(homedir(), \".qoder\", \".auth\", \"machine_id\"),\n  ].filter((p) => typeof p === \"string\" && p.length > 0);\n  for (const path of candidates) {\n    try {\n      const value = readFileSync(path, \"utf8\").trim();\n      if (value.length > 0) return value;\n    } catch { /* 继续找下一个 */ }\n  }\n  const fallback = join(resolveDshHome(), \"qoder\", \"machine-id\");\n  try {\n    const value = readFileSync(fallback, \"utf8\").trim();\n    if (value.length > 0) return value;\n  } catch { /* 下面生成 */ }\n  const generated = randomUUID();\n  try {\n    mkdirSync(dirname(fallback), { recursive: true });\n    writeFileSync(fallback, `${generated}\\n`, { mode: 0o600 });\n  } catch { /* 只读环境就算了，本次进程内仍然一致 */ }\n  return generated;\n}\n\n/** 平台串。SDK 会按 arch/os 拼，这里照抄。 */\nfunction machineOs() {\n  if (process.platform === \"win32\") return process.arch === \"arm64\" ? \"aarch64_windows\" : \"x86_64_windows\";\n  if (process.platform === \"darwin\") return process.arch === \"arm64\" ? \"aarch64_darwin\" : \"x86_64_darwin\";\n  return process.arch === \"arm64\" ? \"aarch64_linux\" : \"x86_64_linux\";\n}\n\n/**\n * 生成 `Authorization: Bearer COSY.<payloadB64>.<sig>` 及其配套 `Cosy-*` 头。\n *\n * `body` 必须是**最终要发出去的字节**（即已经过 {@link qoderEncodeBody} 的那份），\n * 因为签名和 `Cosy-Bodyhash` / `Cosy-Bodylength` 都覆盖它。\n */\nexport function buildCosyHeaders(body, requestUrl, creds) {\n  if (typeof creds?.userID !== \"string\" || creds.userID.length === 0) throw new Error(\"cosy: userID 为空\");\n  /**\n   * [dsh-connect 2026-09-24 修正] token 的字段名有两套：\n   * token-manager 产出的凭据对象用 `jobToken`，而 userinfo 那一步是显式传 `authToken`。\n   * 之前只认 `authToken` → 目录刷新每次都抛「cosy: authToken 为空」，\n   * 表现成\"已登录但模型永远只有兜底那一个\"。两者都认即可。\n   */\n  const authToken = typeof creds?.authToken === \"string\" && creds.authToken !== \"\" ? creds.authToken : creds?.jobToken;\n  if (typeof authToken !== \"string\" || authToken.length === 0) throw new Error(\"cosy: authToken 为空\");\n\n  const aesKey = randomUUID().replace(/-/g, \"\").slice(0, 16);\n  const userInfo = {\n    uid: creds.userID,\n    security_oauth_token: authToken,\n    name: creds.name ?? \"\",\n    aid: \"\",\n    email: creds.email ?? \"\",\n  };\n  const cipher = createCipheriv(\"aes-128-cbc\", Buffer.from(aesKey), Buffer.from(aesKey));\n  const infoB64 = cipher.update(JSON.stringify(userInfo), \"utf8\", \"base64\") + cipher.final(\"base64\");\n  const cosyKey = publicEncrypt(\n    { key: QODER_RSA_PUBLIC_KEY, padding: 1 /* RSA_PKCS1_PADDING */ },\n    Buffer.from(aesKey),\n  ).toString(\"base64\");\n\n  const ts = String(Math.floor(Date.now() / 1000));\n  const payloadB64 = Buffer.from(JSON.stringify({\n    version: \"v1\",\n    requestId: randomUUID(),\n    info: infoB64,\n    cosyVersion: COSY_VERSION,\n    ideVersion: \"\",\n  })).toString(\"base64\");\n\n  const bodyBytes = body === undefined || body === null\n    ? Buffer.alloc(0)\n    : (Buffer.isBuffer(body) ? body : Buffer.from(body));\n  const sig = createHash(\"md5\")\n    .update(payloadB64).update(\"\\n\")\n    .update(cosyKey).update(\"\\n\")\n    .update(ts).update(\"\\n\")\n    .update(bodyBytes).update(\"\\n\")\n    .update(sigPathOf(requestUrl))\n    .digest(\"hex\");\n\n  const machineId = creds.machineID ?? resolveMachineId();\n  return {\n    Authorization: `Bearer COSY.${payloadB64}.${sig}`,\n    \"Cosy-Key\": cosyKey,\n    \"Cosy-User\": creds.userID,\n    \"Cosy-Date\": ts,\n    \"Cosy-Version\": COSY_VERSION,\n    \"Cosy-Machineid\": machineId,\n    \"Cosy-Machinetoken\": machineId,\n    \"Cosy-Machinetype\": \"5\",\n    \"Cosy-Machineos\": machineOs(),\n    \"Cosy-Clienttype\": COSY_CLIENT_TYPE,\n    \"Cosy-Clientip\": \"127.0.0.1\",\n    \"Cosy-Bodyhash\": md5(bodyBytes),\n    \"Cosy-Bodylength\": String(bodyBytes.length),\n    \"Cosy-Sigpath\": sigPathOf(requestUrl),\n    \"Cosy-Data-Policy\": COSY_DATA_POLICY,\n    \"Cosy-Organization-Id\": \"\",\n    \"Cosy-Organization-Tags\": \"\",\n    \"Login-Version\": \"v2\",\n    \"X-Request-Id\": randomUUID(),\n  };\n}\n\n//#endregion\n//#region 配置\n\n/**\n * ⚠️ **本模块不导出 `Config`，也不接受用户配置**（2026-10-08 收口，理由同 trae）。\n *\n * 三合一时本模块被 `lib/index.js` 以 `apply(ctx, {})` 调起 —— 第二个参数恒为\n * 空对象，导出的 `Config` 对宿主不可见。保留 schema 只会让读者误以为这些键\n * 可以设。因此撤下；内部读取点保持 `config()?.x ?? DEFAULT` 原样，\n * config 恒空时自然落到内置默认，运行时行为与收口前一致。\n *\n * 被撤下的键（均有内置默认）：patFile、gateway、openapiBase、chatPath、\n * sessionType、pollIntervalMs。\n *\n * ⚠️ 覆盖通道不受本次收口影响的只有一条：PAT 本体可经**环境变量**\n * `QODERCN_PAT` / `QODERCN_PERSONAL_ACCESS_TOKEN` / `QODERCN_API_KEY`\n * 提供（见 `fromEnv()`）—— 这是运行凭据的正规入口，不属于配置面。\n */\n\n/**\n * 解析路径默认值 —— 必须在 DSH_HOME 可用之后才能求值。\n *\n * [2026-09-25] 认证统一收进 `$DSH_HOME/connect-auth/`（见 trae 那边的同一条说明）：\n * PAT 与 App 会话都放这里，迁移只需搬一个目录。旧路径仍可用 `patFile` / `sessionFile`\n * 配置项指回。\n */\nfunction defaultPatPath() {\n  return join(resolveDshHome(), \"connect-auth\", \"qoder.pat\");\n}\n\n//#endregion\n//#region 凭据（PAT）\n\n/**\n * PAT 读取器。\n *\n * 每次 `resolve()` 都重新读盘 + 重新读环境变量，所以宿主侧换 PAT 之后**不用重启\n * DSH** 就能生效（与 WorkBuddy / Trae 两条路一致）。\n */\n/**\n * [dsh-connect] App 会话凭据：读宿主导出的 Qoder CN 桌面 App 登录态。\n *\n * 为什么要它：官方 PAT 要在网页上手工自建，而 App 本来就已经登录好了。\n * 实测 App 的会话 token（`dt-` 前缀）在 **两个平面都是有效的 Bearer** ——\n * OpenAPI（userinfo/额度/签到）与推理（COSY 头里带的就是它），\n * 所以不需要 PAT 交换，uid 也直接来自会话（不必再问 userinfo）。\n *\n * 文件由宿主脚本 `scripts/qoder-vault.mjs --install-session` 写出（Electron safeStorage 解密）：\n *   $DSH_HOME/connect-auth/qoder-session.json   {token, refreshToken, expiresAt, uid, name, email}\n *\n * 读不到 / 过期 / 格式不对，一律返回 undefined，调用方回落到 PAT。\n */\nexport function createSessionStore(options) {\n  const { config } = options;\n  const explicitPath = () => {\n    const value = config()?.sessionFile;\n    return typeof value === \"string\" && value.length > 0 ? value : join(resolveDshHome(), \"connect-auth\", \"qoder-session.json\");\n  };\n\n  return {\n    path: explicitPath,\n    /** 当前可用的会话凭据；不可用时 undefined（不抛，因为 PAT 还能兜底）。 */\n    async current() {\n      const path = explicitPath();\n      if (!existsSync(path)) return undefined;\n      let doc;\n      try {\n        doc = JSON.parse(readFileSync(path, \"utf8\"));\n      } catch {\n        return undefined;\n      }\n      const token = typeof doc?.token === \"string\" ? doc.token.trim() : \"\";\n      const uid = typeof doc?.uid === \"string\" ? doc.uid.trim() : \"\";\n      if (token === \"\" || uid === \"\") return undefined;\n      // 过期就用不了（App 会自己续；续完重跑导出脚本即可）\n      const expiresAt = resolveExpiry({ expires_at: doc?.expiresAt, expiresAt: doc?.expiresAt }) ?? 0;\n      if (expiresAt !== 0 && expiresAt - JOB_TOKEN_SKEW_MS <= Date.now()) return undefined;\n      return {\n        token,\n        uid,\n        name: typeof doc?.name === \"string\" ? doc.name : \"\",\n        email: typeof doc?.email === \"string\" ? doc.email : \"\",\n        expiresAt: expiresAt === 0 ? Date.now() + ASSUMED_JOB_TOKEN_TTL_MS : expiresAt,\n        source: path,\n      };\n    },\n  };\n}\n\nexport function createPatStore(options) {\n  const { config } = options;\n  const explicitPath = () => {\n    const value = config()?.patFile;\n    return typeof value === \"string\" && value.length > 0 ? value : defaultPatPath();\n  };\n\n  const fromEnv = () => {\n    for (const key of [\"QODERCN_PAT\", \"QODERCN_PERSONAL_ACCESS_TOKEN\", \"QODERCN_API_KEY\"]) {\n      const value = process.env[key];\n      if (typeof value === \"string\" && value.trim().length > 0) return { pat: value.trim(), source: key };\n    }\n    return undefined;\n  };\n\n  const fromFile = () => {\n    const path = explicitPath();\n    if (!existsSync(path)) return undefined;\n    try {\n      const value = readFileSync(path, \"utf8\").trim();\n      return value.length > 0 ? { pat: value, source: path } : undefined;\n    } catch {\n      return undefined;\n    }\n  };\n\n  return {\n    path: explicitPath,\n    /**\n     * 取 PAT。读不到就抛，由调用方降级成「未登录」。\n     *\n     * 环境变量优先于文件：便于临时用另一个账号跑一次而不动落盘的凭据。\n     */\n    async resolve() {\n      const found = fromEnv() ?? fromFile();\n      if (found === undefined) {\n        throw new Error(`未配置 Qoder PAT：既没有 QODERCN_PAT/QODERCN_PERSONAL_ACCESS_TOKEN/QODERCN_API_KEY，也读不到 ${explicitPath()}。请到 https://qoder.com.cn/account/integrations 建一个 pt- 开头的 PAT。`);\n      }\n      if (!found.pat.startsWith(\"pt-\")) {\n        throw new Error(`${found.source} 里的令牌不是 pt- 前缀，Qoder 的 PAT 形如 pt-xxxxxxxx。`);\n      }\n      return found;\n    },\n    async current() {\n      try {\n        return await this.resolve();\n      } catch {\n        return undefined;\n      }\n    },\n  };\n}\n\n//#endregion\n//#region jobToken 管理\n\n/** 换来的 jobToken 还剩不到这个时长就提前重换一次。 */\nconst JOB_TOKEN_SKEW_MS = 120000;\n\n/**\n * `expires_at` 在 Qoder 的返回里可能是 ISO 串、秒级数字或毫秒级数字；\n * `expires_in` 可能是秒也可能是毫秒。全部宽容处理，读不出来就返回 undefined\n * （调用方按「保守 30 分钟」处理）。\n */\nexport function resolveExpiry(doc) {\n  const at = doc?.expires_at;\n  if (typeof at === \"string\") {\n    const parsed = Date.parse(at);\n    if (Number.isFinite(parsed)) return parsed;\n  }\n  if (typeof at === \"number\" && Number.isFinite(at)) return at < 1e12 ? at * 1000 : at;\n  const inSecondsOrMs = doc?.expires_in;\n  if (typeof inSecondsOrMs === \"number\" && Number.isFinite(inSecondsOrMs) && inSecondsOrMs > 0) {\n    return Date.now() + (inSecondsOrMs < 1e6 ? inSecondsOrMs * 1000 : inSecondsOrMs);\n  }\n  return undefined;\n}\n\n/** 保守兜底：拿不到有效期时按 30 分钟算。 */\nconst ASSUMED_JOB_TOKEN_TTL_MS = 1800000;\n\n/**\n * PAT → jobToken 的管理器。\n *\n * 一次成功的交换缓存起来；并发调用只会打一次上游（single-flight）。\n * jobToken 过期就重新用 PAT 换 —— PAT 本身不会过期（除非用户在网页上吊销）。\n */\nexport function createTokenManager(options) {\n  const { pats, sessions, logger, config } = options;\n  const openapiBase = () => String(config()?.openapiBase ?? DEFAULT_OPENAPI).replace(/\\/+$/, \"\");\n\n  /** @type {{ jobToken: string, expiresAt: number, userID: string, name: string, email: string, machineID: string, source: string }|undefined} */\n  let cached;\n  /** @type {Promise<unknown>|undefined} */\n  let inflight;\n\n  /** PAT 交换。不需要签名，也不带 Encode —— 这是唯一一条「裸」请求。 */\n  async function exchange(pat) {\n    const url = `${openapiBase()}${PATH_EXCHANGE}`;\n    let response;\n    try {\n      response = await fetch(url, {\n        method: \"POST\",\n        headers: {\n          \"Content-Type\": \"application/json\",\n          Accept: \"application/json\",\n          \"User-Agent\": \"dsh-qoder-connect\",\n          \"Cosy-Version\": COSY_OPENAPI_VERSION,\n          \"Cosy-ClientType\": COSY_CLIENT_TYPE,\n        },\n        body: JSON.stringify({ personal_token: pat }),\n        signal: AbortSignal.timeout(20000),\n      });\n    } catch (error) {\n      throw new Error(`连不上 Qoder OpenAPI（${openapiBase()}）：${error instanceof Error ? error.message : String(error)}`);\n    }\n    const text = await response.text().catch(() => \"\");\n    if (!response.ok) {\n      const brief = text.replace(/\\s+/g, \" \").slice(0, 200);\n      if (response.status === 401 || response.status === 403) {\n        throw new Error(`PAT 被拒绝（HTTP ${response.status}）：可能已吊销或填错。${brief}`);\n      }\n      throw new Error(`PAT 交换失败（HTTP ${response.status}）：${brief}`);\n    }\n    let doc;\n    try {\n      doc = JSON.parse(text);\n    } catch {\n      throw new Error(`PAT 交换返回的不是 JSON：${text.slice(0, 200)}`);\n    }\n    const jobToken = typeof doc?.token === \"string\" ? doc.token.trim() : \"\";\n    if (jobToken.length === 0) throw new Error(`PAT 交换没有返回 token：${text.slice(0, 200)}`);\n    return {\n      jobToken,\n      refreshToken: typeof doc?.refresh_token === \"string\" ? doc.refresh_token : \"\",\n      expiresAt: resolveExpiry(doc) ?? (Date.now() + ASSUMED_JOB_TOKEN_TTL_MS),\n    };\n  }\n\n  /** userinfo：补上 COSY 签名需要的 uid/name/email。 */\n  async function fetchUserInfo(creds) {\n    const url = `${openapiBase()}${PATH_USERINFO}`;\n    const response = await fetch(url, {\n      headers: { ...buildCosyHeaders(null, url, creds), Accept: \"application/json\", \"User-Agent\": \"dsh-qoder-connect\" },\n      signal: AbortSignal.timeout(20000),\n    });\n    if (!response.ok) {\n      throw new Error(`userinfo 返回 HTTP ${response.status}：${(await response.text().catch(() => \"\")).slice(0, 200)}`);\n    }\n    const doc = await response.json().catch(() => undefined);\n    return {\n      userID: typeof doc?.id === \"string\" ? doc.id : \"\",\n      email: typeof doc?.email === \"string\" ? doc.email : \"\",\n      name: typeof doc?.name === \"string\" ? doc.name : (typeof doc?.username === \"string\" ? doc.username : \"\"),\n    };\n  }\n\n  async function refresh() {\n    const machineID = resolveMachineId();\n\n    // —— 优先用 App 会话：不需要 PAT、不需要 userinfo 往返 ——\n    // 实测 App 的会话 token 在两个平面都有效（OpenAPI 200；推理平面 COSY 头里用的就是它）。\n    if (sessions !== undefined) {\n      const session = await sessions.current().catch(() => undefined);\n      if (session !== undefined) {\n        cached = {\n          jobToken: session.token,\n          expiresAt: session.expiresAt,\n          userID: session.uid,\n          name: session.name,\n          email: session.email,\n          machineID,\n          source: session.source,\n        };\n        logger?.debug?.(`dsh-qoder-connect: 使用 App 会话凭据（uid=${cached.userID}，有效期至 ${new Date(cached.expiresAt).toISOString()}）`);\n        return cached;\n      }\n    }\n\n    const { pat, source } = await pats.resolve();\n    const exchanged = await exchange(pat);\n\n    // userinfo 要 uid 才能签，而 uid 又要拿 jobToken 去问 —— 先要一次再补全。\n    const identity = await fetchUserInfo({ userID: \"\", authToken: exchanged.jobToken, machineID }).catch(async (error) => {\n      logger?.warn(`dsh-qoder-connect: userinfo 读取失败（额度与签到会缺账号名，推理不受影响）：${error instanceof Error ? error.message : String(error)}`);\n      return { userID: \"\", email: \"\", name: \"\" };\n    });\n    if (identity.userID === \"\") {\n      // uid 拿不到就签不出 COSY，等于不能用。\n      throw new Error(\"Qoder userinfo 没有返回用户 id，无法生成 COSY 签名（PAT 可能已失效）。\");\n    }\n\n    cached = {\n      jobToken: exchanged.jobToken,\n      expiresAt: exchanged.expiresAt,\n      userID: identity.userID,\n      name: identity.name,\n      email: identity.email,\n      machineID,\n      source,\n    };\n    logger?.debug?.(`dsh-qoder-connect: jobToken 已刷新（uid=${cached.userID}，有效期至 ${new Date(cached.expiresAt).toISOString()}）`);\n    return cached;\n  }\n\n  return {\n    /** 拿一份当前可用的凭据；过期或缺失就重换。 */\n    async get() {\n      if (cached !== undefined && cached.expiresAt - JOB_TOKEN_SKEW_MS > Date.now()) return cached;\n      if (inflight === undefined) {\n        inflight = refresh().finally(() => { inflight = undefined; });\n      }\n      return inflight;\n    },\n    /** 只读快照，不触发刷新；状态路由用它避免每次打开面板都打上游。 */\n    peek() {\n      return cached;\n    },\n    /** 强制重换（PAT 在网页上被吊销后，用户改了 pat 文件等场景）。 */\n    invalidate() {\n      cached = undefined;\n    },\n  };\n}\n\n//#endregion\n//#region 模型目录\n\n/**\n * 拿不到目录时的兜底名单。\n *\n * **只放确认存在的 key。** 目录是懒加载的（要先有可用 jobToken），在第一次成功\n * 拉取之前模型组得有东西，否则 DSH 会按「模型组为空」把它整个隐藏掉。\n *\n * `qmodel_38max` 是从本机 Qoder CN 的运行清单里读到的真实 key\n * （`~/.qoder-cn/logs/runs/&lt;run_id&gt;/manifest.json` 的 `--model` 参数）；\n * 其余模型一律等网关目录返回，不猜名字。\n */\nexport const FALLBACK_QODER_MODELS = [\n  // 兜底条目**不声明档位**（declaredEfforts 留空）：兜底 = 目录拿不到 = 我们不知道。\n  // 曾写死 [\"xhigh\",\"low\",\"medium\"]（qmodel_38max 的线上声明），目录一挂它就\n  // 被安到所有模型头上 —— dmodel 的 high/max、mmodel 的无思考，全都变成另一套。\n  // 档位为空 ⇒ 描述符 reasoning:false ⇒ 不给档位选择，与「off 恒为 null」同一收口原则：\n  // 宁可少一个选项，也不提供一个可能 400 的档位。目录一恢复，真实声明立即回来。\n  { id: \"qmodel_38max\", name: \"Qwen3.8-Max\", contextWindow: 200000, maxTokens: 32000, supportsImages: false, isReasoning: true, declaredEfforts: [], isFree: false, rate: undefined },\n];\n\n/** 宽松取数：数字或数字串都认（SDK 的 `oci()` 就是这么写的）。 */\nfunction toNumber(value) {\n  if (typeof value === \"number\" && Number.isFinite(value)) return value;\n  if (typeof value === \"string\" && value.trim().length > 0) {\n    const parsed = Number(value);\n    if (Number.isFinite(parsed)) return parsed;\n  }\n  return undefined;\n}\n\n/** 宽松取布尔（SDK 的 `aci()`）。 */\nfunction toBoolean(value) {\n  if (typeof value === \"boolean\") return value;\n  if (value === 1 || value === \"1\") return true;\n  if (value === 0 || value === \"0\") return false;\n  return undefined;\n}\n\n/** 目录最大可用的上下文窗口：优先 `context_config` 里最大的 token_count。 */\nfunction contextWindowOf(entry) {\n  const config = entry?.context_config;\n  if (config !== null && typeof config === \"object\" && !Array.isArray(config)) {\n    let best;\n    for (const window of Object.values(config)) {\n      const count = toNumber(window?.token_count);\n      if (count !== undefined && (best === undefined || count > best)) best = count;\n    }\n    if (best !== undefined) return best;\n  }\n  const maxInput = toNumber(entry?.max_input_tokens ?? entry?.maxInputTokens);\n  if (maxInput !== undefined && maxInput > 0) return maxInput;\n  return undefined;\n}\n\n/**\n * 把网关的 `chat[]` 条目归一化成本插件内部形状。\n *\n * 字段名以 `@qoder-ai/qoder-cn-agent-sdk` 的 `sci()` 为准（那里是 camelCase 与\n * snake_case 都认）——**倍率就是 `price_factor`**，界面上按 `<n>×` 显示。\n */\n/**\n * 解析上游的 `thinking_config` → 档位声明。\n *\n * ## 为什么要单独解析它\n *\n * `is_reasoning` **不是**\"支不支持思考档位\"。实测反例（2026-10-06，原始目录）：\n *\n * | 模型 | is_reasoning | thinking_config.enabled.efforts |\n * |---|---|---|\n * | DeepSeek-Flash (`dfmodel`) | **false** | **high / max / low** |\n * | Kimi-K3 (`kmodel_latest`) | **false** | **high / low / max** |\n * | Qwen3.8-Max (`qmodel_38max`) | true | **xhigh / low / medium** |\n * | Qwen3.7-Plus (`qmodel`) | true | （空） |\n *\n * `is_reasoning` 的含义是\"是否**专用**思考模型\"（Flash 系列不是），所以\n * DeepSeek-Flash 标 false 是**上游的正确表述**，别拿它当\"不支持档位\"。\n * 真正的档位声明在 `thinking_config.enabled.efforts` 这个字典里，**逐模型不同**。\n *\n * @returns `{ declared, defaultEffort, canDisable }`；无配置时 declared 为空数组。\n */\nfunction parseThinkingConfig(raw) {\n  const enabled = raw?.thinking_config?.enabled;\n  const efforts = enabled?.efforts !== null && typeof enabled?.efforts === \"object\" ? enabled.efforts : undefined;\n  const declared = efforts === undefined ? [] : Object.keys(efforts);\n  const defaultEffort = efforts === undefined\n    ? undefined\n    : (Object.entries(efforts).find(([, v]) => v?.is_default === true)?.[0]);\n  // `disabled` 段存在 = 上游提供\"关闭思考\"这一档（对应 id 后缀 @nothink）。\n  const canDisable = raw?.thinking_config?.disabled !== null && typeof raw?.thinking_config?.disabled === \"object\";\n  return { declared, defaultEffort, canDisable };\n}\n\nexport function normalizeCatalogEntry(raw) {\n  const key = String(raw?.key ?? raw?.model_key ?? \"\").trim();\n  if (key.length === 0) return undefined;\n  const enabled = raw?.enable === undefined ? true : (toBoolean(raw.enable) ?? true);\n  const rate = toNumber(raw?.price_factor ?? raw?.priceFactor);\n  const free = toBoolean(raw?.is_free ?? raw?.isFree) ?? (rate === 0);\n  const thinking = parseThinkingConfig(raw);\n  return {\n    id: key,\n    name: String(raw?.display_name ?? raw?.name ?? key) || key,\n    contextWindow: contextWindowOf(raw),\n    maxTokens: toNumber(raw?.max_output_tokens) ?? 32000,\n    supportsImages: toBoolean(raw?.is_vl) === true,\n    isReasoning: toBoolean(raw?.is_reasoning) === true,\n    /**\n     * 上游声明的档位（逐模型不同）。**空数组表示上游没声明** —— 不等于\"不支持\"，\n     * 实测 `qmodel` 声明为空却接受全部档位，所以这种情况交给探查实测。\n     */\n    declaredEfforts: thinking.declared,\n    defaultEffort: thinking.defaultEffort,\n    canDisableThinking: thinking.canDisable,\n    isFree: free,\n    rate,\n    originalRate: toNumber(raw?.original_price_factor ?? raw?.originPriceFactor),\n    promotion: raw?.promotion !== null && typeof raw?.promotion === \"object\" ? raw.promotion : undefined,\n    source: typeof raw?.source === \"string\" ? raw.source : \"system\",\n    outerProvider: typeof raw?.outer_provider === \"string\" ? raw.outer_provider : undefined,\n    enabled,\n  };\n}\n\n/**\n * 模型目录。\n *\n * 与 WorkBuddy / Trae 两条路不同，Qoder 的目录是**懒加载 + 快照兜底**：\n * 只有拿到可用 jobToken 才会去拉一次，拉到就缓存；失败保留上一次的结果（或者\n * 兜底名单），绝不让「目录暂时不可用」升级成「渠道消失」。\n */\nexport function createCatalog(options) {\n  const { tokens, logger, config } = options;\n  const gateway = () => String(config()?.gateway ?? DEFAULT_GATEWAY).replace(/\\/+$/, \"\");\n\n  let models = [...FALLBACK_QODER_MODELS];\n  let source = \"fallback\";\n  let fetchedAt = 0;\n  let lastError;\n\n  /** 打一次 `GET /api/v2/model/list?Encode=1`（COSY 签名，响应是明文 JSON）。 */\n  async function fetchFromRemote(credential) {\n    const url = `${gateway()}${PATH_MODELS}`;\n    const response = await fetch(url, {\n      headers: { ...buildCosyHeaders(null, url, credential), Accept: \"application/json\", \"User-Agent\": \"dsh-qoder-connect\" },\n      signal: AbortSignal.timeout(30000),\n    });\n    if (!response.ok) {\n      throw new Error(`model/list 返回 HTTP ${response.status}：${(await response.text().catch(() => \"\")).slice(0, 300)}`);\n    }\n    const doc = await response.json().catch(() => undefined);\n    const chat = Array.isArray(doc?.chat) ? doc.chat : [];\n    const usable = chat.map((entry) => normalizeCatalogEntry(entry)).filter((entry) => entry !== undefined && entry.enabled);\n    if (usable.length === 0) throw new Error(`model/list 没有返回任何可用模型（chat 长度 ${chat.length}）`);\n    return usable;\n  }\n\n  /** 刷新目录。并发调用共享同一次上游请求。 */\n  let inflight;\n  async function reload() {\n    if (inflight === undefined) {\n      inflight = (async () => {\n        const credential = await tokens.get();\n        const list = await fetchFromRemote(credential);\n        models = list;\n        source = \"remote\";\n        fetchedAt = Date.now();\n        lastError = undefined;\n        logger?.info?.(`dsh-qoder-connect: 目录已刷新，${list.length} 个模型可用`);\n        return list;\n      })().catch((error) => {\n        lastError = error instanceof Error ? error.message : String(error);\n        logger?.warn?.(`dsh-qoder-connect: 目录刷新失败，沿用${source === \"remote\" ? \"上次快照\" : \"兜底名单\"}：${lastError}`);\n        throw error;\n      }).finally(() => { inflight = undefined; });\n    }\n    return inflight;\n  }\n\n  return {\n    reload,\n    source: () => source,\n    fetchedAt: () => fetchedAt,\n    lastError: () => lastError,\n    current: () => models,\n    find: (id) => models.find((model) => model.id === id),\n  };\n}\n\n//#endregion\n//#region 上游对话客户端\n\n/** 逐字节喂入的 SSE 读取器：`event:<name>\\n` + `data:<payload>\\n\\n`。 */\nexport function createSseReader() {\n  const decoder = new TextDecoder();\n  let buffer = \"\";\n  let eventName = \"\";\n  const dataLines = [];\n  const pending = [];\n\n  const flush = () => {\n    if (eventName === \"\" && dataLines.length === 0) return;\n    const raw = dataLines.join(\"\\n\");\n    pending.push({ event: eventName === \"\" ? \"message\" : eventName, raw });\n    eventName = \"\";\n    dataLines.length = 0;\n  };\n\n  return {\n    push(bytes) {\n      buffer += decoder.decode(bytes, { stream: true });\n      let newline;\n      while ((newline = buffer.indexOf(\"\\n\")) !== -1) {\n        const line = buffer.slice(0, newline).replace(/\\r$/, \"\");\n        buffer = buffer.slice(newline + 1);\n        if (line === \"\") { flush(); continue; }\n        if (line.startsWith(\"event:\")) { eventName = line.slice(6).trim(); continue; }\n        if (line.startsWith(\"data:\")) { dataLines.push(line.slice(5).replace(/^ /, \"\")); continue; }\n      }\n      const out = pending.slice();\n      pending.length = 0;\n      return out;\n    },\n    /**\n     * 流结束时的收尾（2026-10-08 加，与 Trae 侧同形）。\n     *\n     * 事件分隔靠空行，最后一个事件没有尾随换行时会一直留在 `buffer` 里被丢掉\n     * （实测 `\"event: a\\ndata: 1\"` → `[]`）。被截断的流最容易缺这个空行，\n     * 而丢掉的又可能是 `[DONE]`／终态事件，于是正常收尾与截断分不出来。\n     */\n    end() {\n      buffer += decoder.decode();\n      const tail = buffer.replace(/\\r$/, \"\");\n      buffer = \"\";\n      if (tail !== \"\") {\n        if (tail.startsWith(\"event:\")) eventName = tail.slice(6).trim();\n        else if (tail.startsWith(\"data:\")) dataLines.push(tail.slice(5).replace(/^ /, \"\"));\n      }\n      flush();\n      const out = pending.slice();\n      pending.length = 0;\n      return out;\n    },\n    pending() {\n      const out = pending.slice();\n      pending.length = 0;\n      return out;\n    },\n  };\n}\n\n/** Qoder 的 SSE 控制哨兵（见 SDK 的 `giA()`）。 */\nfunction isControlSentinel(raw) {\n  return raw === \"[DONE]\"\n    || raw === \"[NOT_EXCEED_QUOTA]\"\n    || raw.startsWith(\"[EXCEED_QUOTA]\")\n    || raw.startsWith(\"[NOTIFICATIONS]\");\n}\n\n/**\n * 解开一层 Qoder 信封。\n *\n * Qoder 的 `data:` 有两层：\n *   data: {\"statusCodeValue\":200,\"statusCode\":200,\"body\":\"{\\\"choices\\\":[...]}\"}\n * 其中 `body` 是**字符串**，里面才是 OpenAI 形状的 chunk；也可能是 `\"[DONE]\"`。\n *\n * 返回：\n *   `{kind:\"chunk\", chunk}`   内层是普通 chunk\n *   `{kind:\"done\"}`           流结束\n *   `{kind:\"error\", code, message}` 上游业务错误（code 来自 statusCodeValue）\n *   `{kind:\"ignore\"}`         控制哨兵 / 空事件\n */\n/**\n * 判断一条 403 错误是不是**凭据失效**。\n *\n * 为什么要看文案而不是只看状态码（2026-10-08 实测）：Qoder 用 403 表示两种\n * 完全不同的事 ——\n *   · `{\"code\":\"110\",\"message\":\"Billing daily count exceeded\"}` = 当日调用次数超限\n *   · 真正的 token 失效 / PAT 被吊销\n * 两者状态码相同。若一律当凭据问题，就会出现「刷新 token → 再打一次 → 还是\n * 403 → 用户看到\"API 密钥无效\"」这种误导性提示，还白花一次请求。\n *\n * 判据：403 的正文里出现凭据类词汇才算。命中即视为可重试的凭据问题。\n */\nexport function isCredentialRejection(message) {\n  const text = typeof message === \"string\" ? message.toLowerCase() : \"\";\n  if (text === \"\") return false;\n  // 明确的\"额度/限额\"语义优先否决，避免 billing/unauthorized 之类的交叉词误判。\n  if (/billing|quota|exceed|rate.?limit|too many|额度|限额/.test(text)) return false;\n  return /token|credential|api.?key|unauthori|auth|invalid|expire|登录|凭据|密钥/.test(text);\n}\n\n/**\n * 额度/限流类失败的判据（与 {@link isCredentialRejection} 互补）。\n *\n * 实测（2026-10-08）：Qoder 的当日次数超限走 `403 code:110\n * \"Billing daily count exceeded\"` —— 是额度语义，不是凭据失效。\n */\nexport function isQuotaRejection(message) {\n  const text = typeof message === \"string\" ? message.toLowerCase() : \"\";\n  if (text === \"\") return false;\n  /**\n   * 中英双语都要覆盖：本机实测出现过的原文是\n   *   · `{\"code\":\"110\",\"message\":\"Billing daily count exceeded\"}`\n   *   · WorkBuddy 侧同族文案 `您的使用量已超出频率限制，将在 … 重置`\n   * 少一种语言，那条失败就还会被当成密钥问题。\n   */\n  return /billing|quota|exceed|rate.?limit|too many|usage limit|额度|限额|次数|频率限制|使用量已超出|超出频率/.test(text);\n}\n\n/**\n * 抹掉文案里的裸 HTTP 状态码。\n *\n * DSH 前端用 `classifyPiAiError(message)` **从错误文案里猜类别**，判定顺序是：\n *\n *   1. `/\\b(?:401|403)\\b/`             → `AUTH`\n *   2. `isQuotaExceededError(message)`  → `QUOTA`\n *   3. `/\\b429\\b|rate.?limit/`          → `RATE_LIMIT`\n *   4. `/\\b(?:413|400)\\b/`              → `INVALID_REQUEST`\n *   5. `/\\b5\\d\\d\\b/`                    → `SERVER`\n *\n * 顺序决定了一件要命的事：**文案里只要出现 401/403 这三个数字，额度错误也会被判成\n * `AUTH`**。而 `AUTH` 在前端会把原文**整条丢弃**（`displayFailure` 对 AUTH 只返回\n * 空 message），于是用户看到的是「API 密钥无效」——真实原因完全不可见，还会被误导\n * 去找密钥问题（凭据其实一直有效，同凭据探测能正常打上游）。\n *\n * 所以额度类失败在渲染前把状态码换成**词**：保留诊断信息，同时不再被前面的分支抢走。\n */\nexport function neutralizeStatusTokens(text) {\n  return String(text ?? \"\")\n    .replace(/\\b(?:401|403)\\b/g, \"denied\")\n    .replace(/\\b429\\b/g, \"rate-limited\")\n    .replace(/\\b413\\b/g, \"too-large\")\n    .replace(/\\b400\\b/g, \"bad-request\")\n    .replace(/\\b5\\d\\d\\b/g, \"server-error\");\n}\n\n/**\n * 把上游失败渲染成**宿主能正确分类**的文案。\n *\n * 额度/限流类：改用宿主认得的措辞（`usage limit exceeded`）并抹掉状态码，\n * 让它落进 `QUOTA`/`RATE_LIMIT`，前端就会显示额度提示而不是\"API 密钥无效\"。\n * 其余（含真正的凭据失效）保持原文 —— 那些本来就该按状态码分类。\n */\nexport function describeUpstreamFailure(status, message) {\n  const text = typeof message === \"string\" ? message : String(message ?? \"\");\n  if (isQuotaRejection(text)) {\n    return `Qoder 上游额度限制：usage limit exceeded（当日调用次数或额度已达上限，额度恢复后可继续使用）。上游原文：${neutralizeStatusTokens(text).slice(0, 300)}`;\n  }\n  return `qoder upstream (http ${status}): ${text.slice(0, 400)}`;\n}\n\nexport function unwrapQoderEvent(raw) {\n  const text = typeof raw === \"string\" ? raw.trim() : \"\";\n  if (text === \"\") return { kind: \"ignore\" };\n  if (text === \"[DONE]\") return { kind: \"done\" };\n  if (text === \"[NOT_EXCEED_QUOTA]\") return { kind: \"ignore\" };\n  if (text.startsWith(\"[EXCEED_QUOTA]\")) return { kind: \"error\", code: 429, message: \"Qoder 额度已用尽（EXCEED_QUOTA）\" };\n  if (text.startsWith(\"[NOTIFICATIONS]\")) return { kind: \"ignore\" };\n\n  let envelope;\n  try {\n    envelope = JSON.parse(text);\n  } catch {\n    return { kind: \"ignore\" };\n  }\n\n  // 带信封的形状。\n  if (envelope !== null && typeof envelope === \"object\" && envelope.statusCodeValue !== undefined && envelope.body !== undefined) {\n    const code = toNumber(envelope.statusCodeValue);\n    if (code !== undefined && code !== 200) {\n      const detail = typeof envelope.body === \"string\" ? envelope.body : JSON.stringify(envelope.body);\n      /**\n       * **带上 `code`**（2026-10-08 加）：业务级 401/403 藏在这个信封里，\n       * 而调用方要靠它判断\"是不是凭据问题、要不要 invalidate 后重试\"。\n       * 修之前这里只给 message，于是凭据失效走不到重试分支 ——\n       * 表现成「整轮失败：API 密钥无效」，而下一轮又正常。\n       */\n      return { kind: \"error\", code, message: `Qoder 上游 ${code}：${detail.slice(0, 400)}` };\n    }\n    const body = envelope.body;\n    if (typeof body !== \"string\") {\n      // 有的实现直接把对象塞在 body 里。\n      return body !== null && typeof body === \"object\" ? { kind: \"chunk\", chunk: body, envelope } : { kind: \"ignore\" };\n    }\n    const inner = body.trim();\n    if (inner === \"\") return { kind: \"ignore\" };\n    if (inner === \"[DONE]\") return { kind: \"done\" };\n    if (isControlSentinel(inner)) return { kind: \"ignore\" };\n    try {\n      return { kind: \"chunk\", chunk: JSON.parse(inner), envelope };\n    } catch {\n      return { kind: \"ignore\" };\n    }\n  }\n\n  // 裸 OpenAI chunk（防御性：万一服务端换了形状）。\n  if (envelope !== null && typeof envelope === \"object\" && Array.isArray(envelope.choices)) {\n    return { kind: \"chunk\", chunk: envelope };\n  }\n  return { kind: \"ignore\" };\n}\n\n/** 把 Qoder 的 delta 翻成 OpenAI 的 delta。 */\nfunction deltaOf(chunk) {\n  const choice = Array.isArray(chunk?.choices) ? chunk.choices[0] : undefined;\n  const delta = choice?.delta;\n  if (delta === null || typeof delta !== \"object\") return undefined;\n  const out = {};\n  if (typeof delta.content === \"string\" && delta.content.length > 0) out.content = delta.content;\n  // Qoder 的思考链字段就叫 reasoning_content（与 DeepSeek 一致）。\n  if (typeof delta.reasoning_content === \"string\" && delta.reasoning_content.length > 0) out.reasoning_content = delta.reasoning_content;\n  if (Array.isArray(delta.tool_calls) && delta.tool_calls.length > 0) out.tool_calls = delta.tool_calls;\n  return Object.keys(out).length > 0 ? out : undefined;\n}\n\n/** 组装对话请求体（OpenAI 形状 + Qoder 专有字段）。 */\n/**\n * pi-ai 的思考档位键空间（宿主契约，**不可扩展**）。\n *\n * 取自 pi-ai 源码 `THINKING_LEVELS`（`Object.keys({off,minimal,low,medium,high,xhigh,max})`），\n * 按\"强度递增\"排列。`thinkingLevelMap` 的**键**必须落在这个集合里，多一个键会被\n * 宿主忽略、少一个就少一档可选。\n *\n * ⚠️ 这里固定的是**键**（宿主定死的），不是\"哪些键可用\"——后者由上游声明\n * （`declaredEfforts`）与探查实测决定，见 {@link reasoningFieldsFor}。\n * 早先的错误做法是拿一个写死的 5 档子集当\"上游支持集\"，那既漏了 `xhigh`，\n * 又让探查永远找不到新档位。\n */\nexport const PI_AI_THINKING_LEVELS = [\"off\", \"minimal\", \"low\", \"medium\", \"high\", \"xhigh\", \"max\"];\n\n/**\n * 该渠道**可能**在线上出现的档位（探查候选的上界）。\n *\n * = pi-ai 键空间去掉 `off`：实测上游对 `off` 返回 400，它不是\"关思考\"的拼写\n * （关思考走 id 后缀 `@nothink`）。其余键都值得一探 —— 包括上游今天没声明的，\n * 因为实测显示**声明为空 ≠ 不支持**（`qmodel` 声明空却接受 5 档）。\n */\nexport const PROBE_CANDIDATE_EFFORTS = PI_AI_THINKING_LEVELS.filter((level) => level !== \"off\");\n\n/**\n * 算某个模型\"支持哪些档位\"：**上游声明 ∪ 探查实测**，并按强度排序。\n *\n * 唯一的档位真值来源，shim 与模型描述符共用，避免各处各算一套。\n * - 上游声明（`declaredEfforts`）来自 `thinking_config.enabled.efforts`；\n * - 探查实测（`validating` 时的 efforts）覆盖\"声明为空但实际支持\"的情形。\n * 两者都没有则返回空数组，调用方据此决定\"不给档位\"。\n */\nexport function supportedEffortsOf(info, observed) {\n  const declared = Array.isArray(info?.declaredEfforts) ? info.declaredEfforts : [];\n  const measured = observed?.validation === \"validating\" && Array.isArray(observed.efforts) ? observed.efforts : [];\n  const set = new Set([...declared, ...measured]);\n  // 按 pi-ai 键空间的强度顺序排序；声明里出现的未知拼写也保留（排最后）。\n  return [...set].sort((a, b) => {\n    const ia = PI_AI_THINKING_LEVELS.indexOf(a);\n    const ib = PI_AI_THINKING_LEVELS.indexOf(b);\n    return (ia === -1 ? 99 : ia) - (ib === -1 ? 99 : ib);\n  });\n}\n\nexport function buildChatBody(options) {\n  const { modelKey, messages, isReasoning, reasoningEffort, reasoningEffortExact, supportedEfforts, defaultEffort, maxTokens, tools, toolChoice, temperature, sessionId, sessionType } = options;\n  const requestId = randomUUID();\n  const lastUser = [...(Array.isArray(messages) ? messages : [])].reverse().find((m) => m?.role === \"user\");\n  const promptText = typeof lastUser?.content === \"string\"\n    ? lastUser.content\n    : Array.isArray(lastUser?.content)\n      ? lastUser.content.filter((p) => p?.type === \"text\").map((p) => p.text).join(\"\\n\")\n      : \"\";\n\n  /** @type {Record<string, unknown>} */\n  const parameters = { enable_thinking: isReasoning === true };\n  if (Number.isFinite(maxTokens) && maxTokens > 0) parameters.max_tokens = Math.trunc(maxTokens);\n  if (Number.isFinite(temperature)) parameters.temperature = temperature;\n  /**\n   * 思考档位。原先写死 `\"high\"`，用户无从选择；现在用 pi-ai 按 `thinkingLevelMap`\n   * 映射后下发的值（见 {@link reasoningFieldsFor} 的实测依据）。\n   *\n   * 只接受已知档位，其余一律回退 `\"high\"`：\n   * - 上游对未知值（含 `off`）返回 400，宁可回退也不能把请求打挂；\n   * - `\"high\"` 正是改动前的行为，所以异常输入不会让体验变差。\n   */\n  if (isReasoning === true) {\n    /**\n     * `reasoningEffortExact` 供**探查**使用：原样透传、不走回退。\n     *\n     * 探查必须能发出\"上游不认识的哨兵值\"。若被回退成合法档位，就永远测不出\n     * \"上游是否校验该字段\" —— 哨兵拒绝法会整体失效（所有值都被当成接受）。\n     */\n    if (typeof reasoningEffortExact === \"string\") {\n      parameters.reasoning_effort = reasoningEffortExact;\n    } else {\n      /**\n       * 正常路径：只发该模型**确实支持**的档位。\n       *\n       * 回退目标分两级：\n       *   1. `supportedEfforts` 为空 → 用户没选档。回退**目录默认档**\n       *      （`defaultEffort`，来自 thinking_config 里 is_default 的那档），\n       *      而不是想当然的最高档 —— dmodel 声明的默认是 max，qmodel_38max\n       *      是 medium，各模型不同。上游给了默认值就该用它。\n       *   2. 用户选了但不支持 → 回退**已支持集合里的最高档**（改动前的行为）。\n       * 集合也没有（兜底名单 + 无探查）时退回键空间最高档。\n       */\n      const usable = (Array.isArray(supportedEfforts) && supportedEfforts.length > 0\n        ? supportedEfforts\n        : PROBE_CANDIDATE_EFFORTS);\n      parameters.reasoning_effort = usable.includes(reasoningEffort)\n        ? reasoningEffort\n        // 未选档 → 目录默认档；但**仅当默认档确在支持集合内** ——\n        // 兜底名单/指纹不符时默认档可能与支持集合脱节，发一个明知会被拒\n        // 的值等于把 400 变回随机故障，仍回退集合最高档。\n        : reasoningEffort === undefined && typeof defaultEffort === \"string\" && usable.includes(defaultEffort)\n          ? defaultEffort\n          : usable[usable.length - 1];\n    }\n  }\n\n  return {\n    request_id: requestId,\n    request_set_id: requestId,\n    chat_record_id: requestId,\n    session_id: typeof sessionId === \"string\" && sessionId.length > 0 ? sessionId : randomUUID(),\n    stream: true,\n    chat_task: \"FREE_INPUT\",\n    is_reply: true,\n    is_retry: false,\n    source: 1,\n    version: \"3\",\n    agent_id: \"agent_common\",\n    task_id: \"common\",\n    session_type: typeof sessionType === \"string\" && sessionType.length > 0 ? sessionType : DEFAULT_SESSION_TYPE,\n    code_language: \"\",\n    chat_prompt: \"\",\n    image_urls: null,\n    aliyun_user_type: \"\",\n    // 顶层 system 服务端会忽略，系统提示走 messages 里的 {role:\"system\"}。\n    system: \"\",\n    messages: Array.isArray(messages) ? messages : [],\n    tools: Array.isArray(tools) ? tools : [],\n    ...(toolChoice === undefined ? {} : { tool_choice: toolChoice }),\n    parameters,\n    chat_context: {\n      chatPrompt: \"\",\n      imageUrls: null,\n      extra: {\n        context: [],\n        modelConfig: { key: modelKey, is_reasoning: isReasoning === true },\n        originalContent: promptText,\n      },\n      features: [],\n      text: promptText,\n    },\n    model_config: { key: modelKey, source: \"system\" },\n    business: {\n      product: \"cli\",\n      version: \"1.0.0\",\n      type: \"agent\",\n      stage: \"start\",\n      id: requestId,\n      name: promptText.slice(0, 30),\n      begin_at: Date.now(),\n    },\n  };\n}\n\n/**\n * 上游对话客户端。\n *\n * `chatStream` 发一次 `POST /algo/api/v2/service/pro/sse/agent_chat_generation`，\n * 返回一个**已经把 Qoder 双层 SSE 翻成 OpenAI SSE** 的 ReadableStream，\n * 这样 shim 只要 pipe 出去就行。\n */\nexport function createQoderClient(options) {\n  const { tokens, logger, config } = options;\n  const gateway = () => String(config()?.gateway ?? DEFAULT_GATEWAY).replace(/\\/+$/, \"\");\n  const chatPath = () => {\n    const value = config()?.chatPath;\n    return typeof value === \"string\" && value.length > 0 ? value : DEFAULT_CHAT_PATH;\n  };\n  const chatUrl = () => `${gateway()}${chatPath()}`;\n\n  /**\n   * 发一次流式请求（内部会在凭据被上游拒绝时重试一次）。\n   *\n   * 返回 `{ok:true, response}` 或 `{ok:false, status, kind, message}`。\n   * 因为上游**总是**回 HTTP 200 + SSE（业务错误藏在信封的 `statusCodeValue` 里），\n   * 所以这里先读**首个有效事件**再决定成败，避免已经写出 200 才发现是错误。\n   *\n   * ## 为什么多一次重试（2026-10-08 修）\n   *\n   * jobToken 是**上游轮换**的：Qoder 桌面 App 重新登录、或另一台设备刷新会话后，\n   * 旧 token 会被立刻作废，而本机的快照文件（`connect-auth/qoder-session.json`）\n   * 可能还没被导出流程更新。此时第一次请求必然 401。\n   *\n   * 修之前的做法是 `tokens.invalidate()` 然后**直接把错误返回给用户** ——\n   * 于是表现为「有时能聊、有时整轮失败：API 密钥无效」，而下一轮又好了，\n   * 看起来像随机故障。DSH 前端把 401/403 一律显示成 `message.failure.auth`\n   * （\"API 密钥无效\"），所以文案与真实原因也对不上。\n   *\n   * 现在改成：凭据级失败 → 丢弃缓存 → 重新取一次 → **重试一次**。\n   * 只重试一次是刻意的：第二次仍失败说明是真的没凭据（如 PAT 被吊销），\n   * 再打上游只是浪费额度。\n   */\n  async function chatStream(request, signal) {\n    const url = chatUrl();\n    const body = buildChatBody({\n      modelKey: request.model,\n      messages: request.messages,\n      isReasoning: request.isReasoning,\n      // pi-ai 按 thinkingLevelMap 映射后下发的档位（未选/非法 → buildChatBody 回退：\n      // 未选 → 目录默认档；选了但不支持 → 支持集合最高档）。\n      reasoningEffort: request.reasoningEffort,\n      // 该模型支持的档位（声明 ∪ 探查），由 shim 算好传入。\n      supportedEfforts: request.supportedEfforts,\n      // 目录默认档：用户没选档时用它，而不是\"支持集合最高档\"。\n      defaultEffort: request.defaultEffort,\n      maxTokens: request.maxTokens,\n      tools: request.tools,\n      toolChoice: request.toolChoice,\n      temperature: request.temperature,\n      sessionId: request.sessionId,\n      sessionType: config()?.sessionType,\n    });\n\n    // 只有要发出去的字节才参与签名 —— 顺序不能反。\n    const encoded = qoderEncodeBody(Buffer.from(JSON.stringify(body), \"utf8\"));\n\n    /**\n     * 打一次，拿凭据与响应。返回 `{response}` 或 `{error}`（error 已是定稿形状）。\n     * 凭据级失败时**只报告**不重试 —— 重试决策留在 chatStream 里，\n     * 那里才知道该不该再来一次。\n     */\n    const attempt = async () => {\n      const credential = await tokens.get();\n      let response;\n      try {\n        response = await fetch(url, {\n          method: \"POST\",\n          headers: {\n            ...buildCosyHeaders(encoded, url, credential),\n            \"Content-Type\": \"application/json\",\n            Accept: \"text/event-stream\",\n            \"Cache-Control\": \"no-cache\",\n            \"Accept-Encoding\": \"identity\",\n            \"X-Model-Key\": request.model,\n          \"X-Model-Source\": \"system\",\n        },\n        body: encoded,\n        signal,\n      });\n    } catch (error) {\n      /**\n       * **返回形状必须与其它分支一致**（2026-10-08 修）。\n       *\n       * 这里原先直接返回裸的错误对象 `{ok:false, ...}`，而 `attempt()` 的其余\n       * 出口都是包好的 `{error:{...}}`。调用方只认后者：\n       *\n       *     if (outcome.error?.kind === \"auth\") { …重试… }\n       *     if (outcome.error !== undefined) return outcome.error;\n       *     return { ok: true, response: outcome.response };\n       *\n       * 于是网络失败（`outcome.error === undefined`）会掉进最后一行，变成\n       * `{ok:true, response:undefined}` —— shim 看到 ok 就写 200，\n       * 然后 `Readable.fromWeb(undefined)` 抛错，而响应头已经发出去了，\n       * 用户只看到一个空的 200。**顺带连 invalidate + 重试都不会发生。**\n       * 实测三种情形（网络失败、客户端取消、正常失败）都会走到这里。\n       */\n      const aborted = signal?.aborted === true;\n      return {\n        error: {\n          ok: false,\n          status: 0,\n          kind: aborted ? \"aborted\" : \"network\",\n          message: aborted ? \"客户端已取消\" : `连不上 Qoder 网关：${error instanceof Error ? error.message : String(error)}`,\n        },\n      };\n    }\n    if (!response.ok) {\n      const text = await response.text().catch(() => \"\");\n      /**\n       * HTTP 层的 403 **同样不能一律当凭据失效**（2026-10-08 补）。\n       *\n       * 上一版只修了信封路径，这里仍是 `auth = 401 || 403` 的文本盲判：\n       * 如果上游把额度错误放在 HTTP 层（而不是信封里），就会被标成 `kind:\"auth\"`，\n       * 于是 (a) 白白 invalidate + 重试一次，(b) 文案里带着 `403` 且**断言是凭据问题**，\n       * 前端照样显示「API 密钥无效」—— 额度提示永远出不来。\n       * 判据与信封路径共用 `isCredentialRejection` / `isQuotaRejection`。\n       */\n      const quotaLike = isQuotaRejection(text);\n      const auth = response.status === 401 || (response.status === 403 && !quotaLike && isCredentialRejection(text));\n      if (auth) tokens.invalidate();\n      return {\n        error: {\n          ok: false,\n          status: quotaLike ? 429 : response.status,\n          kind: auth ? \"auth\" : \"upstream\",\n          message: auth\n            ? `Qoder 拒绝了凭据（HTTP ${response.status}）：jobToken 可能已失效或 PAT 被吊销。${text.slice(0, 200)}`\n            : text.replace(/\\s+/g, \" \").slice(0, 400),\n        },\n      };\n    }\n    if (response.body === null) return { error: { ok: false, status: response.status, kind: \"upstream\", message: \"Qoder 返回了空响应体\" } };\n\n    const reader = response.body.getReader();\n    const parser = createSseReader();\n    /**\n     * 首个事件预读：若上游直接报错，就在写响应头之前变成正经的 HTTP 错误。\n     *\n     * ⚠️ **必须把这一批里剩余的事件一起带上**（2026-10-08 修，与 Trae 侧同一个坑）。\n     *\n     * `parser.push()` 返回**整批**已解析事件并清空内部队列，所以只接住第一个就等于\n     * 丢掉同批其余事件，而紧接着的 `parser.pending()` 只会拿到空数组 —— 实测\n     * 一个 TCP 分片含 3 个事件时，下游只收到 1 个，丢掉的可能是正文分片或 `[DONE]`。\n     * 生产环境一个分片常含多个事件，所以这不是理论问题。\n     *\n     * 现在把整批收下，交给 translate 按顺序回放（parser 也一并交接，见下）。\n     */\n    let initialEvents = [];\n    while (initialEvents.length === 0) {\n      const { done, value } = await reader.read();\n      if (done) break;\n      initialEvents = parser.push(value);\n    }\n    let first;\n    for (const event of initialEvents) {\n      const parsed = unwrapQoderEvent(event.raw);\n      if (parsed.kind === \"ignore\") continue;\n      first = parsed;\n      break;\n    }\n    if (first === undefined) return { error: { ok: false, status: 502, kind: \"upstream\", message: \"Qoder 流提前结束，没有读到任何事件\" } };\n    if (first.kind === \"error\") {\n      /**\n       * 业务错误也可能是凭据级：上游把 401/403 塞在信封的 `statusCodeValue` 里，\n       * HTTP 仍是 200（只看 HTTP 会把\"凭据失效\"误判成成功）。\n       * 这条路径**同样要能触发重试**，否则用户照样看到\"API 密钥无效\"。\n       *\n       * ⚠️ **403 不等于凭据失效**（2026-10-08 实测）：`code:110 / \"Billing daily\n       * count exceeded\"` 也是 403，那是当日调用次数超限，刷新 token 没有意义，\n       * 重试只是白花一次请求。所以只有 **401**，以及带明确失效语义的 403\n       * （\"token\"/\"credential\"/\"auth\"/\"unauthorized\"）才算凭据问题。\n       */\n      const code = typeof first.code === \"number\" ? first.code : undefined;\n      const authLike = code === 401 || (code === 403 && isCredentialRejection(first.message));\n      if (authLike) tokens.invalidate();\n      /**\n       * 额度/限流类不要把 403 原样带出去。\n       *\n       * 宿主是按**文案里的数字**分类的（`classifyPiAiError` 先匹配 `403` → `AUTH`），\n       * 而 `AUTH` 会把原文丢弃、只显示「API 密钥无效」。额度问题照原样上报就会\n       * 变成误导性的密钥报错，所以这里换成 429 —— 它会被正确识别成 `RATE_LIMIT`\n       * （429 分支在 AUTH 之后、但文案里已无 401/403 数字，见 writeOpenAIError 的渲染）。\n       */\n      const quotaLike = !authLike && isQuotaRejection(first.message);\n      return {\n        error: {\n          ok: false,\n          status: quotaLike ? 429 : code ?? 502,\n          kind: authLike ? \"auth\" : \"upstream\",\n          message: first.message,\n        },\n      };\n    }\n    if (first.kind === \"done\") return { error: { ok: false, status: 502, kind: \"upstream\", message: \"Qoder 只回了一个结束标记，没有正文\" } };\n    return { response: translate(reader, parser, initialEvents, request, signal) };\n    };\n\n    // 第一次；凭据被拒就丢缓存重来一次（最多两次，绝不更多）。\n    let outcome = await attempt();\n    if (outcome.error?.kind === \"auth\") {\n      tokens.invalidate();\n      logger?.warn?.(`dsh-qoder-connect: 凭据被拒（${outcome.error.status}），已丢弃缓存并重试一次`);\n      outcome = await attempt();\n    }\n    if (outcome.error !== undefined) return outcome.error;\n    return { ok: true, response: outcome.response };\n  }\n\n  /**\n   * 把已解析的 Qoder 事件流翻译成 OpenAI SSE 字节流。\n   *\n   * `parser` 由 `chatStream` 传进来**继续使用**，不在这里新建：首事件预读可能停在\n   * 某个事件中间（TCP 分片切在事件内），那些残片只存在于那个 parser 的 buffer 里，\n   * 换一个新 parser 就等于把它们丢掉（丢掉的可能是正文分片或 `[DONE]`）。\n   * `initialEvents` 是首读那一批的**全部**事件，按顺序回放，不能只回放第一个。\n   */\n  function translate(reader, parser, initialEvents, request, signal) {\n    const model = request.model;\n    const id = `chatcmpl-qoder-${randomBytes(8).toString(\"hex\")}`;\n    const created = Math.floor(Date.now() / 1000);\n    const encoder = new TextEncoder();\n    let usage;\n    let finished = false;\n\n    const chunk = (delta, finishReason) => {\n      const payload = {\n        id,\n        object: \"chat.completion.chunk\",\n        created,\n        model,\n        choices: [{ index: 0, delta, finish_reason: finishReason ?? null }],\n      };\n      if (finishReason !== undefined && finishReason !== null) {\n        // openai-completions 的解析器只在最后一帧读 usage，所以并到收尾帧里。\n        payload.usage = {\n          prompt_tokens: usage?.prompt_tokens ?? 0,\n          completion_tokens: usage?.completion_tokens ?? 0,\n          total_tokens: usage?.total_tokens ?? 0,\n        };\n      }\n      return encoder.encode(`data: ${JSON.stringify(payload)}\\n\\n`);\n    };\n\n    return new ReadableStream({\n      start(controller) {\n        // `finished` = 逻辑上收尾了；`closed` = 流真的关了。两者必须分开，\n        // 否则 done 事件里 close() 之后 pump() 结尾再 close() 会抛 ERR_INVALID_STATE。\n        let closed = false;\n        const closeStream = () => {\n          if (closed) return;\n          closed = true;\n          try { controller.close(); } catch { /* 下游已取消 */ }\n        };\n        const enqueue = (bytes) => {\n          if (closed) return;\n          try { controller.enqueue(bytes); } catch { closed = true; }\n        };\n        const emit = (parsed) => {\n          if (finished || closed) return;\n          if (parsed.kind === \"ignore\") return;\n          if (parsed.kind === \"error\") {\n            enqueue(chunk({ content: `\\n\\n[Qoder 错误] ${parsed.message}` }));\n            return;\n          }\n          if (parsed.kind === \"done\") {\n            finished = true;\n            enqueue(chunk({}, \"stop\"));\n            enqueue(encoder.encode(\"data: [DONE]\\n\\n\"));\n            closeStream();\n            return;\n          }\n          const inner = parsed.chunk;\n          if (inner?.usage !== undefined && inner.usage !== null) usage = inner.usage;\n          const choice = Array.isArray(inner?.choices) ? inner.choices[0] : undefined;\n          if (choice?.finish_reason !== undefined && choice.finish_reason !== null) {\n            finished = true;\n            const delta = deltaOf(inner) ?? {};\n            enqueue(chunk(delta, choice.finish_reason));\n            enqueue(encoder.encode(\"data: [DONE]\\n\\n\"));\n            closeStream();\n            return;\n          }\n          const delta = deltaOf(inner);\n          if (delta !== undefined) enqueue(chunk(delta));\n        };\n\n        const pump = async () => {\n          try {\n            // 首读那一批的全部事件，按原顺序回放（只回放第一个会丢掉同批其余事件）。\n            for (const event of initialEvents) emit(unwrapQoderEvent(event.raw));\n            while (!finished && !closed) {\n              const { done, value } = await reader.read();\n              if (done) break;\n              for (const event of parser.push(value)) emit(unwrapQoderEvent(event.raw));\n            }\n            /**\n             * 流读完先冲一次残留（2026-10-08 加）：最后一个事件没有尾随空行时\n             * 会一直留在 buffer 里 —— 被截断的流最容易缺这个空行，而丢掉的\n             * 可能是 `[DONE]`／收尾帧，于是\"正常结束\"与\"被截断\"分不出来。\n             */\n            if (!finished && !closed) {\n              for (const event of parser.end()) emit(unwrapQoderEvent(event.raw));\n            }\n            if (!finished) {\n              finished = true;\n              enqueue(chunk({}, \"stop\"));\n              enqueue(encoder.encode(\"data: [DONE]\\n\\n\"));\n            }\n            closeStream();\n          } catch (error) {\n            logger?.warn?.(`dsh-qoder-connect: 上游流中断：${error instanceof Error ? error.message : String(error)}`);\n            if (!finished) {\n              finished = true;\n              enqueue(chunk({}, \"stop\"));\n              enqueue(encoder.encode(\"data: [DONE]\\n\\n\"));\n            }\n            closeStream();\n          }\n        };\n\n        if (signal?.aborted === true) { finished = true; closeStream(); return; }\n        pump();\n      },\n      cancel() {\n        finished = true;\n        reader.cancel().catch(() => {});\n      },\n    });\n  }\n\n  return { chatStream };\n}\n\n//#endregion\n//#region 账号侧客户端（额度 + 签到活动）\n\n/**\n * OpenAPI 平面：普通 `Bearer <jobToken>` + `Cosy-ClientType`，**不需要 COSY 签名**。\n *\n * App 实际还多带 `Cosy-Version: <App 版本>` 与一整组 `Cosy-Machine*`（机器身份）。\n * 已实测**这些都不是必需的**：在 `Cosy-ClientType: 10` 的前提下逐个叠加它们，\n * 签到活动的返回没有任何变化（`scripts/qoder-campaign-headers-probe.mjs`）。\n * 所以这里保持最小头集，不引入机器身份（它在容器里根本拿不到）。\n */\nfunction openApiHeaders(jobToken) {\n  return {\n    Accept: \"application/json\",\n    Authorization: `Bearer ${jobToken}`,\n    \"Cosy-ClientType\": COSY_OPENAPI_CLIENT_TYPE,\n    \"User-Agent\": \"Qoder\",\n  };\n}\n\n/**\n * 额度与「签到」。\n *\n * 两条额度来源：\n *   1. `GET /sash/api/v2/me/usage`   —— **App 自己**用的那条（OpenAPI 平面），\n *      返回 `{displayMode, qoderUsage:{userType,userQuota:{used,total,percentage},…}}`。\n *   2. `GET /api/v2/quota/usage`     —— 社区参考实现那条（COSY 平面），\n *      返回 `{userQuota:{total,used,remaining,percentage,unit},…}`。\n *\n * 先打 1，失败回落到 2；两条都挂就抛，由状态文档降级成 `quotaError`。\n *\n * 签到：Qoder CN 有**每日活动**（App 左下角用量面板里的礼物图标，「每天领 100 Credits」，\n * 每日 10:00 (UTC+8) 刷新、奖励 30 天有效）。状态是\n * `GET /sash/api/v1/me/campaigns` → `{showCampaign, claimable, campaignUrl, campaigns[]}`。\n *\n * ⚠️ 这个端点**按 `Cosy-ClientType` 门控**，见 `COSY_OPENAPI_CLIENT_TYPE` ——\n * 客户端类型不对时它不报错，只回一份\"没有任何活动\"的空文档。\n *\n * **领取是可以调的**：`POST /sash/api/v1/me/campaigns/<campaignId>/claim`。\n * 这条路径是活动页自己拼出来的（活动页 JS 在公开 CDN 上：\n * `g.alicdn.com/qbase/qoder/<版本>/growth-page/activity-iframe/activity-iframe.js`），\n * 它把请求交给 App 的授权桥转发。因为它由 `${id}` 拼成，**在本地包里静态搜\n * `/sash/api/...` 字符串搜不到** —— 早先据此得出过\"没有领取接口、只能只读\"的错误结论。\n */\nexport function createQoderAccountClient(options) {\n  const { tokens, config, logger } = options;\n  const openapiBase = () => String(config()?.openapiBase ?? DEFAULT_OPENAPI).replace(/\\/+$/, \"\");\n  const TIMEOUT_MS = 20000;\n\n  /**\n   * 打 OpenAPI 平面。失败一律抛，由调用方决定降级方式。\n   *\n   * `options.method` / `options.body` 供**写**请求用（目前只有签到领取那条 POST）。\n   * 不传就是原来的 GET，行为不变。\n   */\n  async function getOpenApi(path, label, credential, options) {\n    const url = `${openapiBase()}${path}`;\n    const hasBody = options?.body !== undefined;\n    let response;\n    try {\n      response = await fetch(url, {\n        method: options?.method ?? \"GET\",\n        headers: hasBody\n          ? { ...openApiHeaders(credential.jobToken), \"Content-Type\": \"application/json\" }\n          : openApiHeaders(credential.jobToken),\n        ...(hasBody ? { body: options.body } : {}),\n        signal: AbortSignal.timeout(TIMEOUT_MS),\n      });\n    } catch (error) {\n      throw new Error(`${label} 连不上 ${openapiBase()}：${error instanceof Error ? error.message : String(error)}`);\n    }\n    const text = await response.text().catch(() => \"\");\n    if (!response.ok) {\n      if (response.status === 401 || response.status === 403) tokens.invalidate();\n      throw new Error(`${label} 返回 HTTP ${response.status}：${text.replace(/\\s+/g, \" \").slice(0, 200)}`);\n    }\n    try {\n      return JSON.parse(text);\n    } catch {\n      throw new Error(`${label} 返回的不是 JSON：${text.slice(0, 200)}`);\n    }\n  }\n\n  /** 打 COSY 平面（备用额度来源）。 */\n  async function getCosy(path, label, credential) {\n    const url = `${openapiBase()}${path}`;\n    const response = await fetch(url, {\n      headers: { ...buildCosyHeaders(null, url, credential), Accept: \"application/json\", \"User-Agent\": \"dsh-qoder-connect\" },\n      signal: AbortSignal.timeout(TIMEOUT_MS),\n    });\n    if (!response.ok) {\n      throw new Error(`${label} 返回 HTTP ${response.status}：${(await response.text().catch(() => \"\")).slice(0, 200)}`);\n    }\n    return response.json();\n  }\n\n  /** 「已用 / 总额 / 百分比」→ 统一形状。`total` 为 0 表示不限量。 */\n  function shapeQuota(source, parts) {\n    const used = toNumber(parts.used);\n    const total = toNumber(parts.total);\n    const remaining = toNumber(parts.remaining) ?? (total !== undefined && used !== undefined ? Math.max(0, total - used) : undefined);\n    let percentage = toNumber(parts.percentage);\n    // 有的实现给 0..1 的比例，有的给 0..100 的百分数 —— 统一成 0..1。\n    if (percentage !== undefined && percentage > 1) percentage /= 100;\n    if (percentage === undefined && total !== undefined && total > 0 && used !== undefined) percentage = used / total;\n    return {\n      source,\n      used,\n      total,\n      remaining,\n      percentage,\n      unit: typeof parts.unit === \"string\" ? parts.unit : undefined,\n      unlimited: total === 0,\n    };\n  }\n\n  /** App 那条：`displayMode === \"enterprise\"` 时没有可用数字，只有外链。 */\n  function shapeAccountUsage(doc) {\n    if (doc?.displayMode === \"enterprise\") {\n      const detail = doc?.enterpriseUsage;\n      return {\n        source: \"account-usage\",\n        enterprise: true,\n        detailUrl: typeof detail?.detailUrl === \"string\" ? detail.detailUrl : undefined,\n        unlimited: false,\n      };\n    }\n    const usage = doc?.qoderUsage;\n    if (usage === null || typeof usage !== \"object\") throw new Error(\"额度接口没有返回 qoderUsage\");\n    const user = usage.userQuota ?? {};\n    const addOn = usage.addOnQuota === null || usage.addOnQuota === undefined ? {} : usage.addOnQuota;\n    const addOnTotal = toNumber(addOn.total);\n    const addOnUsed = toNumber(addOn.used);\n    const addOnRemaining = addOnTotal === undefined || addOnUsed === undefined ? undefined : Math.max(0, addOnTotal - addOnUsed);\n\n    /**\n     * [dsh-connect 2026-09-24 修正] 主额度要把**加油包**算进来。\n     *\n     * 实测 personal_standard 账号：`userQuota = {total:0, used:0}` 而\n     * `addOnQuota = {total:100, used:0}` —— 只读 userQuota 会得到 0/0，\n     * 而 `unlimited: total === 0` 就把它显示成\"不限量\"（用户一眼看出不对）。\n     * 合并成\"总可用 = 主额度 + 加油包\"才是这个面板该显示的账。\n     */\n    const sum = (a, b) => {\n      const left = toNumber(a);\n      const right = toNumber(b);\n      if (left === undefined) return right;\n      if (right === undefined) return left;\n      return left + right;\n    };\n\n    const shaped = shapeQuota(\"account-usage\", {\n      used: sum(user.used, addOnUsed),\n      total: sum(user.total, addOnTotal),\n      // 不传 percentage：合并后按 used/total 重算，避免\"主额度占比\"与合并后的账不一致。\n      unit: typeof user.unit === \"string\" ? user.unit : addOn.unit,\n    });\n    return {\n      ...shaped,\n      enterprise: false,\n      userType: typeof usage.userType === \"string\" ? usage.userType : undefined,\n      /** 加油包剩余（单独留一份，便于 UI 细分）。 */\n      addOnRemaining,\n      addOnTotal,\n      /** 组织资源包（有些账号有）。 */\n      orgUsed: usage.orgResourcePackage === null || usage.orgResourcePackage === undefined\n        ? undefined\n        : toNumber(usage.orgResourcePackage.used),\n    };\n  }\n\n  return {\n    /** 额度。两条来源依次尝试，都失败才抛。 */\n    async fetchQuota(credential) {\n      const errors = [];\n      try {\n        return shapeAccountUsage(await getOpenApi(PATH_ACCOUNT_USAGE, \"额度\", credential));\n      } catch (error) {\n        errors.push(error instanceof Error ? error.message : String(error));\n      }\n      try {\n        const doc = await getCosy(PATH_QUOTA_LEGACY, \"额度(备用)\", credential);\n        const user = doc?.userQuota ?? {};\n        if (user.total === undefined && user.used === undefined && user.remaining === undefined) {\n          throw new Error(\"备用额度接口没有返回 userQuota\");\n        }\n        return {\n          ...shapeQuota(\"quota-usage\", { used: user.used, total: user.total, remaining: user.remaining, percentage: user.percentage, unit: user.unit }),\n          enterprise: false,\n          isQuotaExceeded: doc?.isQuotaExceeded === true,\n          expiresAt: typeof doc?.expiresAt === \"string\" ? doc.expiresAt : undefined,\n        };\n      } catch (error) {\n        errors.push(error instanceof Error ? error.message : String(error));\n      }\n      throw new Error(errors.join(\" ／ \"));\n    },\n\n    /**\n     * 「签到」状态。只读。\n     *\n     * ⚠️ 这个端点是**按 `Cosy-ClientType` 门控**的（见 `COSY_OPENAPI_CLIENT_TYPE`）：\n     * 客户端类型不对时它不报错，只回一份「没有任何活动」的空文档，与\"账号真没活动\"\n     * 无法区分。历史上就是在这里被误导过。\n     *\n     * `campaigns[]` 才是权威细节（`claimStatus` 有 CLAIMABLE / CLAIMED / 过期等），\n     * `claimable` / `showCampaign` 只是服务端汇总。读得到 `campaigns` 就优先按它判，\n     * 读不到再退回汇总字段。\n     */\n    async fetchCampaign(credential) {\n      let doc;\n      try {\n        doc = await getOpenApi(PATH_CAMPAIGNS, \"签到活动\", credential);\n      } catch (error) {\n        const message = error instanceof Error ? error.message : String(error);\n        if (message.includes(\"HTTP 404\")) {\n          return { supported: false, showCampaign: false, claimable: false, reason: \"当前账号没有签到活动\" };\n        }\n        throw error;\n      }\n      const showCampaign = doc?.showCampaign === true;\n      const claimable = doc?.claimable === true;\n      const campaignUrl = typeof doc?.campaignUrl === \"string\" && doc.campaignUrl.trim().length > 0 ? doc.campaignUrl.trim() : undefined;\n      const campaigns = Array.isArray(doc?.campaigns) ? doc.campaigns : [];\n      /** 可领的那一条：动作类型必须是「领奖励」，且服务端标了 CLAIMABLE，且 id 可用。 */\n      const target = campaigns.find(\n        (c) =>\n          c?.actionType === \"CLAIM_BENEFIT\" &&\n          c?.claimStatus === \"CLAIMABLE\" &&\n          typeof c?.campaignId === \"string\" &&\n          c.campaignId.length > 0,\n      );\n      /** 「今天已经领过」的证据：有领奖励类活动但不是 CLAIMABLE。用于区分「已签」与「没活动」。 */\n      const claimedToday = campaigns.some((c) => c?.actionType === \"CLAIM_BENEFIT\" && c?.claimStatus === \"CLAIMED\");\n      const reward =\n        target?.benefit?.kind === \"CREDITS\" && Number.isFinite(target.benefit.amount) ? target.benefit.amount : undefined;\n      if (!showCampaign && !claimable) {\n        return { supported: true, showCampaign: false, claimable: false, claimedToday, campaigns, reason: \"当前账号没有进行中的签到活动\" };\n      }\n      return {\n        supported: true,\n        showCampaign,\n        // 「能不能领」以**能不能真领**为准，不看服务端汇总。\n        claimable: Boolean(target) || claimable,\n        claimedToday,\n        /** 可直接领取的那条活动（没有就是 undefined）。领取时要用它的 campaignId。 */\n        campaign: target,\n        campaigns,\n        campaignUrl,\n        reward,\n        claimableHere: Boolean(target),\n        reason: target\n          ? `Qoder CN 今日有可领取的奖励${reward === undefined ? \"\" : `（+${reward} credits）`}，可直接在本面板领取。`\n          : \"今日签到已完成或暂不可领。\",\n      };\n    },\n\n    /**\n     * 领取。**永远不假装成功** —— 直接把「去哪儿领」告诉调用方。\n     * 保留成异步是为了让路由对 GET/POST 一视同仁。\n     */\n    async claimCampaign(credential) {\n      let campaign;\n      try {\n        campaign = await this.fetchCampaign(credential);\n      } catch (error) {\n        return { state: \"failed\", message: error instanceof Error ? error.message : String(error) };\n      }\n      if (campaign.supported === false) return { state: \"unsupported\", message: campaign.reason ?? \"当前账号没有签到活动\" };\n      const target = campaign.campaign;\n      if (target === undefined) {\n        // 有活动但今天没得领 → 已签；连活动开关都没有 → 这个账号就没有活动。\n        // ⚠️ 这两支必须分开：把「没有活动」报成 already-claimed 会被 normalizeClaim\n        // 映射成 done，界面显示\"已签到\"却看不到积分增加（2026-09-27 踩过）。\n        if (campaign.showCampaign === true || campaign.claimedToday === true) return { state: \"already-claimed\", campaign };\n        return { state: \"unsupported\", message: campaign.reason ?? \"当前账号没有进行中的签到活动\" };\n      }\n      // 真领取。端点与形状来自活动页自己的 JS（见 createQoderAccountClient 的函数头注释）。\n      const path = `${PATH_CAMPAIGNS}/${encodeURIComponent(target.campaignId)}/claim`;\n      try {\n        await getOpenApi(path, \"签到领取\", credential, { method: \"POST\", body: \"{}\" });\n      } catch (error) {\n        const message = error instanceof Error ? error.message : String(error);\n        // 404/410 = 活动已下线或窗口已过；这不是\"故障\"，按已结束处理。\n        if (message.includes(\"HTTP 404\") || message.includes(\"HTTP 410\")) {\n          return { state: \"already-claimed\", campaign, message: \"领取窗口已结束或活动已下线\" };\n        }\n        // 上游明说「已领过 / 不符合条件」时也按已领处理（幂等重试的常见返回）。\n        if (/已领取|已经领取|重复领取|not\\s*eligible|already/i.test(message)) {\n          return { state: \"already-claimed\", campaign, message: \"今日奖励已领取过\" };\n        }\n        return { state: \"failed\", message };\n      }\n      return {\n        state: \"claimed\",\n        campaign,\n        message: campaign.reward === undefined ? \"已领取今日奖励\" : `已领取 +${campaign.reward} credits`,\n      };\n    },\n  };\n}\n\n//#endregion\n//#region 回环 shim\n\nfunction writeOpenAIError(res, status, code, message) {\n  writeJson(res, status, { error: { message, type: code, code } });\n}\n\n/**\n * OpenAI → Qoder 的消息转换。\n *\n * Qoder 的请求是 OpenAI 形状，所以这里基本是透传 + 清洗：\n *   · `system` 保持独立角色（顶层 `system` 字段服务端会忽略）\n *   · 图片 `image_url` 原样保留\n *   · `assistant.tool_calls` 与 `role:\"tool\"` 原样保留\n */\nexport function toQoderMessages(messages) {\n  const out = [];\n  for (const message of Array.isArray(messages) ? messages : []) {\n    if (message === null || typeof message !== \"object\") continue;\n    let role = typeof message.role === \"string\" ? message.role : \"user\";\n    /**\n     * `developer` → `system`。\n     *\n     * OpenAI 新惯例把系统提示的角色拼写从 `system` 改成 `developer`，pi-ai 对\n     * **声明了 reasoning 的模型**会用新拼写发来（旧实现全部 `reasoning:false`，\n     * 走老路径，所以此前从没见过这个角色）。Qoder 上游只认\n     * `system/assistant/user/tool/function`，收到 `developer` 直接 400：\n     *   \"developer is not one of ['system', 'assistant', 'user', 'tool', 'function']\"\n     * 两者语义等同（都是系统指令），归一化即可，不丢内容。\n     */\n    if (role === \"developer\") role = \"system\";\n    /** @type {Record<string, unknown>} */\n    const next = { role };\n    if (typeof message.content === \"string\") {\n      next.content = message.content;\n    } else if (Array.isArray(message.content)) {\n      next.content = message.content\n        .map((part) => {\n          if (part?.type === \"text\" && typeof part.text === \"string\") return { type: \"text\", text: part.text };\n          if (part?.type === \"image_url\" && part.image_url?.url) return { type: \"image_url\", image_url: { url: part.image_url.url } };\n          return undefined;\n        })\n        .filter((part) => part !== undefined);\n    } else {\n      next.content = \"\";\n    }\n    if (Array.isArray(message.tool_calls) && message.tool_calls.length > 0) next.tool_calls = message.tool_calls;\n    if (typeof message.tool_call_id === \"string\") next.tool_call_id = message.tool_call_id;\n    if (typeof message.name === \"string\") next.name = message.name;\n    out.push(next);\n  }\n  if (out.length === 0) out.push({ role: \"user\", content: \"\" });\n  return out;\n}\n\n/** 把 OpenAI 的 tools 原样透传（Qoder 的请求就是 OpenAI 形状）。 */\nfunction toQoderTools(tools) {\n  if (!Array.isArray(tools)) return [];\n  return tools\n    .filter((tool) => tool?.type === \"function\" && typeof tool.function?.name === \"string\")\n    .map((tool) => ({\n      type: \"function\",\n      function: {\n        name: tool.function.name,\n        ...(typeof tool.function.description === \"string\" ? { description: tool.function.description } : {}),\n        parameters: tool.function.parameters ?? { type: \"object\", properties: {} },\n        ...(typeof tool.function.strict === \"boolean\" ? { strict: tool.function.strict } : {}),\n      },\n    }));\n}\n\n/** 解码模型 id 里可选的后缀：`<key>@think` 强制开思考、`@nothink` 强制关。 */\nexport function decodeModelId(raw, fallback) {\n  const id = typeof raw === \"string\" ? raw : \"\";\n  if (id.endsWith(\"@think\")) return { model: id.slice(0, -\"@think\".length), thinking: true };\n  if (id.endsWith(\"@nothink\")) return { model: id.slice(0, -\"@nothink\".length), thinking: false };\n  return { model: id, thinking: fallback };\n}\n\n/**\n * 回环 OpenAI shim。与另外两条渠道同构：随机端口 + 随机 bearer，\n * 只服务三个路由；上游换成 Qoder 客户端。\n */\nexport function createQoderShim(options) {\n  const { client, catalog } = options;\n  const logger = options.logger;\n  /**\n   * 探查服务用**可后挂**的方式注入：它在 `apply` 里晚于 shim 创建（要读 catalog），\n   * 但请求处理要用它来判断\"该模型是否支持思考\"。用可变引用而不是构造参数，\n   * 是为了避开 `const` 的 TDZ 陷阱。\n   */\n  let probe = options.probe;\n  /** 每次启动换一份共享密钥；只在 127.0.0.1 上用。 */\n  const SHARED_SECRET = randomBytes(32).toString(\"base64url\");\n\n  function bearerOk(req) {\n    const header = req.headers.authorization;\n    if (typeof header !== \"string\") return false;\n    const match = /^Bearer\\s+(.+)$/i.exec(header.trim());\n    if (match === null) return false;\n    const given = Buffer.from(match[1]);\n    const expected = Buffer.from(SHARED_SECRET);\n    return given.length === expected.length && timingSafeEqual(given, expected);\n  }\n\n  const server = createServer((req, res) => { handle(req, res); });\n  const ready = new Promise((resolve, reject) => {\n    server.once(\"listening\", () => resolve());\n    server.once(\"error\", reject);\n  });\n  server.listen(0, \"127.0.0.1\");\n  const baseUrl = () => {\n    const address = server.address();\n    if (address === null || typeof address === \"string\") throw new Error(\"dsh-qoder-connect: shim 没有监听地址\");\n    return `http://127.0.0.1:${address.port}`;\n  };\n\n  async function handle(req, res) {\n    try {\n      if (!hostIsLoopback(req.headers.host)) { writeOpenAIError(res, 403, \"host_not_allowed\", \"Host 必须是回环地址\"); return; }\n      if (!originIsLoopback(req.headers.origin)) { writeOpenAIError(res, 403, \"origin_not_allowed\", \"Origin 必须是回环地址\"); return; }\n      if (!bearerOk(req)) { writeOpenAIError(res, 401, \"unauthorized\", \"Authorization bearer 缺失或不匹配\"); return; }\n      const url = req.url ?? \"/\";\n      if (req.method === \"GET\" && (url === \"/healthz\" || url === \"/healthz/\")) { writeJson(res, 200, { ok: true }); return; }\n      if (req.method === \"GET\" && (url === \"/v1/models\" || url === \"/v1/models/\")) {\n        writeJson(res, 200, {\n          object: \"list\",\n          data: catalog.current().map((model) => ({ id: model.id, object: \"model\", created: 0, owned_by: QODER_PROVIDER })),\n        });\n        return;\n      }\n      if (req.method === \"POST\" && (url === \"/v1/chat/completions\" || url === \"/v1/chat/completions/\")) { await chatCompletions(req, res); return; }\n      writeOpenAIError(res, 404, \"not_found\", `no such route: ${req.method} ${url}`);\n    } catch (error) {\n      if (!res.headersSent) writeOpenAIError(res, 500, \"internal\", String(error));\n      else res.end();\n    }\n  }\n\n  async function chatCompletions(req, res) {\n    if (typeof req.headers[\"content-type\"] !== \"string\" || !req.headers[\"content-type\"].toLowerCase().includes(\"application/json\")) {\n      writeOpenAIError(res, 415, \"unsupported_media_type\", \"Content-Type 必须是 application/json\");\n      return;\n    }\n    /**\n     * 取消接线：客户端断开时 abort 上游。\n     *\n     * 判据是 `res` 的 `'close'`（不是 `req` 的）—— `req` 的 `'close'` 在请求体\n     * 读完时就触发，会让**每个正常请求**都被 abort 成 499「客户端已取消」。\n     * 详见 {@link abortOnClientDisconnect}。\n     */\n    const controller = new AbortController();\n    abortOnClientDisconnect(res, controller);\n    let request;\n    try {\n      request = JSON.parse((await readBody(req)).toString(\"utf8\"));\n    } catch {\n      writeOpenAIError(res, 400, \"invalid_json\", \"请求体不是合法 JSON\");\n      return;\n    }\n    const decoded = decodeModelId(request.model, undefined);\n    const entry = catalog.find(decoded.model);\n    /**\n     * 是否开思考 —— **不能只看 `entry.isReasoning`**。\n     *\n     * `is_reasoning` 的含义是\"是否**专用**思考模型\"：DeepSeek-Flash / Kimi-K3\n     * 都是 false，但它们**支持思考档位**（上游在 `thinking_config` 里声明了 efforts）。\n     * 只看它会让这些模型永远走不到 `enable_thinking: true`，档位形同虚设。\n     *\n     * 判据（与模型描述符的 `reasoningFieldsFor` 保持一致）：\n     *   · 用户显式指定（`@nothink` 后缀或 `reasoning_effort`）以用户为准；\n     *   · 否则看目录：声明了档位 ⇒ 该模型支持思考；实测探查结论 validating 也算。\n     */\n    const supportsThinking = Array.isArray(entry?.declaredEfforts) && entry.declaredEfforts.length > 0;\n    const requestedEffort = typeof request.reasoning_effort === \"string\" && request.reasoning_effort.length > 0;\n    // 探查实测为 validating 也算\"支持思考\"（上游没声明、但实测接受档位的情形）。\n    const probed = probe?.service?.cached(decoded.model)?.validation === \"validating\";\n    const isReasoning = decoded.thinking ?? (requestedEffort || supportsThinking || probed || entry?.isReasoning === true);\n\n    /**\n     * 取消接线在函数入口已注册（见上），这里不再重复注册 —— 也不该在这里注册：\n     * 此刻请求体已读完，`req` 的 `'close'` 早已触发过一遍。\n     */\n\n    let result;\n    try {\n      result = await client.chatStream({\n        model: decoded.model,\n        messages: toQoderMessages(request.messages),\n        tools: toQoderTools(request.tools),\n        toolChoice: request.tool_choice,\n        isReasoning,\n        /**\n         * 用户选的思考档位。pi-ai 依据模型的 `thinkingLevelMap` 把 UI 档位映射成\n         * 线上拼写，放在请求体的 `reasoning_effort` 里发到 shim —— 这里读出来\n         * 透传给上游（WorkBuddy 那条渠道也是同一机制）。\n         */\n        reasoningEffort: typeof request.reasoning_effort === \"string\" ? request.reasoning_effort : undefined,\n        /**\n         * 该模型**确实支持**的档位（声明 ∪ 探查），供 `buildChatBody` 决定\n         * 非法输入该回退到哪一档。传进来而不是让 buildChatBody 自己去查，\n         * 是为了保持它是个纯函数（它不知道 catalog / probe）。\n         */\n        supportedEfforts: supportedEffortsOf(entry, probed ? probe?.service?.cached(decoded.model) : undefined),\n        // 目录默认档（thinking_config 里 is_default 的那档）：未选档时的回退目标。\n        defaultEffort: entry?.defaultEffort,\n        maxTokens: request.max_tokens ?? request.max_completion_tokens,\n        temperature: request.temperature,\n      }, controller.signal);\n    } catch (error) {\n      writeOpenAIError(res, 401, \"not_signed_in\", error instanceof Error ? error.message : String(error));\n      return;\n    }\n\n    if (!result.ok) {\n      const status = result.kind === \"auth\" ? 401 : result.kind === \"aborted\" ? 499 : 502;\n      writeOpenAIError(res, status, result.kind, describeUpstreamFailure(result.status, result.message));\n      return;\n    }\n    res.writeHead(200, {\n      \"Content-Type\": \"text/event-stream\",\n      \"Cache-Control\": \"no-cache\",\n      \"Connection\": \"keep-alive\",\n      \"X-Accel-Buffering\": \"no\",\n    });\n    let sawDone = false;\n    const body = Readable.fromWeb(result.response);\n    body.on(\"data\", (chunk) => { if (chunk.includes(\"[DONE]\")) sawDone = true; });\n    body.on(\"error\", (error) => {\n      logger?.warn?.(`dsh-qoder-connect: 上游流中断：${error instanceof Error ? error.message : String(error)}`);\n      if (!sawDone && res.writable) res.end(\"data: [DONE]\\n\\n\");\n    });\n    body.pipe(res);\n  }\n\n  return {\n    ready,\n    baseUrl,\n    token: () => SHARED_SECRET,\n    /** 后挂探查服务（见上方 `probe` 变量的说明）。 */\n    setProbe: (next) => { probe = next; },\n    close: () => new Promise((resolve, reject) => {\n      server.close(() => resolve());\n      server.closeAllConnections();\n      server.once(\"error\", reject);\n    }),\n  };\n}\n\n//#endregion\n//#region 适配器\n\n/** pi-ai 的 auth 平面在本插件里必须惰性：认证只走 shim 的共享密钥。 */\nconst INERT_AUTH = {\n  credentials: {\n    async read() {},\n    async list() { return []; },\n    async modify() { throw new Error(\"dsh-qoder-connect: the qoder route has no pi-ai credential lifecycle\"); },\n    async delete() {},\n  },\n  authContext: {\n    async env() {},\n  },\n};\n\n/** pi-ai 模型描述里要显式写 0，否则计费面板会按未知价格处理。 */\nconst NO_COST = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 };\nconst REQUEST_IMAGE_BUDGETS = {\n  maxRequestImageBytes: 20971520,\n  requestImagePixelBudget: 4194304,\n  requestImageMaxBytes: 1048576,\n};\nconst QODER_STREAM_IDLE_TIMEOUT_MS = 300000;\n\n/**\n * ── 推理等级探查（Qoder）────────────────────────────────────────────────\n *\n * Qoder 的模型目录只给 `is_reasoning` 布尔，**不声明支持哪些档位** ——\n * 所以它和 WorkBuddy 一样属于\"必须探查\"的渠道（Trae 相反：目录里直接\n * 按 (模型 × function) 声明了 options，无需探查）。\n *\n * 这里复用渠道无关的 {@link probeModel} 哨兵拒绝法。它能用的前提是\n * **上游会拒绝非法值** —— Qoder 实测确实如此（2026-10-06）：\n *\n * | 发送值 | 上游 |\n * |---|---|\n * | 不发该字段 | 200 |\n * | minimal/low/medium/high/max | 200 |\n * | `off` | **400** |\n * | 乱填（哨兵对照） | **400** |\n *\n * 对照组被拒是关键：证明上游在校验，而不是\"传什么都收\"。\n * （对照 Trae：乱填同样 200 → 哨兵法对它无效，所以 Trae 走目录声明。）\n */\nconst QODER_PROBE_FILENAME = \".qoder-probe.json\";\nconst QODER_PROBE_FORMAT_VERSION = 1;\n\n/**\n * 探查用的进程内密钥。\n *\n * 为什么需要它：探查会**花真实额度**（哨兵 + 逐档扫描会发多个请求），\n * 只靠\"回环 Host\"这层守卫不够 —— DNS rebinding 下任意本地页面都能发同源请求，\n * 而 Host 就是本机、拦不住。所以状态文档下发一个每次启动都换的随机 key，\n * POST 探查时必须带上。与 WorkBuddy 同机制（随机 key + 常量时间比较）。\n */\nfunction createQoderProbeKey() {\n  return randomBytes(24).toString(\"hex\");\n}\n\n/** 常量时间比较；长度不符即失败，不抛。 */\nfunction probeKeyMatches(expected, presented) {\n  if (typeof presented !== \"string\" || presented.length !== expected.length) return false;\n  return timingSafeEqual(Buffer.from(expected), Buffer.from(presented));\n}\n\n/** 判定\"这次尝试是否被上游接受\"。 */\nfunction probeIsAcceptance(attempt) {\n  return attempt?.status === 200;\n}\n/**\n * 判定\"这次尝试是否属于**归因明确**的档位拒绝\"。\n *\n * 只有 400 才算：401 是凭据问题、502 是网关问题，把它们当成\"档位被拒\"会得出\n * 完全错误的结论（会把\"登录过期\"报告成\"这个档位不支持\"）。\n */\nfunction probeIsEffortRejection(attempt) {\n  return attempt?.status === 400;\n}\n\n/**\n * 发一次探查请求。\n *\n * **不能走 `client.chatStream`**：它把上游业务错误统一包成 `status: 502`\n * （见 `chatStream` 的 `first.kind === \"error\"` 分支），400 与 502 就分不清了，\n * 而探查的全部意义正是区分它们。所以这里自己发一次、只读首个事件取真实状态码。\n */\nasync function sendQoderProbe({ tokens, config, logger }, modelId, effort, signal) {\n  const credential = await tokens.get();\n  const body = buildChatBody({\n    modelKey: modelId,\n    messages: [{ role: \"user\", content: \"ping\" }],\n    isReasoning: true,\n    // 探查专用：原样透传（含哨兵值），不做白名单回退。\n    reasoningEffortExact: effort === undefined ? undefined : effort,\n    maxTokens: 16,\n    sessionType: config()?.sessionType,\n  });\n  if (effort === undefined) delete body.parameters.reasoning_effort;\n\n  const url = `${String(config()?.gateway ?? DEFAULT_GATEWAY).replace(/\\/+$/, \"\")}${DEFAULT_CHAT_PATH}?FetchKeys=llm_model_result&AgentId=agent_common&Encode=1`;\n  const encoded = qoderEncodeBody(Buffer.from(JSON.stringify(body), \"utf8\"));\n  const res = await fetch(url, {\n    method: \"POST\",\n    headers: {\n      ...buildCosyHeaders(encoded, url, credential),\n      \"Content-Type\": \"application/json\",\n      Accept: \"text/event-stream\",\n      \"Accept-Encoding\": \"identity\",\n      \"X-Model-Key\": modelId,\n      \"X-Model-Source\": \"system\",\n    },\n    body: encoded,\n    signal,\n  });\n  if (!res.ok) {\n    // 上游在 HTTP 层就拒了（400 就在这里）。\n    await res.text().catch(() => \"\");\n    return { status: res.status };\n  }\n  /**\n   * 200 也要读首个事件：Qoder 会把业务错误塞在信封的 `statusCodeValue` 里\n   * （HTTP 仍是 200）。只看 HTTP 会把\"业务拒绝\"误判成\"接受\"。\n   */\n  const text = await res.text().catch(() => \"\");\n  const match = text.match(/\"statusCodeValue\"\\s*:\\s*(\\d+)/);\n  const bizCode = match === null ? undefined : Number(match[1]);\n  if (bizCode !== undefined && bizCode >= 400) return { status: bizCode };\n  return { status: 200 };\n}\n\n/** 组装 Qoder 的探查运行器 + 存储，供路由与适配器共用。 */\nexport function createQoderProbe(options) {\n  const { tokens, config, catalog, logger } = options;\n  // 每次启动换一份；只随状态文档下发给同源页面，POST 探查时必须回传。\n  const key = createQoderProbeKey();\n  const store = new ProbeStore({\n    path: join(resolveDshHome(), QODER_PROBE_FILENAME),\n    version: QODER_PROBE_FORMAT_VERSION,\n    logger,\n  });\n  const service = new ProbeService({\n    consent: options.consent,\n    catalog: () => catalog.current(),\n    account: () => options.account?.(),\n    store,\n    logger,\n    // 探查改了\"支持哪些档位\"→ 必须让宿主重建模型列表，否则界面上看不到变化。\n    onProbed: options.onProbed,\n    run: (modelId) => probeModel({\n      // 候选 = pi-ai 键空间去掉 off（见 PROBE_CANDIDATE_EFFORTS 的说明）。\n      // 这是协议层的\"上界\"，不是某个模型的写死名单 —— 探出来多少算多少。\n      candidates: PROBE_CANDIDATE_EFFORTS,\n      send: (effort, signal) => sendQoderProbe({ tokens, config, logger }, modelId, effort, signal),\n      isAcceptance: probeIsAcceptance,\n      isEffortRejection: probeIsEffortRejection,\n    }),\n  });\n  return { service, store, key: () => key };\n}\n\n/** 组装 pi-ai 的 provider + DSH 的 adapter。 */\n/**\n * [dsh-connect] 面板下发的\"禁用模型\"钩子：`(providerId) => 要隐藏的模型 id[]`。\n *\n * provider 自己不知道面板的存在；lib/index.js 在启动时用 setExternalHidden 注入，\n * 未注入时视为\"不隐藏\"。每次构建模型列表时重新调用，所以用户在面板里改完立即生效。\n */\nlet externalHidden = () => [];\nexport function setExternalHidden(fn) {\n  externalHidden = typeof fn === \"function\" ? fn : () => [];\n}\n\n/**\n * Qoder 思考档位（reasoning_effort）声明。\n *\n * ## 为什么现在敢声明了\n *\n * 早先这里是写死的 `reasoning: false`，注释理由是\"避免 pi-ai 塞 Qoder 不认识的\n * reasoning 参数\"。**实测推翻了这个假设**：上游不但认识，而且会校验。\n *\n * 2026-10-06 用真实凭据逐档位探测（复用本文件的编码/COSY 签名，保证请求同形；\n * 脚本见 `probes/qoder-effort-probe.mjs`，含一个乱填值的对照组）：\n *\n * | 发送值 | 上游 |\n * |---|---|\n * | 不发该字段 | 200 |\n * | minimal / low / medium / high / max | 200（全部接受）|\n * | off | **400 拒绝** |\n * | `bogus_value_xyz`（对照） | **400 拒绝** |\n *\n * 对照组是关键：**乱填会被拒**，证明上游确实在校验这个参数，而不是\"传什么都收\"。\n * 响应体量也随档位分层（high 45KB / max 39KB / low 30KB vs 不传 17KB），说明\n * 档位真的改变输出，不是被忽略的装饰参数。\n *\n * ## 映射规则\n *\n * pi-ai 的 `thinkingLevelMap` 把 UI 档位映射成**线上拼写**（值与键同名即原样发）。\n * - `off` 置 `null`：上游对 `off` 返回 400，这不是\"关思考\"的意思。\n *   要关思考走既有的 id 后缀 `@nothink`（`decodeModelId`），那是另一条已验证的路径。\n * - `minimal` 置 `null`：上游接受，但 DSH 的档位 UI 不呈现该级别，留着是死配置。\n * - 其余档位（low/medium/high/xhigh/max）**逐模型**按上游声明给出。\n *\n * ## ⚠️ 曾用错判据的教训（2026-10-06）\n *\n * 早先这里用 `isReasoning`（上游 `is_reasoning`）当\"支不支持档位\"的判据，\n * 结果 DeepSeek-Flash、Kimi-K3 都拿不到档位。**那个判据是错的**：\n * `is_reasoning` 说的是\"是否**专用**思考模型\"，Flash 系列自然不是；\n * 档位声明在 `thinking_config.enabled.efforts` 里（见 {@link parseThinkingConfig}）。\n *\n * 而且档位**逐模型不同**（实测原始目录）：\n *   qmodel_38max → xhigh / low / medium；dfmodel → high / max / low。\n * 早先\"所有模型同一套档位\"的做法，等于给部分模型发了它不认的值。\n *\n * ## 声明 vs 实测：**取并集**，不是二选一\n *\n * 上游没声明 ≠ 不支持：`qmodel` 声明为空，实测却接受全部 5 档。\n * 反过来，声明也**可能比实测窄**：`dfmodel` 声明 3 档，实测接受 5 档 ——\n * 若\"声明优先\"，实测出的 2 个真实档位会被永远藏住。\n * 所以两者**取并集**（见 {@link supportedEffortsOf}）：声明是保底，\n * 实测发现的额外档位是对它的**扩展**，谁也不压谁。\n */\nfunction reasoningFieldsFor(info, observed) {\n  /**\n   * 并集语义（与 {@link supportedEffortsOf} 一致）：\n   *   · 声明 = 上游对 UI 的正式承诺，保底；\n   *   · 实测（仅 `validating` 才算数）= 已证实的额外档位；\n   *   · `non-validating`/`unknown` **不能**当\"不支持\"—— 哨兵被接受只说明\n   *     上游不校验，档位可能照常生效（`kmodel_latest` 声明 3 档但实测\n   *     non-validating，此时必须保住声明的 3 档）。\n   * 并集为空 → `reasoning: false`。\n   */\n  const supported = supportedEffortsOf(info, observed);\n  if (supported.length === 0) return { reasoning: false };\n\n  const set = new Set(supported);\n  const levelOf = (value) => (set.has(value) ? value : null);\n  return {\n    reasoning: true,\n    thinkingLevelMap: {\n      off: null,\n      minimal: null,\n      low: levelOf(\"low\"),\n      medium: levelOf(\"medium\"),\n      high: levelOf(\"high\"),\n      // xhigh 不是死配置：Qwen3.8 系列（qmodel_38max / qfmodel）上游**确实**声明了它。\n      xhigh: levelOf(\"xhigh\"),\n      max: levelOf(\"max\"),\n    },\n  };\n}\n\nexport function createQoderAdapter(options) {\n  const { shim, catalog } = options;\n  const providerId = options.providerId ?? QODER_PROVIDER;\n  const displayName = options.displayName ?? QODER_DISPLAY_NAME;\n  /** [dsh-connect] 面板禁用的模型 id（每次构建列表时重读，改完立即生效）。 */\n  const hidden = options.hidden ?? (() => []);\n\n  const buildModels = () => {\n    const baseUrl = `${shim.baseUrl()}/v1`;\n    // hiddenMatcher 返回的是判定函数（(id) => boolean），按函数调用。\n    // 曾把它当 Set 调 .has() —— 每次构建列表都抛 TypeError，选择器里整个渠道消失。\n    const isHidden = hiddenMatcher(hidden());\n    const probe = options.probe;\n    return catalog.current().filter((info) => !isHidden(info.id)).map((info) => ({\n      id: info.id,\n      // 倍率挂在名字上：模型下拉只渲染 `name`（理由见 withRateName）。\n      name: withRateName(info),\n      api: \"openai-completions\",\n      provider: providerId,\n      baseUrl,\n      input: info.supportsImages === true ? [\"text\", \"image\"] : [\"text\"],\n      // 探查过的模型以实测结果为准（仅采纳 validating，理由见 reasoningFieldsFor）。\n      ...reasoningFieldsFor(info, probe?.service?.cached(info.id)),\n      cost: NO_COST,\n      contextWindow: info.contextWindow ?? 200000,\n      maxTokens: info.maxTokens ?? 32000,\n      compat: { maxTokensField: \"max_tokens\" },\n    }));\n  };\n\n  const provider = {\n    ...createProvider({\n      id: providerId,\n      name: displayName,\n      auth: {\n        apiKey: {\n          name: \"Qoder 回环凭据（由插件自己维护，无需填写）\",\n          async resolve({ credential }) {\n            const apiKey = credential?.key;\n            return apiKey === undefined || apiKey.length === 0 ? undefined : { auth: { apiKey }, source: \"Qoder\" };\n          },\n        },\n      },\n      models: buildModels(),\n      api: openAICompletionsApi(),\n    }),\n    getModels: () => buildModels(),\n  };\n\n  const profile = {\n    provider: providerId,\n    displayName,\n    streamIdleTimeoutMs: QODER_STREAM_IDLE_TIMEOUT_MS,\n    retryPolicy: resolveRetryPolicy(undefined, \"dsh-qoder-connect retryPolicy\"),\n    configuredMaxTokens: new Map(),\n    modelErrors: new Map(),\n    ...REQUEST_IMAGE_BUDGETS,\n    piProvider: provider,\n  };\n  let profiles = new Map([[providerId, profile]]);\n  return {\n    /**\n     * 附件服务解析器 —— **带图会话能跑通全靠它**。\n     *\n     * 宿主 `dsh-llm-pi-ai` 在把请求交给 pi-ai 之前会先问这个函数要附件仓库：\n     *\n     * ```js\n     * const attachments = containsImage ? this.config.resolveAttachments?.() : undefined;\n     * if (containsImage && attachments === undefined)\n     *   throw new LlmError(\"pi-ai image input requires the durable attachment service\", \"UNSUPPORTED_CONTENT\");\n     * ```\n     *\n     * 不传就是 `undefined`，于是**任何**带图片的请求都在这里被拒，请求根本到不了\n     * Qoder 上游 —— 表现为「目录里明明写了 `is_vl: true` 却报 UNSUPPORTED_CONTENT」，\n     * 很容易误判成模型不支持读图。WorkBuddy provider 一直是好的，正是因为它建\n     * adapter 时把这行传了进去；Trae / Qoder 两路一直漏了，所以只有它们报错（2026-10-07 定位）。\n     *\n     * `ctx.get(\"attachments\")` 在本插件这一层能取到服务：`dsh-base` 声明了\n     * `id: attachment-local`，且三个渠道共用同一个 ctx（见 lib/index.js 的 `mod.apply(ctx, {})`）。\n     * 套 `withLegacyImageBudget` 是为跨版本安装兜底（pi-ai 与附件服务的两代契约在\n     * `readImageRequest` 的第二个参数上不一致）；同代 store 上它是 no-op，恒定套用安全。\n     *\n     * 参考实现：dingminhua/dsh-connect-trae `src/index.ts` 同一写法。\n     *\n     * 注：这段说明刻意放在 `new PiAiAdapter(` **外面** —— 放进实参里会让\n     * `probes/verify-attachment-wiring.mjs` 把注释里的同名字符串当成接线证据。\n     */\n    adapter: new PiAiAdapter({\n      profiles: () => profiles,\n      auth: INERT_AUTH,\n      resolveApiKey: async () => shim.token(),\n      resolveAttachments: options.resolveAttachments,\n    }),\n    invalidate: () => { profiles = new Map([[providerId, profile]]); },\n  };\n}\n\n//#endregion\n//#region 状态路由（供浏览器侧读取）\n\n/** 注册给浏览器侧的两个路由。与 client.js 里的字面量必须逐字一致。 */\nexport const QODER_STATUS_ROUTE = \"/plugins/dsh-qoder-connect/status\";\nexport const QODER_CHECKIN_ROUTE = \"/plugins/dsh-qoder-connect/checkin\";\n/** 推理等级探查：GET 读已探结果，POST `{model}` 触发一次探测（会花真实额度）。 */\nexport const QODER_PROBE_ROUTE = \"/plugins/dsh-qoder-connect/probe\";\n\n/** 倍率展示：0.8 → \"0.8×\"，整数去掉小数，拿不到就是 undefined。 */\nfunction formatRate(rate) {\n  if (typeof rate !== \"number\" || !Number.isFinite(rate) || rate <= 0) return undefined;\n  return Number.isInteger(rate) ? `${rate}×` : `${Number(rate.toFixed(2))}×`;\n}\n\n/**\n * 把倍率挂到模型名上：`Qwen3.8-Max` → `Qwen3.8-Max · 0.5×`。\n *\n * DSH 0.1.5 的模型下拉（dsh-client-ui-model-selection）只渲染 `model.name`\n * （`modelLabel = currentChoice?.model.name`，列表项也是 `children: model.name`），\n * `description` 根本不读 —— 想让每个模型都看到倍率，只能挂在名字上。\n *\n * 拿不到倍率（上游没给 `price_factor`，例如 `Qwen3.8-Flash`）就原样返回，不硬凑。\n * 面板状态文档里另有独立的 `rate` 字段，所以那一边不必重复。\n */\nfunction withRateName(info) {\n  const rate = formatRate(info.rate);\n  return rate === undefined ? info.name : `${info.name} · ${rate}`;\n}\n\n/**\n * 组装给浏览器侧的状态文档。\n *\n * 与另外两条渠道同一原则：**额度与签到都是「尽力而为」**——上游任何一段失败都降级\n * 成该字段的错误串，而不是让整份文档 500。否则网络抖一下，界面上连渠道名和签到\n * 按钮都会消失。\n *\n * 这里额外把**每个模型的倍率**带上（`models[].rate`），因为 dock 那一行要显示\n * 当前选中模型的倍率，而它只随目录变，不该为它单独打一次上游。\n */\nexport async function qoderWebStatus(deps) {\n  const base = { provider: QODER_PROVIDER, channel: QODER_DISPLAY_NAME };\n  // 凭据可以来自 App 会话（session.json）或官方 PAT —— 两者都没有才算未登录。\n  // （会话由宿主脚本 scripts/qoder-vault.mjs --install-session 导出，token-manager 会优先用它。）\n  const session = deps.sessions === undefined ? undefined : await deps.sessions.current().catch(() => undefined);\n  const pat = await deps.pats.current();\n  if (session === undefined && pat === undefined) {\n    return {\n      ...base,\n      status: \"signed-out\",\n      patPath: deps.pats.path(),\n      ...deps.sessions === undefined ? {} : { sessionPath: deps.sessions.path() },\n    };\n  }\n\n  let credential;\n  try {\n    credential = await deps.tokens.get();\n  } catch (error) {\n    return { ...base, status: \"signed-out\", patPath: deps.pats.path(), patSource: pat.source, reason: briefMessage(error) };\n  }\n\n  const models = deps.catalog.current();\n  const doc = {\n    ...base,\n    status: \"signed-in\",\n    userId: credential.userID,\n    account: credential.name === \"\" ? credential.email : credential.name,\n    email: credential.email,\n    patSource: credential.source,\n    expiresAt: new Date(credential.expiresAt).toISOString(),\n    modelCount: models.length,\n    catalogSource: deps.catalog.source(),\n    catalogFetchedAt: deps.catalog.fetchedAt() === 0 ? undefined : new Date(deps.catalog.fetchedAt()).toISOString(),\n    models: models.map((model) => ({\n      id: model.id,\n      name: model.name,\n      rate: formatRate(model.rate),\n      free: model.isFree === true,\n      isReasoning: model.isReasoning === true,\n      contextWindow: model.contextWindow,\n    })),\n    /**\n     * 推理等级探查契约（供前端渲染\"检测\"按钮）。\n     *\n     * 为什么 Qoder 需要而 Trae 不需要：Qoder 目录只给 `is_reasoning` 布尔、\n     * **不声明档位列表**，所以\"这个模型支持哪几档\"只能靠探查实测；\n     * 而 Trae 目录按 (模型 × function) 直接声明了 `options`，声明即权威。\n     */\n    ...deps.probe === undefined ? {} : {\n      probe: {\n        /**\n         * 显示探查按钮的模型 = **还没有探查记录**的模型。\n         *\n         * 早期两版判据都不对：\n         *   · `isReasoning === true` —— 把 DeepSeek-Flash / Kimi-K3 排除在外\n         *     （它们 `is_reasoning=false` 却档位最全）；\n         *   · 「没声明档位的」—— 反过来把**已声明**的模型藏起来，而实测恰恰\n         *     可能比声明更宽（dfmodel 声明 3 档、实测 5 档），用户就永远\n         *     发现不了多的那几档。\n         * 「没有记录就值得探」是完全数据驱动的：探完有结果 → 按钮变成展示结果\n         * （前端 `candidates.includes(model) || result !== undefined` 就是这个语义），\n         * 模型增减自动跟随目录，无任何写死名单。\n         */\n        candidates: models.filter((model) => deps.probe.service.cached(model.id) === undefined).map((model) => model.id),\n        running: deps.probe.service.isRunning(),\n        results: models.flatMap((model) => {\n          const record = deps.probe.service.cached(model.id);\n          return record === undefined ? [] : [{ id: model.id, name: model.name, validation: record.validation, efforts: record.efforts, probedAt: record.probedAt }];\n        }),\n      },\n      probeKey: deps.probe.key(),\n    },\n  };\n\n  try {\n    doc.quota = await deps.account.fetchQuota(credential);\n  } catch (error) {\n    doc.quotaError = briefMessage(error);\n  }\n  try {\n    doc.checkin = await deps.account.fetchCampaign(credential);\n  } catch (error) {\n    doc.checkinError = briefMessage(error);\n  }\n  return doc;\n}\n\n/** 签到路由：GET 读状态（只读），POST 尝试领取（会如实返回 manual-required）。 */\nexport async function qoderCheckinAction(deps, method) {\n  const credential = await deps.tokens.get().catch(() => undefined);\n  if (credential === undefined) return { state: \"signed-out\" };\n  if (method === \"GET\") {\n    try {\n      return { state: \"signed-in\", checkin: await deps.account.fetchCampaign(credential) };\n    } catch (error) {\n      return { state: \"failed\", message: briefMessage(error) };\n    }\n  }\n  try {\n    return await deps.account.claimCampaign(credential);\n  } catch (error) {\n    return { state: \"failed\", message: briefMessage(error) };\n  }\n}\n\n/**\n * 两个路由的共用外壳。\n *\n * 必须做 loopback 守卫：这两个端点挂在用户自己的 DSH 端口上，而 DSH 端口可能被\n * 反代 / 局域网暴露。Host **和** Origin 都要求是回环，缺一不可\n * （只有 Host 挡不住 DNS rebinding，只有 Origin 挡不住非浏览器客户端；\n * 这两个接口本身不写敏感数据，两者齐备即可）。\n */\nfunction qoderRouteHandler(handle) {\n  return async (req, res) => {\n    if (req.method !== \"GET\" && req.method !== \"POST\") {\n      writeJson(res, 405, { error: \"method not allowed\" });\n      return;\n    }\n    if (!loopbackRequest(req)) {\n      writeJson(res, 403, { error: \"request-not-trusted\" });\n      return;\n    }\n    /**\n     * POST 要读 body：探查路由靠 `{model}` 指定目标模型。\n     * 复用已有的 `readBody`（本文件里 shim 也在用同一个），不另造一份。\n     */\n    let body;\n    if (req.method === \"POST\") {\n      try {\n        body = (await readBody(req)).toString(\"utf8\");\n      } catch (error) {\n        writeJson(res, 400, { error: briefMessage(error) });\n        return;\n      }\n    }\n    try {\n      writeJson(res, 200, await handle(req.method, body, req.headers));\n    } catch (error) {\n      writeJson(res, 500, { error: briefMessage(error) });\n    }\n  };\n}\n\n/**\n * 注册 `/plugins/dsh-qoder-connect/{status,checkin,probe}`；webServer 缺失时整段跳过。\n *\n * ## 新渠道接入探查需要改哪些地方\n *\n * 三处，缺一不可（Trae 只做了第 1 处，因为它的档位由目录声明、不需要探查）：\n *   1. 目录/provider 侧声明档位（若有 `options` 就到此为止）；\n *   2. **状态文档下发 `probe` + `probeKey`** —— 前端据此渲染\"检测\"按钮；\n *   3. **注册探查路由**并校验 key —— 探查会花额度，必须有这层授权。\n * 前端控件还需要认识该 provider（见 `client.js` 的 provider → 路由映射）。\n */\nexport function registerQoderStatusRoutes(ctx, deps) {\n  for (const [path, handle] of [\n    [QODER_STATUS_ROUTE, () => qoderWebStatus(deps)],\n    [QODER_CHECKIN_ROUTE, (method) => qoderCheckinAction(deps, method)],\n    [QODER_PROBE_ROUTE, (method, body, headers) => qoderProbeAction(deps, method, body, headers)],\n  ]) {\n    ctx.effect(() => {\n      const dispose = ctx.webServer.register({ kind: \"exact\", path, handler: qoderRouteHandler(handle) });\n      return () => { dispose(); };\n    }, `dsh-qoder-connect: ${path}`);\n  }\n}\n\n/**\n * 探查路由：`GET` 读已探结果、`POST` 触发一次探测（需带 key）。\n *\n * ## 为什么请求契约与 WorkBuddy 对齐\n *\n * 前端那个\"检测\"控件（`client.js` 的 `WorkBuddyProbeControl`）是**构建产物**，\n * 它发请求时用的是固定的头名与 body 结构（`X-WorkBuddy-Probe-Key` +\n * `{action:\"probe\", model}`）。为让 Qoder 复用同一个控件，这里**接收同样的形状**\n * 而不是另立一套 —— 否则就要去改打包后的 bundle，风险与收益不成比例。\n * 头部名是历史遗留（控件是 WorkBuddy 时期写的），不影响安全性：key 本身每次启动随机。\n *\n * 同时接受 `x-qoder-probe-key` + `{model}`，方便脚本/CLI 直连时用更自然的名字。\n */\nasync function qoderProbeAction(deps, method, body, headers) {\n  const { probe } = deps;\n  if (probe === undefined) return { state: \"unavailable\", reason: \"probe not configured\" };\n  if (method === \"POST\") {\n    /**\n     * 只有 POST 需要 key：它会真的发请求、花额度。GET 是只读的已探结果，\n     * 与状态路由同级，不额外设卡。\n     */\n    const presented = headers?.[\"x-workbuddy-probe-key\"] ?? headers?.[\"x-qoder-probe-key\"];\n    if (!probeKeyMatches(probe.key(), presented)) {\n      return { state: \"unavailable\", reason: \"invalid-probe-key\" };\n    }\n  }\n  if (method === \"GET\") {\n    return {\n      running: probe.service.isRunning(),\n      results: deps.catalog.current().flatMap((model) => {\n        const record = probe.service.cached(model.id);\n        return record === undefined ? [] : [{ id: model.id, validation: record.validation, efforts: record.efforts }];\n      }),\n    };\n  }\n  if (method !== \"POST\") return { error: \"method not allowed\" };\n  let parsed;\n  try {\n    parsed = typeof body === \"string\" && body.length > 0 ? JSON.parse(body) : {};\n  } catch {\n    return { state: \"unavailable\", reason: \"bad json\" };\n  }\n  // `action` 在前端契约里恒为 \"probe\"；这里只校验 model。\n  const modelId = typeof parsed?.model === \"string\" ? parsed.model : \"\";\n  if (modelId === \"\") return { state: \"unavailable\", reason: \"missing model\" };\n  /**\n   * 面板/设置页的显式点击 = 一次性人工同意（`manualConsent`）。\n   *\n   * 与 WorkBuddy 同思路：人工点击不改变\"自动探查\"的配置，只对本次生效 ——\n   * 探查会花真实额度，所以必须由用户逐个模型确认。\n   */\n  return await probe.service.probe(modelId, true);\n}\n\n//#endregion\n//#region 插件入口\n\n/** 运行态文件名（与 trae 的同名文件只差前缀）。 */\nconst QODER_STATE_FILENAME = \".qoder-connect-state.json\";\n\n/**\n * 运行态落盘：`$DSH_HOME/.qoder-connect-state.json`。\n *\n * 与另外两条渠道同思路 —— DSH 的插件日志默认不进 web 日志文件，\n * 只看日志无法判断一个渠道到底有没有注册成功、当前是「未登录」还是「已就绪」。\n * 这份文件把结论固化下来，排查时直接看它。\n *\n * 实现在 `shared/node.js`（与 trae 共用同一份，只差文件名）。\n */\nfunction writeState(patch, logger) {\n  writeChannelState({ filename: QODER_STATE_FILENAME, patch, logger });\n}\n\n/**\n * 启动：起回环 shim → 注册 `qoder1` provider → 按凭据巡检刷新目录。\n *\n * 无论有没有 PAT 都先注册 provider —— DSH 用「模型组为空」来隐藏一个模型组，\n * 所以登录（放进 PAT）发生在 DSH 已经跑起来之后也能生效，不需要重新注册。\n */\nexport function apply(ctx, config) {\n  let stopped = false;\n  const current = () => config ?? {};\n\n  const pats = createPatStore({ config: current });\n  // [dsh-connect] App 会话优先：导出了 ~/.dsh/qoder/session.json 就用它，不碰 PAT。\n  const sessions = createSessionStore({ config: current });\n  const tokens = createTokenManager({ pats, sessions, config: current, logger: ctx.logger });\n  const catalog = createCatalog({ tokens, config: current, logger: ctx.logger });\n  const client = createQoderClient({ tokens, config: current, logger: ctx.logger });\n  const account = createQoderAccountClient({ tokens, config: current, logger: ctx.logger });\n\n  const shim = createQoderShim({ client, catalog, logger: ctx.logger });\n\n  /**\n   * 探查用的账号标识 —— **必须来自凭据，不能读配置**。\n   *\n   * ## 为什么（2026-10-08 修）\n   *\n   * 这里原来是 `() => current()?.account`，即读**配置对象**里的一个字段。而该字段\n   * 从来没人写过（profile 里只有 autoCheckin / disabledChannels / disabledModels），\n   * 于是 `ProbeService.probe()` 里的\n   *\n   *     const account = this.options.account();\n   *     if (account === undefined) return { state: \"unavailable\", reason: \"no credential\" };\n   *\n   * 每次都命中 —— **面板上点「检测档位」必然返回 `no credential`**，与凭据是否有效\n   * 完全无关。状态行仍显示 `signed-in`（那条路走的是凭据解析），所以现象看起来\n   * 自相矛盾：「已登录」却「没有凭据」。\n   *\n   * 对照 WorkBuddy：它用的是 `account: () => identityOf(variant.id)` —— 动态解析真实\n   * 身份（`uid:enterpriseId`），所以那条路一直能探（`.workbuddy1-probe.json` 有记录）。\n   * 本次修复就是把 Qoder 对齐到同一思路：**身份来自 tokens，而不是配置。**\n   *\n   * ## 为什么要缓存\n   *\n   * `ProbeService` 同步调用 `account()`，而 `tokens.get()` 是异步的（可能要刷新\n   * jobToken）。所以这里维护一个**同步可读**的缓存，由凭据巡检在每次拿到凭据时刷新。\n   * 缓存没热起来时返回 undefined —— 与旧行为一致（探查返回 no credential），\n   * 但下一次巡检（默认 30 s）后就好了，属于可接受的冷启动窗口。\n   */\n  let probeAccountCache;\n  const refreshProbeAccount = () => {\n    tokens\n      .get()\n      .then((credential) => {\n        const uid = typeof credential?.userID === \"string\" ? credential.userID.trim() : \"\";\n        if (uid !== \"\") probeAccountCache = uid;\n      })\n      .catch(() => {\n        /* 拿不到凭据就保持上一次的值；签出后再签入时会重新填上 */\n      });\n  };\n  const probeAccount = () => probeAccountCache;\n  // 立刻热一次（插件刚启动、凭据已在盘上时，第一次点击探查就能用）。\n  refreshProbeAccount();\n\n  /**\n   * 推理等级探查。\n   *\n   * Qoder 的档位**优先**取上游目录的 `thinking_config.enabled.efforts` 声明\n   * （逐模型精确）；探查只为**没声明**的那些兜底（哨兵拒绝法，见 {@link createQoderProbe}）。\n   */\n  const probe = createQoderProbe({\n    tokens, config: current, catalog, logger: ctx.logger,\n    account: () => probeAccount(),\n    // 探查完必须广播一次：档位写在模型描述符里，重建后 UI 才会出现档位下拉。\n    onProbed: () => {\n      try {\n        ctx.emit(\"llm/adapters-updated\");\n      } catch (error) {\n        ctx.logger?.warn?.(\"dsh-qoder-connect: 探查后广播模型更新失败\", error);\n      }\n    },\n  });\n  // shim 需要读探查结论来决定\"这个模型是否开思考\"，所以创建后再挂上去。\n  // （顺序反了会踩 TDZ：`const` 在声明前不可访问。）\n  shim.setProbe?.(probe);\n\n  // 渠道状态行（渠道 / 倍率 / 额度 / 签到）走 DSH 自己的 webServer，不是回环 shim ——\n  // 前者给浏览器同源读取，后者只给 pi-ai 发 OpenAI 请求。webServer 在非 web\n  // profile 里不存在，所以用 ctx.inject 做可选依赖。\n  ctx.inject([\"webServer\"], (webCtx) => {\n    if (stopped) return;\n    try {\n      registerQoderStatusRoutes(webCtx, { pats, sessions, tokens, catalog, account, probe });\n    } catch (error) {\n      ctx.logger?.warn?.(\"dsh-qoder-connect: 状态路由注册失败（渠道本身不受影响）\", error);\n    }\n  });\n\n  shim.ready.then(() => {\n    if (stopped) return;\n    const { adapter, invalidate } = createQoderAdapter({\n      shim,\n      catalog,\n      hidden: () => externalHidden(QODER_PROVIDER),\n      probe,\n      /** 附件仓库解析器；缺了它，带图请求会被宿主在进 pi-ai 之前拒掉（UNSUPPORTED_CONTENT）。 */\n      resolveAttachments: () => {\n        const store = ctx.get(\"attachments\");\n        return store === undefined ? undefined : withLegacyImageBudget(store, REQUEST_IMAGE_BUDGETS.requestImagePixelBudget);\n      },\n    });\n    const release = ctx.llm.registerAdapter([QODER_PROVIDER], adapter);\n    try {\n      ctx.effect(() => () => { release(); shim.close(); });\n    } catch {\n      release();\n      shim.close();\n    }\n\n    const refresh = () => {\n      if (stopped) return;\n      // 顺带热一次探查用的身份缓存（凭据已在这里解析，不必再起一条异步链）。\n      refreshProbeAccount();\n      tokens.get().then(\n        (credential) => catalog.reload().then(\n          () => {\n            if (stopped) return;\n            invalidate();\n            ctx.emit(\"llm/adapters-updated\");\n            const models = catalog.current();\n            writeState({\n              ready: true,\n              provider: QODER_PROVIDER,\n              shim: shim.baseUrl(),\n              userId: credential.userID,\n              patSource: credential.source,\n              jobTokenExpiresAt: new Date(credential.expiresAt).toISOString(),\n              catalogSource: catalog.source(),\n              modelCount: models.length,\n              models: models.map((model) => ({ id: model.id, rate: model.rate, free: model.isFree })),\n            }, ctx.logger);\n            ctx.logger.info(`dsh-qoder-connect: Qoder 已就绪（uid=${credential.userID}，${models.length} 个模型）`);\n          },\n          (error) => {\n            if (stopped) return;\n            const message = error instanceof Error ? error.message : String(error);\n            // 目录挂了但凭据是好的：渠道仍然可用（只是沿用兜底名单）。\n            invalidate();\n            ctx.emit(\"llm/adapters-updated\");\n            writeState({\n              ready: true,\n              provider: QODER_PROVIDER,\n              shim: shim.baseUrl(),\n              userId: credential.userID,\n              catalogSource: catalog.source(),\n              modelCount: catalog.current().length,\n              catalogError: message,\n            }, ctx.logger);\n            ctx.logger.warn(`dsh-qoder-connect: 目录刷新失败，渠道沿用兜底名单 — ${message}`);\n          },\n        ),\n        (error) => {\n          if (stopped) return;\n          const message = error instanceof Error ? error.message : String(error);\n          writeState({ ready: false, provider: QODER_PROVIDER, shim: shim.baseUrl(), patPath: pats.path(), error: message }, ctx.logger);\n          ctx.logger.warn(`dsh-qoder-connect: 未就绪 — ${message}`);\n        },\n      );\n    };\n\n    refresh();\n    const timer = setInterval(refresh, pollInterval(current()));\n    timer.unref?.();\n    ctx.effect(() => () => { clearInterval(timer); });\n  }).catch((error) => {\n    ctx.logger?.error?.(\"dsh-qoder-connect: 回环 shim 启动失败\", error);\n  });\n\n  ctx.effect(() => () => { stopped = true; });\n\n  // 面板「更新模型」：强制重拉目录并广播，新模型不在禁用黑名单里 → 立即可选。\n  // 差异带档位：目录是档位的真值来源，thinking_config 变了要如实上报。\n  return {\n    kind: \"qoder\",\n    forceRefresh: async () => {\n      const before = catalog.current();\n      const list = await catalog.reload();\n      ctx.emit(\"llm/adapters-updated\");\n      const after = Array.isArray(list) ? list : catalog.current();\n      return {\n        source: catalog.source(),\n        ...diffCatalog(before, after, (entry) => entry?.declaredEfforts),\n      };\n    },\n  };\n}\n\n//#endregion\n"
    },
    {
      "path": "lib/providers/trae/index.js",
      "content": "/**\n * dsh-trae-connect —— 把 Trae 订阅里的模型接入 DeepSeek Harness。\n *\n * 契约速查（完整背景见 docs/IMPLEMENTATION-NOTES.md「Trae 渠道总览」）：\n *   · 在用的产品只有一个：**Trae CN IDE**（`product` = cn）。旧的独立客户端\n *     TRAE SOLO CN 已被厂商并进 IDE，`solo` 那条只留给**并入前导出的旧快照**继续跑。\n *     两条线共用同一端点与 appId，差异全收在 `TRAE_PRODUCTS` 一张表；\n *     重导快照（`export-trae-plain.mjs --app cn|solo`）即切换，30 秒巡检内生效，不用重启 DSH。\n *   · 推理走 agent 服务 `/api/agent/v3/llm_utils_chat` —— 不是\n *     `llm_raw_chat`（那是 BYOK 通道，外部调用必得 2001 record not found）。\n *     必需三样：`app_id`+`app_version_code`（产品级常量）、注册过的\n *     `function`（见 TRAE_FUNCTIONS）、`content` 为对象数组（字符串会被拒）。\n *   · 数据流：DSH ──OpenAI──▶ 回环 shim ──Trae SSE──▶ trae-api-cn.mchost.guru\n *     （shim 与 workbuddy 同构；上游非 OpenAI 形状，本模块逐事件翻译）。\n *   · 凭据：宿主脚本解密 Trae 客户端信封后写明文快照到\n *     `$DSH_HOME/trae{,-cn}/`，本模块只读快照，不碰 App 目录。\n *\n * @module dsh-trae-connect\n */\n\nimport z from \"@deepseek-ai/schemastery\";\nimport { randomBytes, timingSafeEqual } from \"node:crypto\";\nimport { existsSync, readFileSync } from \"node:fs\";\nimport { createServer } from \"node:http\";\nimport { join } from \"node:path\";\nimport { Readable } from \"node:stream\";\nimport { createProvider } from \"@earendil-works/pi-ai\";\nimport { openAICompletionsApi } from \"@earendil-works/pi-ai/api/openai-completions.lazy\";\nimport { PiAiAdapter } from \"@deepseek-ai/dsh-llm-pi-ai\";\nimport { resolveRetryPolicy } from \"@deepseek-ai/dsh-llm\";\nimport { resolveDshHome } from \"@deepseek-ai/dsh-home-paths\";\nimport { abortOnClientDisconnect, briefMessage, hostIsLoopback, loopbackRequest, originIsLoopback, withLegacyImageBudget, writeJson } from \"../../shared/http.js\";\nimport { pollInterval, readBody, writeState as writeChannelState } from \"../../shared/node.js\";\nimport { hiddenMatcher } from \"../../shared/hidden.js\";\nimport { diffCatalog } from \"../../shared/catalog-diff.js\";\n\n//#region 常量\n\n/** Cordis 插件名。必须与 cordis.patch.yml 里的 `id` 一致。 */\nexport const name = \"llm-trae\";\n/** 注册 provider 之前必须先拿到模型注册表。 */\nexport const inject = [\"llm\"];\n\n/** DSH 里对用户展示的 provider id，也是模型选择器上那一组的名字。 */\nconst TRAE_PROVIDER = \"trae\";\nconst TRAE_DISPLAY_NAME = \"Trae\";\n\n/** 推理网关。product.json 的 bootConfig.agent/hub/remote 全部指向它。 */\nconst DEFAULT_GATEWAY = \"https://trae-api-cn.mchost.guru\";\n/** 账号/计费网关。凭据里的 `host` 就是它，签到与额度都打这里。 */\nconst DEFAULT_ACCOUNT_BASE = \"https://api.trae.cn\";\n/** 产品级 App 身份（bootConfig.hub.appId / agent.appId）。两条接法共用同一个串。 */\nconst DEFAULT_APP_ID = \"6eefa01c-1036-4c7e-9ca5-d891f63bfcd8\";\n\n/**\n * 模型配置注册表 —— 倍率的**唯一权威来源**。\n *\n * 同一台网关（`trae-api-cn.mchost.guru`）下的 `/api/ide/v1/**` 命名空间，\n * 与推理同源，不需要额外主机常量。\n *\n * 三个请求头缺一不可，且行为都不直观（实测矩阵见 {@link createTraeRateClient}）：\n * `X-Ide-Token` 缺 → 401；`X-App-Id` 缺 → 只回 1.3 KB 空壳；\n * `X-Ide-Version-Code` 用小值 → **静默降级**成 6.5 KB 的不带 function_configs 的壳。\n */\nconst DETAIL_PARAM_PATH = \"/api/ide/v1/batch_get_detail_param\";\n\n/**\n * 倍率刷新间隔。**与 30s 的凭据巡检解耦** —— 定价变动以小时计，\n * 而一次全量响应约 1.4 MB（约 96 次/天 = 130 MB/天），按凭据频率打会把上游打疼。\n */\nconst RATE_REFRESH_MS = 900000;\nconst MIN_RATE_REFRESH_MS = 60000;\nconst MAX_RATE_REFRESH_MS = 86400000;\n/** 倍率请求超时：响应 1.4 MB，实测 0.4–27 s（上游会抖），别用默认的短超时。 */\nconst RATE_TIMEOUT_MS = 60000;\n/**\n * 倍率注册表的**单次查询 function 数上限**。\n *\n * 实测（2026-10-07，Trae CN，同一份凭据）上游延迟对 `functions` 长度是**非线性**的：\n *   3 个 → 2.4 s   5 个 → 8.1 s   7 个 → 7.2 s   9 个 → 10.2 s\n *   12 个 → **60 s 超时**（不是慢，是整条请求被掐住）  17 个 → 同样超时\n * 所以按 9 个一批切开顺序查，一批失败只丢那一批的模型，不至于整列倍率消失。\n *\n * 两条接法的默认名单（现役 CN 3 个 / 冻结的 SOLO 11 个）走这条分别是 1 批和 2 批。\n * 留在 9 而不是调小，是为了兜住**用户自己在配置里写长 `rateFunctions`** 的情况 ——\n * 那是唯一能把名单撑到 12 个以上的入口，而它一旦撑过去，不分批就是整列倍率超时。\n */\nconst RATE_QUERY_CHUNK = 9;\n\n/**\n * 积分与签到的两个上游端点。\n *\n * 两者都是 **POST**（`out/main.js` 里 `eb(path, \"POST\", ...)`），尽管 GET 也回 200 ——\n * 但只有 POST 是 App 自己用的那条路，所以照抄 POST。\n *\n * 返回形状：\n *   status → {code, message, enable, checked_in, did_checked_in, credits, extra_credits}\n *   claim  → {code, message}            // code === 0 即成功\n *   usage  → {usage_summary:{consumed_amount,total_amount,consumption_ratio}, ...}\n */\nconst CHECKIN_STATUS_PATH = \"/trae/api/v2/ug/checkin_credits/status\";\nconst CHECKIN_CLAIM_PATH = \"/trae/api/v2/ug/checkin_credits/claim\";\nconst ENTITLEMENT_USAGE_PATH = \"/trae/api/v2/pay/ide_user_ent_usage\";\n\n/**\n * 请求体里的 `req_source`，**漏了它 claim 会回 9004**。\n *\n * App 侧（`out/main.js` 的 `eb()`）发的是 `{req_source: a}`，其中\n * `a = Pr(product) ? 2 : 1`；而 `Pr` 判定 `packageType ∈ {SOLO_CN, SOLO_I18N,\n * SOLO_CN_ENTERPRISE}`。本机 `product.json` 是 `packageType: \"SOLO_CN\"`，\n * 所以是 **2**（\"work/lite\" 产品线，与 `sendEvent` 里的 `product: \"trae_work\"` 一致）。\n *\n * 实测：不带这个字段时 status 仍回 200，但 claim 回\n * `9004 The submitted order parameters are incorrect` —— 只读接口不校验它，\n * 写接口校验。这种\"只读能过、写入被拒\"的差异很容易被误判成鉴权问题。\n */\nconst TRAE_REQ_SOURCE = 2;\n\n/** 浏览器侧读的那两个路由，与 client.js 里的字面量必须一致。 */\nconst TRAE_STATUS_ROUTE = \"/plugins/dsh-trae-connect/status\";\nconst TRAE_CHECKIN_ROUTE = \"/plugins/dsh-trae-connect/checkin\";\n\n/**\n * 服务端为该 App 注册过的 function 名。在这个集合之外的任何名字都会被\n * `no function config found for appId=...` 拒绝（实测 86 个候选里只有这 9 个通过）。\n *\n * 前 7 个对应 Trae 的 agent 分组（与 state.vscdb 的 model_list_map 分组名一致），\n * 后 2 个是工具型 function。\n *\n * [产品变体] 这张表是 **TRAE SOLO CN 那条产品线**的白名单 —— 独立客户端已被厂商\n * 并进 IDE，所以它现在只服务并入前导出的旧快照（见 {@link TRAE_PRODUCTS} 的 `solo`）。\n * 现役的 Trae CN IDE 有自己的一套 function，在 {@link TRAE_PRODUCTS} 的 `cn.functions`\n * ——两条接法共用同一个 appId 与推理端点，但 function 名单、buildId、倍率注册表\n * 覆盖的模型各不相同，所以按产品分别持有，不再共用一张全局表。\n */\nexport const TRAE_FUNCTIONS = [\n  \"solo_work_lite\",\n  \"solo_agent_lite\",\n  \"solo_coder\",\n  \"solo_work_remote\",\n  \"solo_agent_remote\",\n  \"solo_design_lite\",\n  \"solo_design_remote\",\n  \"multimodal\",\n  \"refactor\",\n];\n\n/**\n * 拿不到 models.json 时的兜底名单（SOLO 产品线）。\n *\n * 只放确定存在的 preset 模型；不在名单里的 id 照样能用（catalog 是建议性的），\n * 这里的作用只是让模型选择器在首次导出前不至于空着。\n *\n * ⚠️ 声明位置在 {@link TRAE_PRODUCTS} **之前**：那张变体表要引用它，\n * 而 `const` 在初始化前是不可见的（TDZ）——放后面会让整个模块加载就抛 ReferenceError。\n */\nexport const FALLBACK_TRAE_MODELS = [\n  { id: \"DeepSeek-V4-Flash-Official\", name: \"DeepSeek-V4-Flash 正式版\", contextWindow: 200000, maxTokens: 32768, supportsImages: false },\n  { id: \"DeepSeek-V4-Pro-Official\", name: \"DeepSeek-V4-Pro 正式版\", contextWindow: 200000, maxTokens: 32768, supportsImages: false },\n  { id: \"Doubao-Seed-Evolving\", name: \"Seed-Evolving\", contextWindow: 256000, maxTokens: 32768, supportsImages: true },\n  { id: \"glm-5.3\", name: \"GLM-5.3\", contextWindow: 200000, maxTokens: 32768, supportsImages: false },\n  { id: \"kimi-k3\", name: \"Kimi-K3\", contextWindow: 200000, maxTokens: 32768, supportsImages: true },\n  { id: \"minimax-m3\", name: \"MiniMax-M3\", contextWindow: 128000, maxTokens: 32768, supportsImages: true },\n  { id: \"qwen3.8-max\", name: \"Qwen3.8-Max\", contextWindow: 200000, maxTokens: 32768, supportsImages: true },\n];\n\n/**\n * SOLO 产品线的默认 function（能力槽位）。\n *\n * ⚠️ **思考档位是按 (模型 × function) 配对下发的**，这是选它的唯一理由：\n *\n * | function | 支持档位的模型数 | 三档齐全 |\n * |---|---|---|\n * | `solo_agent_lite` / `solo_agent_remote` | 11 / 18 | 6 |\n * | `solo_work_lite`（旧默认） | **0 / 17** | 0 |\n * | 其余 5 个 | 0 | 0 |\n *\n * 实测（2026-10-06，同一账号）：`deepseek-v4.1-flash` 在 `solo_agent_lite` 下\n * 是 `{support_thinking:true, options:[\"light\",\"high\",\"extra_high\"]}`，\n * 而在 `solo_work_lite` 下是 `{support_thinking:false}` —— 传任何档位都无效。\n *\n * 切换代价为零：`solo_work_lite` 的 17 个模型**全部**包含在 `solo_agent_lite`\n * 的 18 个里（还多一个 Seed-Code），不会丢模型。\n */\nconst DEFAULT_FUNCTION = \"solo_agent_lite\";\n\n/**\n * Trae CN IDE 的三个能力槽位：`model_list_map` 的分组名 = 可推理 function =\n * 倍率注册表的查询键，三个身份在这一侧是同名的同一批字符串。\n *\n * 所以只写一次：`functions` / `rateFunctions` / `catalogGroups` 都从这里展开。\n * 分头维护的话，「快照里带了哪几个分组」和「请求发哪个槽位」就会漂移，\n * 而漂移的表现是静默丢档位（见 {@link TRAE_PRODUCTS} 里 `cn.functions` 的注释）。\n */\nconst TRAE_CN_SLOTS = [\"solo_agent\", \"chat_v3\", \"builder_v3\"];\n\n/**\n * Trae 的产品变体表 —— 「同一个渠道，两种接法」的唯一事实源。\n *\n * ## 现役产品只有一个\n *\n * 2026-10-11 本机实测：卸载表里只剩 `TRAE CN 3.4.2` 一条，`D:\\TRAE SOLO CN\\TRAE SOLO CN.exe`\n * 这个文件已经不存在，而残留的那份 `product.json` 与 Trae CN 的 `commit` / `buildId`\n * **逐字节相同** —— 即 **TRAE SOLO CN 作为独立客户端被并进了 Trae CN IDE**，\n * SOLO 变成 IDE 里的一个模式，不再是单独安装、单独登录的 App。\n * 所以 `cn` 是唯一的现役条目，`solo` 留着只服务两种存量场景：\n *\n *   1. 并入前导出的那份旧快照（`$DSH_HOME/trae/`）要继续能跑，不必重导；\n *   2. 尚未迁移的机器上独立客户端还在，仍能 `--app solo` 导出。\n *\n * 新用户一律 `--app cn`：IDE 里看到的那排模型就是全部，SOLO 的旧分组不再往外暴露\n * （理由见下面 `cn.functions` 的注释）。\n *\n * ## 为什么要做成表而不是分叉两份代码\n *\n * 两条产品在**协议层几乎同构**：同一个推理端点 `/api/agent/v3/llm_utils_chat`、\n * 同一个 `appId`、同一个账号网关、同一套 byteCrypto 信封。差别集中在**数据**上，\n * 而且每组都是实测出来的硬事实，不能猜：\n *\n * | 维度 | `cn`（Trae CN IDE，现役） | `solo`（TRAE SOLO CN，已并入 IDE） |\n * |---|---|---|\n * | `packageType` | `TRAE_CN` → `req_source=1` | `SOLO_CN` → `req_source=2` |\n * | `buildId`（= 倍率接口的 `X-Ide-Version-Code`） | 1238630385922 | 1227681842690 |\n * | 数据根目录（宿主） | `%APPDATA%\\Trae CN` | `%APPDATA%\\TRAE SOLO CN` |\n * | 有效 function 集 | `solo_agent` / `chat_v3` / `builder_v3` | {@link TRAE_FUNCTIONS} |\n * | 模型目录快照 | `$DSH_HOME/trae-cn/models.json` | `$DSH_HOME/trae/models.json` |\n *\n * 实测（2026-10-07 两份凭据对照，2026-10-11 合并后复算，同一账号、同一 deviceId）：\n * - **两份 token 是独立的**（`iCubeAuthInfo://icube.cloudide` 各存各的，\n *   到期时间也不同）。所以「换产品」= 换一份导出的快照，不是换个头。\n * - **Trae CN 的账号能打通 SOLO 的 function**（`solo_agent_lite` 等实测可用），\n *   但反过来不行 —— SOLO 的 `model_list_map` 里没有 CN 独占的\n *   `glm-5.3-flash` / `glm-5.3-flashx` / `kimi-k2.8-preview` / `qwen3.8-flash`。\n *   这正是「CN 模型更多更全」的技术成因，也是这次要切过去的原因。\n * - `builder` 在 CN 下报 `4001 param is invalid`、`chat` 报 `4023 model is unknown`\n *   ——它们只出现在**倍率注册表**里，不是可推理的 function，所以别放进 functions。\n *\n * ## 怎么选\n *\n * 由**凭据快照**里的 `product` 字段决定（`export-trae-plain.mjs --app cn|solo` 写进去）。\n * 老快照没有这个字段 → 由 buildId / `packageType` 嗅探认成 `solo`（见 {@link resolveProduct}），\n * 与升级前行为逐字相同：认不出来的快照只可能出自 SOLO 还独立发行的年代，判成 CN 会把\n * `req_source` 和 function 白名单一起换错，而且只在上游换来指不到根因的 4001。\n * 这样「切换」只是重跑一次导出脚本（30 秒巡检内生效，不用重启 DSH）。\n */\nexport const TRAE_PRODUCTS = {\n  cn: {\n    id: \"cn\",\n    /** 面板与状态文档里显示的产品名。 */\n    label: \"Trae CN（IDE）\",\n    /** 宿主数据根目录名（Windows 在 %APPDATA%、macOS 在 ~/Library/Application Support）。 */\n    appDir: \"Trae CN\",\n    packageType: \"TRAE_CN\",\n    /** 账号网关写接口（签到 claim）的 `req_source`。由 packageType 决定，填错只会被 9004 拒。 */\n    reqSource: 1,\n    /**\n     * product.json 的 buildId —— 倍率接口的筛选键，用错值不报错、只回空壳。\n     *\n     * ⚠️ 这**不是**必须与宿主相符的常量：运行时取值优先级是\n     * `配置 ?? 快照 ?? 这里`，厂商升级后快照里的新值本来就赢，这里只是快照没带\n     * `appVersionCode` 时的兜底。2026-10-11 按本机 `TRAE CN 3.4.2` 更新\n     * （旧值 1232067209986 打同一个倍率接口返回逐字节相同，所以旧值也不会空壳，\n     * 但兜底值理应当前版本）。\n     */\n    appVersionCode: 1238630385922,\n    appVersion: \"3.4.2\",\n    /**\n     * 默认 function：CN 的 Agent 智能体槽位。\n     *\n     * 选它的理由与 SOLO 选 `solo_agent_lite` 同一条：**档位与上下文窗口是按\n     * (模型 × function) 配对下发的**。实测 CN 的 `solo_agent` 分组里 14/18 个模型\n     * 带 `support_thinking`，其中 11 个三档齐全（light/high/extra_high），\n     * 且每个模型都带 `{dev, max}` 双窗口（Max 模式可扩到 1M）。\n     */\n    defaultFunction: \"solo_agent\",\n    /**\n     * IDE 模型表（`model_list_map`）里的三个分组，也是本产品**全部的**槽位名。\n     *\n     * 目录只从这三组收模型、倍率只查这三个名字、`@<槽位>` 后缀的白名单也只放这\n     * 三个，所以写成一份常量 —— 分头维护必然漂移。\n     *\n     * 为什么不再带上 SOLO 那 4 个槽位名（`solo_agent_lite` / `solo_work_lite` /\n     * `solo_agent_remote` / `solo_work_remote`）和工具型的 `multimodal` / `refactor`，\n     * 两条实测依据（2026-10-11，同一份 CN 凭据）：\n     *\n     * | 倍率查询集 | 耗时 | 目录模型的倍率覆盖 |\n     * |---|---|---|\n     * | 就这三个分组名 | 250 ms | **24 / 24** |\n     * | 上面 4 个 + `assistant` / `builder`（共 11 个） | 962 ms | 24 / 24，一条没多 |\n     *\n     * 逐个查还算过边际贡献：`solo_agent` 21 条、`builder_v3` 补最后 3 条，SOLO 那\n     * 4 个各自覆盖 19~20 条但**边际新增 0**，`multimodal` / `refactor` 直接 0。\n     * 多出来的 12 条倍率属于 `refactor_scoper` / `file_search_agent` / `sagitta`\n     * 这类内部流水线模型，一个都不在目录里；而同一模型跨 function 的取值实测一致\n     * （0 处冲突），所以多查纯粹是多一次上游往返。\n     *\n     * ⚠️ 从**推理**白名单里去掉它们还有更硬的一条：档位与上下文窗口是按\n     * (模型 × 分组) 下发的，而快照只带这三组的数据。真用 `@solo_work_lite` 去请求，\n     * `reasoningByGroup` 与 `contextWindowByGroup` 都查不到这个键 → 思考档位静默\n     * 失效、窗口退回兜底值，正是最难排查的那类静默降级。\n     * （SOLO 那几个名字在 CN 凭据下**确实还能推理**，只是对我们的目录毫无意义。）\n     */\n    functions: [...TRAE_CN_SLOTS],\n    /** 倍率注册表的查询键，见 {@link TRAE_CN_SLOTS} 上面那张覆盖表。 */\n    rateFunctions: [...TRAE_CN_SLOTS],\n    /**\n     * 导出模型目录时读取的分组（= {@link TRAE_CN_SLOTS}）。\n     *\n     * 只从这几个分组收模型，`code_reviewer` / `code_review_summary` / `refactor` 里的\n     * `refactor_scoper`、`code-review-judge` 这类**内部流水线小模型**就不会污染\n     * DSH 的模型选择器。`scripts/export-trae-plain.mjs` 的 `APPS.cn.catalogGroups`\n     * 是这份名单在宿主侧的镜像，两边要一起改。\n     */\n    catalogGroups: [...TRAE_CN_SLOTS],\n    /** 读不到 models.json 时的兜底名单（CN 侧确定存在的 preset）。 */\n    fallbackModels: [\n      { id: \"glm-5.3\", name: \"GLM-5.3\", contextWindow: 1000000, maxTokens: 32768, supportsImages: false },\n      { id: \"deepseek-v4.1-flash\", name: \"DeepSeek-V4.1-Flash\", contextWindow: 1000000, maxTokens: 32768, supportsImages: true },\n      { id: \"kimi-k3\", name: \"Kimi-K3\", contextWindow: 1000000, maxTokens: 32768, supportsImages: true },\n      { id: \"qwen3.8-max\", name: \"Qwen3.8-Max\", contextWindow: 1000000, maxTokens: 32768, supportsImages: true },\n      { id: \"Doubao-Seed-2.1-Pro\", name: \"Doubao-Seed-2.1-Pro\", contextWindow: 1000000, maxTokens: 32768, supportsImages: true },\n    ],\n    /** 模型目录快照的默认落点（$DSH_HOME 下）。 */\n    catalogSubdir: \"trae-cn\",\n  },\n  solo: {\n    id: \"solo\",\n    label: \"TRAE SOLO CN（已并入 Trae CN IDE）\",\n    appDir: \"TRAE SOLO CN\",\n    packageType: \"SOLO_CN\",\n    /** 与插件历史常量逐字相同（SOLO_* 产品线 = 2）。 */\n    reqSource: TRAE_REQ_SOURCE,\n    /** 独立客户端 `product.json` 的 buildId，逐字保留 —— 老快照就靠它被嗅探认出来。 */\n    appVersionCode: 1227681842690,\n    appVersion: \"0.1.66\",\n    defaultFunction: DEFAULT_FUNCTION,\n    /**\n     * 整条产品线**逐字冻结**：白名单、倍率查询集、目录分组、兜底名单、目录子目录\n     * 全部保持并入前的值。这里不是\"还没清理\"，而是刻意不动 ——\n     * 手里拿着 SOLO 快照的人没有重导的机会（独立客户端已经装不回来了），\n     * 任何一项跟着 CN 改都会让他们在某次重启之后突然掉模型、掉倍率、掉档位。\n     */\n    functions: [...TRAE_FUNCTIONS],\n    /** 历史查询集（9 个可推理名 + 只在注册表里出现的 `assistant` / `builder`）。 */\n    rateFunctions: [...TRAE_FUNCTIONS, \"assistant\", \"builder\"],\n    catalogGroups: [\"solo_agent_lite\", \"solo_coder\", \"solo_work_lite\", \"solo_agent_remote\", \"solo_work_remote\", \"solo_design_lite\", \"solo_design_remote\"],\n    fallbackModels: [...FALLBACK_TRAE_MODELS],\n    /** 历史路径，逐字保留 —— 已有的 SOLO 快照不用重导也能继续跑。 */\n    catalogSubdir: \"trae\",\n  },\n};\n\n/**\n * 手上没有任何凭据可依据时，按哪个产品接线（目录路径、槽位、状态标签的兜底）。\n *\n * 2026-10-11 从 `solo` 翻成 `cn`：独立客户端 TRAE SOLO CN 已被并进 Trae CN IDE，\n * 新装的人只会装 IDE，`export-trae-plain.mjs` 的默认也是 `--app cn`。\n * 继续兜到 SOLO 会让一个还没登录过的新渠道在面板上自称「已并入的旧产品」。\n *\n * ⚠️ 这次翻转**碰不到任何存量快照**：老快照一定带 `appVersionCode`（v1 就有），\n * 由 {@link resolveProduct} 的嗅探显式认成 solo，不再靠这条兜底猜。\n */\nexport const TRAE_DEFAULT_PRODUCT = \"cn\";\n\n/**\n * 思考档位映射：Trae 线上值 → pi-ai 的档位键。\n *\n * Trae 只有三个值（服务端下发的 `options` 与客户端常量表里都只出现它们）：\n *   `light` → 轻、`high` → 高、`extra_high` → 极高\n * 依次对应 pi-ai 的 `low` / `high` / `xhigh`。\n *\n * ⚠️ 不能照搬 Qoder/WorkBuddy 的 `low/medium/high/xhigh/max`：Trae 对不认识的\n * 值会**静默忽略**（实测乱填同样返回 200），错值不报错、只会让人误判\"档位无效\"。\n *\n * 这张表是**唯一事实来源**，声明（正向）与请求（反向）都从这里取，\n * 免得两处各写一份而漂移。\n */\nconst TRAE_EFFORT_TO_LEVEL = {\n  light: \"low\",\n  high: \"high\",\n  extra_high: \"xhigh\",\n};\n/** 反向查表：pi-ai 档位键 → Trae 线上值。 */\nconst LEVEL_TO_TRAE_EFFORT = new Map(\n  Object.entries(TRAE_EFFORT_TO_LEVEL).map(([wire, level]) => [level, wire]),\n);\n\n/** 流式请求在两次数据之间允许的最长静默。 */\nconst TRAE_STREAM_IDLE_TIMEOUT_MS = 300000;\n\n/** pi-ai 模型描述里要显式写 0，否则计费面板会按未知价格处理。 */\nconst NO_COST = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 };\nconst REQUEST_IMAGE_BUDGETS = {\n  maxRequestImageBytes: 20971520,\n  requestImagePixelBudget: 4194304,\n  requestImageMaxBytes: 1048576,\n};\n\n/**\n * pi-ai 的 auth 平面在本插件里必须是惰性的：认证只走 shim 的共享密钥，\n * 由 `resolveApiKey` 每个请求现取，pi-ai 自己不该凭空造一份凭据出来。\n */\nconst INERT_AUTH = {\n  credentials: {\n    async read() {},\n    async list() { return []; },\n    async modify() { throw new Error(\"dsh-trae-connect: the trae route has no pi-ai credential lifecycle\"); },\n    async delete() {},\n  },\n  authContext: {\n    async env() {},\n  },\n};\n\n//#endregion\n//#region 配置\n\n/**\n * ⚠️ **本模块不导出 `Config`，也不接受用户配置**（2026-10-08 收口）。\n *\n * ## 为什么\n *\n * 三合一时（见 lib/index.js 头注释）各渠道被有意收编为**内部子模块**：\n * `lib/index.js` 以 `apply(ctx, {})` 手动调起 —— 第二个参数恒为空对象，\n * 这里导出的 `Config` 对宿主**不可见**（宿主只认 bundle 入口\n * `lib/index.js` 的 `Config`，即面板那段 HUB_SECTION）。\n *\n * 保留 schema 的后果是**双重误导**：\n *   - 读者会以为这些键可以设；\n *   - 注释里\"设为 false 退回纯聊天\"之类的承诺实际不成立 —— 逃生阀不存在。\n *\n * 因此 20 个键（含默认值语义）从 schema 撤下，代码内的读取点保持\n * `config?.x` / `current().x` 原样：config 恒空时自然落到内置默认，\n * **运行时行为与收口前逐字节一致**（有 17 个确定性探针钉着）。\n *\n * ## 这里保留的一段防回归知识\n *\n * schemastery 没有 `z.enum()`：可选值必须用 `z.union([z.const(...), …])` 表达。\n * 写成 `z.enum` 会在模块求值阶段抛 TypeError，整个插件（含 workbuddy /\n * qoder 两个渠道）一起加载失败 —— 见 probes/verify-provider-config-schema.mjs。\n * 将来若把某个键重新接成可配置项，仍然要守这条。\n *\n * @param {Record<string, never>} _config 恒为 `{}`（由 lib/index.js 传入）\n */\n\n// schemastery 没有 z.enum()：可选值用 z.union([z.const(...), ...]) 表达。\n// 写成 z.enum 会在模块求值阶段抛 TypeError，整个插件（含 workbuddy /\n// qoder 两个渠道）一起加载失败 —— 见 probes/verify-provider-config-schema.mjs。\n\n/**\n * 解析路径默认值 —— 必须在 DSH_HOME 可用之后才能求值。\n *\n * [2026-09-25] 认证统一收进 `$DSH_HOME/connect-auth/`：迁移或多端部署时只需搬这一个目录，\n * 不必再逐渠道记路径。旧位置 `$DSH_HOME/trae/credential.json` 仍可通过\n * `credentialFile` 配置项指回（`scripts/export-connect-credentials.mjs restore` 会搬运）。\n */\nfunction defaultCredentialPath() {\n  return join(resolveDshHome(), \"connect-auth\", \"trae.json\");\n}\n/**\n * 模型目录缓存 —— 这不是凭据，留在 `$DSH_HOME` 下，但**按产品分目录**。\n *\n * SOLO 用历史路径 `$DSH_HOME/trae/models.json`（逐字不变，已有的快照不用重导），\n * Trae CN 用 `$DSH_HOME/trae-cn/models.json`。两份目录的分组名、上下文窗口、档位\n * 都是各产品自己的数据，混用会把 CN 的 1M 窗口配到 SOLO 的 function 名上。\n */\nfunction defaultCatalogPath(product) {\n  return join(resolveDshHome(), (product ?? TRAE_PRODUCTS[TRAE_DEFAULT_PRODUCT]).catalogSubdir, \"models.json\");\n}\n\n/**\n * 这条凭据属于哪个产品。优先级：**配置强制** > **快照声明** > **嗅探** > 现役产品兜底。\n *\n * 为什么以快照为主、配置只做覆盖：token 是**从哪个 App 导出来**的就属于那个产品，\n * 用配置把一份 SOLO 的 token 硬说成 CN，只会在上游换来 4001/4023 这种指不到根因的错。\n * 反过来（快照是 CN、配置覆盖成 SOLO）是能跑的 —— CN 账号实测能吃 SOLO 的 function，\n * 但那样做只会少模型，所以真需要时才有意义。\n *\n * 两条嗅探（`packageType` / `appVersionCode`）是**双向**的，认不出的才落到兜底。\n * 之所以敢双向：老快照（`formatVersion` 1）虽然不带 `product` 字段，但一定带\n * `appVersionCode`，而 SOLO 那个值在 {@link TRAE_PRODUCTS} 里逐字留着，\n * 所以存量 SOLO 用户永远走嗅探命中，不依赖兜底 —— 兜底才敢在 2026-10-11\n * 从 solo 翻成 cn（{@link TRAE_DEFAULT_PRODUCT}）。\n */\nexport function resolveProduct(config, doc) {\n  const forced = typeof config?.product === \"string\" ? config.product : \"\";\n  if (forced === \"cn\" || forced === \"solo\") return TRAE_PRODUCTS[forced];\n  const declared = typeof doc?.product === \"string\" ? doc.product.trim() : \"\";\n  if (declared === \"cn\" || declared === \"solo\") return TRAE_PRODUCTS[declared];\n  const pkg = typeof doc?.packageType === \"string\" ? doc.packageType.trim().toUpperCase() : \"\";\n  if (pkg === \"TRAE_CN\" || pkg === \"TRAE\" || pkg === \"TRAE_I18N\") return TRAE_PRODUCTS.cn;\n  if (pkg.startsWith(\"SOLO_\")) return TRAE_PRODUCTS.solo;\n  const code = doc?.appVersionCode;\n  if (Number.isFinite(code)) {\n    // 先认 SOLO 的 buildId：它是\"老快照\"唯一的识别特征（见上面那段）。\n    if (code === TRAE_PRODUCTS.solo.appVersionCode) return TRAE_PRODUCTS.solo;\n    if (code === TRAE_PRODUCTS.cn.appVersionCode) return TRAE_PRODUCTS.cn;\n  }\n  return TRAE_PRODUCTS[TRAE_DEFAULT_PRODUCT];\n}\n\n//#endregion\n//#region 凭据与目录\n\n/** 读 JSON 文件；不存在或格式坏都返回 undefined，绝不抛。 */\nfunction readJsonFile(path) {\n  if (typeof path !== \"string\" || path.length === 0 || !existsSync(path)) return undefined;\n  try {\n    const parsed = JSON.parse(readFileSync(path, \"utf8\"));\n    return typeof parsed === \"object\" && parsed !== null ? parsed : undefined;\n  } catch {\n    return undefined;\n  }\n}\n\n/**\n * 当前生效的产品变体 —— **不校验 token 有效性**的轻量判定。\n *\n * `store.resolve()` 那份是「带过期校验、失败就抛」的正式路径；这里要的是另一种东西：\n * 目录（models.json 该读哪个目录）、倍率（该查哪些 function）、状态页（该显示哪个产品名）\n * 这三处都需要「现在按哪个产品接线」，但**都不能因为 token 过期就没答案** ——\n * 未登录时面板仍要显示「这是什么渠道、模型目录空不空」。\n *\n * 所以这里只读文件、不判过期；`resolve()` 那边每次也调同一个 {@link resolveProduct}，\n * 两处判定同源，不会出现「目录读 CN、请求发 SOLO」的分裂。\n */\nexport function activeProduct(config) {\n  const cfg = typeof config === \"function\" ? config() ?? {} : config ?? {};\n  return resolveProduct(cfg, readJsonFile(cfg.credentialFile || defaultCredentialPath()));\n}\n\n/** JWT payload（不验签，只用来读 exp 做提前预警）。 */\nfunction jwtExpirySeconds(token) {\n  const parts = String(token).split(\".\");\n  if (parts.length !== 3) return undefined;\n  try {\n    const payload = JSON.parse(Buffer.from(parts[1].replace(/-/g, \"+\").replace(/_/g, \"/\"), \"base64\").toString(\"utf8\"));\n    return typeof payload?.exp === \"number\" ? payload.exp : undefined;\n  } catch {\n    return undefined;\n  }\n}\n\n/**\n * 凭据读取器。每次 `resolve()` 都重新读盘 —— 宿主侧重新导出快照后无需重启 DSH\n * 即可生效，这与 WorkBuddy 那条路一致。\n */\nexport function createCredentialStore(options) {\n  const { config, logger } = options;\n  let lastWarn = 0;\n  return {\n    path: () => config().credentialFile || defaultCredentialPath(),\n    async resolve() {\n      const doc = readJsonFile(this.path());\n      if (doc === undefined || typeof doc.token !== \"string\" || doc.token.length === 0) {\n        throw new Error(`未登录：读不到 Trae 凭据快照（${this.path()}）。先在宿主机跑 scripts/export-trae-plain.mjs。`);\n      }\n      const exp = jwtExpirySeconds(doc.token);\n      if (exp !== undefined && exp * 1000 < Date.now()) {\n        const now = Date.now();\n        if (now - lastWarn > 3600000) {\n          lastWarn = now;\n          logger?.warn(`dsh-trae-connect: Trae token 已于 ${new Date(exp * 1000).toISOString()} 过期，请在 Trae 重新登录后重跑 export-trae-plain.mjs`);\n        }\n        throw new Error(\"Trae token 已过期；请在 Trae 桌面端重新登录后重跑 scripts/export-trae-plain.mjs。\");\n      }\n      /** 先定产品，后面每个字段都从它取默认值（避免半 CN 半 SOLO 的组合）。 */\n      const product = resolveProduct(config(), doc);\n      return {\n        token: doc.token,\n        userId: typeof doc.userId === \"string\" ? doc.userId : \"\",\n        /** 展示用账号名（Trae 的 `account.username`，形如 `用户7381384633`）。 */\n        account: typeof doc.account?.username === \"string\" ? doc.account.username : \"\",\n        gateway: config().gateway || doc.gateway || DEFAULT_GATEWAY,\n        /** 签到与额度打的是账号网关，与推理网关不同。 */\n        accountBase: config().accountBase || doc.host || DEFAULT_ACCOUNT_BASE,\n        appId: config().appId || doc.appId || DEFAULT_APP_ID,\n        /**\n         * **产品变体**（cn / solo）—— 一次读盘只判一次，随凭据一起往外传，\n         * 让 function 白名单、`req_source`、目录路径、状态标签都用同一个判定结果，\n         * 免得出现「模型目录按 CN 读、签到按 SOLO 发」这种自相矛盾的请求。\n         */\n        product: resolveProduct(config(), doc),\n        appVersionCode: config().appVersionCode ?? doc.appVersionCode ?? product.appVersionCode,\n        /**\n         * 设备号，**写接口必需**（签到 claim 缺它会回 9004）。\n         * 由 export-trae-plain.mjs 从 storage.json 的 `iCubeAuthInfo://icube-dc:<id>` 键取出。\n         * 缺了不阻止插件启动 —— 只读功能（模型、额度、签到状态）都还能用。\n         */\n        deviceId: typeof doc.deviceId === \"string\" ? doc.deviceId : \"\",\n        /** ISO 串（导出脚本从 JWT 的 exp 取），供界面显示有效期。 */\n        expiresAt: typeof doc.expiredAt === \"string\" ? doc.expiredAt : undefined,\n      };\n    },\n    async current() {\n      try {\n        return await this.resolve();\n      } catch {\n        return undefined;\n      }\n    },\n  };\n}\n\n/**\n * 模型目录 = **快照（名单与上下文窗口）** ＋ **实时倍率层**。\n *\n * 两层的来源与生命周期完全不同，所以这里显式分开：\n *\n * 1. **名单层**：`models.json` 快照（`export-trae-plain.mjs` 从 state.vscdb 导出）。\n *    它决定\"有哪些模型、上下文多大\"——这些值随 App 版本变，但变化很慢，\n *    而且是**必须**由宿主导出的（容器看不到 macOS 的 state.vscdb）。\n * 2. **倍率层**：运行时打 `POST /api/ide/v1/batch_get_detail_param` 现取，\n *    见 {@link createTraeRateClient}。倍率是**定价**，随促销/活动变，不该固化进文件。\n *\n * 叠加规则：live 值优先；拿不到（未启用/首次未回/该模型不在上游清单里）时，\n * 退回快照自带的 rate —— 老版本导出脚本写的离线倍率因此仍然是可用的兜底，\n * 不会因为一次网络抖就把整个倍率列清空。\n *\n * ⚠️ 重建对象时**必须显式透传 rate 三兄弟**。catalog 是按白名单字段重建的，\n * 早先只取 id/name/contextWindow/maxTokens/supportsImages 五项，rate 就算在\n * 上游/快照里存在也会在这里被静默丢掉 —— 表现就是\"trae 永远没有倍率\"，\n * 而且没有任何报错。这类\"重建时漏字段\"的 bug 只能靠逐层比对发现。\n */\nexport function createCatalog(options) {\n  const { config } = options;\n  /** 当前产品（cn / solo）——兜底名单与默认目录路径都跟着它走。 */\n  const product = () => activeProduct(config);\n  /** 名单层：文件/兜底名单解析出来的条目（含文件自带的离线 rate，作兜底）。 */\n  let base = [...product().fallbackModels];\n  /** 倍率层：`id → {rate, rateDiscount, rateActivity}`，来自上游注册表。 */\n  let rates = new Map();\n  let ratesSource = \"none\";\n  let ratesFetchedAt = 0;\n  let ratesError;\n  let models = [...product().fallbackModels];\n  let source = \"fallback\";\n\n  /** 把两层合成对外可见的模型列表。任何一层变化后都要调用。 */\n  const rebuild = () => {\n    models = base.map((m) => {\n      const live = rates.get(m.id);\n      const rate = live?.rate ?? m.rate;\n      const rateDiscount = live?.rateDiscount ?? m.rateDiscount;\n      const rateActivity = live?.rateActivity ?? m.rateActivity;\n      return {\n        id: m.id,\n        name: m.name,\n        contextWindow: m.contextWindow,\n        maxTokens: m.maxTokens,\n        supportsImages: m.supportsImages,\n        // 档位按 (模型 × function) 配对，原样带下去，由适配器按当前 function 取用。\n        ...(m.reasoningByGroup === undefined ? {} : { reasoningByGroup: m.reasoningByGroup }),\n        // 上下文窗口/Max 开关同上（rebuild 的输入来自 load 的 base，字段要在这里透传）。\n        ...(m.contextWindowByGroup === undefined ? {} : { contextWindowByGroup: m.contextWindowByGroup }),\n        ...(m.maxModeByGroup === undefined ? {} : { maxModeByGroup: m.maxModeByGroup }),\n        ...Number.isFinite(rate) ? { rate } : {},\n        ...Number.isFinite(rateDiscount) ? { rateDiscount } : {},\n        ...Number.isFinite(rateActivity) ? { rateActivity } : {},\n      };\n    });\n  };\n\n  const load = () => {\n    /**\n     * 每次重载都重新判定产品：用户换了一份别的 App 导出的快照（30 秒巡检内被发现），\n     * 目录就必须跟着换到那个产品的文件，否则 CN 的 token 配 SOLO 的模型清单，\n     * 面板里会看到一批上游根本不认识的模型名。\n     */\n    const p = product();\n    const doc = readJsonFile(config().modelCatalogFile || defaultCatalogPath(p));\n    const list = Array.isArray(doc?.models) ? doc.models : [];\n    const usable = list.filter((m) => m && typeof m.id === \"string\" && m.id.length > 0);\n    if (usable.length > 0) {\n      base = usable.map((m) => ({\n        id: m.id,\n        name: typeof m.name === \"string\" && m.name.length > 0 ? m.name : m.id,\n        contextWindow: Number.isFinite(m.contextWindow) && m.contextWindow > 0 ? m.contextWindow : 128000,\n        maxTokens: Number.isFinite(m.maxTokens) && m.maxTokens > 0 ? m.maxTokens : 16384,\n        supportsImages: m.supportsImages === true,\n        /**\n         * 档位配置**按 function 分别保留**。\n         *\n         * ⚠️ 这里曾经只挑固定几个字段，把 `reasoningByGroup` 整个丢掉了 ——\n         * 于是模型列表里再也看不到\"这个模型支持哪些思考档位\"，档位功能无从实现。\n         * 注意它必须是 **per-function 的字典**：同一个模型在 solo_agent_lite 下\n         * 支持 light/high/extra_high，在 solo_work_lite 下 support_thinking=false。\n         */\n        ...(m.reasoningByGroup && typeof m.reasoningByGroup === \"object\" ? { reasoningByGroup: m.reasoningByGroup } : {}),\n        /**\n         * 上下文窗口**同样按 function 配对**（与 reasoningByGroup 同一批教训）：\n         * `deepseek-v4.1-flash` 在 solo_agent_lite 是 {dev:200000, max:1000000}，\n         * 在 solo_work_lite 只有 {dev:200000}。只存一个数会把 1M 丢掉。\n         * `maxModeByGroup[group]===true` 表示客户端 UI 有「更大上下文(Max)」开关。\n         */\n        ...(m.contextWindowByGroup && typeof m.contextWindowByGroup === \"object\" ? { contextWindowByGroup: m.contextWindowByGroup } : {}),\n        ...(m.maxModeByGroup && typeof m.maxModeByGroup === \"object\" ? { maxModeByGroup: m.maxModeByGroup } : {}),\n        ...Number.isFinite(m.rate) ? { rate: m.rate } : {},\n        ...Number.isFinite(m.rateDiscount) ? { rateDiscount: m.rateDiscount } : {},\n        ...Number.isFinite(m.rateActivity) ? { rateActivity: m.rateActivity } : {},\n      }));\n      source = \"snapshot\";\n    } else {\n      base = p.fallbackModels.map((m) => ({ ...m }));\n      source = \"fallback\";\n    }\n    rebuild();\n  };\n  load();\n  return {\n    reload: load,\n    source: () => source,\n    current: () => models,\n    /**\n     * 灌入上游实时倍率。\n     *\n     * 全量替换而非合并：上游是**权威**，某个模型这次没返回就是\"上游不再给这个价\"，\n     * 继续留着上一次的值只会让人以为它还有效。没被覆盖的模型会退回快照兜底\n     * （见 {@link rebuild}），所以不会出现\"整列消失\"。\n     */\n    setRates(map) {\n      rates = map instanceof Map ? map : new Map();\n      ratesSource = \"live\";\n      ratesFetchedAt = Date.now();\n      ratesError = undefined;\n      rebuild();\n    },\n    /**\n     * 清空倍率层（换账号时用）。\n     *\n     * 倍率是**账号级**的（会员折扣、活动价都挂在账号上），沿用上一个账号的数值\n     * 不只是显示错了 —— 还会让下一次刷新的\"降级保护\"拿旧账号的覆盖数当基线，\n     * 从而误判新账号的正常响应为残缺。所以换账号先把基线清掉。\n     */\n    clearRates() {\n      rates = new Map();\n      ratesSource = \"none\";\n      ratesFetchedAt = 0;\n      ratesError = undefined;\n      rebuild();\n    },\n    /** 记录一次失败的刷新：保留旧值，只留错误信息，且把时间推前避免疯狂重试。 */\n    markRatesFailed(error) {\n      ratesFetchedAt = Date.now();\n      ratesError = briefMessage(error);\n    },\n    ratesSource: () => ratesSource,\n    ratesFetchedAt: () => ratesFetchedAt,\n    ratesError: () => ratesError,\n    /** 当前展示的模型里，有多少个真的拿到了 live 倍率（诊断用）。 */\n    rateCoverage: () => {\n      let covered = 0;\n      for (const m of models) if (rates.has(m.id)) covered += 1;\n      return { covered, total: models.length };\n    },\n  };\n}\n\n//#endregion\n//#region 请求/响应形状转换\n\n/**\n * 模型 id 里可以写 `@<function>` 覆盖默认 function，例如\n * `DeepSeek-V4-Flash-Official@refactor`。这样既保持了模型选择器里的名字干净，\n * 又不必为每个 function 各铺一份模型列表。\n *\n * ⚠️ 白名单**按产品传进来**：`solo_coder` 在 SOLO 下有效、`chat_v3` 在 CN 下有效，\n * 拿一张全局表放行等于让用户写出一个上游必然拒绝的组合（而且上游只回\n * `no function config found`，看不出是「产品不对」）。\n *\n * 后缀不认识时**只退回默认 function，模型名保持原样**（含那个 `@bogus`）—— 这是上游\n * 历史行为，这里刻意不改：静默剥掉后缀会让拼错的 function 悄悄按默认槽位跑（档位与\n * 上下文窗口都可能不同），比让上游报一句 `model is unknown` 更难查。\n */\nexport function decodeModelId(raw, fallbackFunction, allowedFunctions) {\n  const id = typeof raw === \"string\" ? raw : \"\";\n  const at = id.lastIndexOf(\"@\");\n  if (at > 0) {\n    const fn = id.slice(at + 1);\n    const model = id.slice(0, at);\n    if (Array.isArray(allowedFunctions) && allowedFunctions.includes(fn)) return { model, functionName: fn };\n  }\n  return { model: id, functionName: fallbackFunction };\n}\n\n/** 文本片段 → Trae 的 LLMRawMessageContent。 */\nfunction textPart(text) {\n  return { type: \"text\", text };\n}\n\n/**\n * 清理「模型在拿不到工具时自编 agent 标记」的残留。\n *\n * ## 现象（2026-10-08 实测）\n *\n * Trae 的 `solo_agent` 槽位内置了 Trae 自家的 agent 模板。当一轮请求\n * **没有携带 `tools`**、却带着 DSH 的 agent 身份提示时，模型会按它被训练的\n * 方式扮演 agent，而不是正常回答：\n *\n *   · 吐出 GLM 系列的原生工具标记（**整段出现在正文里**）：\n *     `<seed:tool_call><function name=\"bash\"><parameter name=\"command\" ...>`\n *   · 或在正文开头复述任务：`The user says: '...` / `The user asks: ...`\n *\n * 实测 5 种请求形状 × 2 个 function 槽位都出现过，且**不固定**（同一输入\n * 一次吐标记、一次正常回答），所以\"换个槽位\"绕不开。\n *\n * ## 为什么在这里清洗\n *\n * 上游的 agent 模板我们控制不了，但**下发给 DSH 的内容**可以清洗 —— 这正是\n * 适配层的职责：把上游不合规的输出规整成 OpenAI 形状。\n *\n * ## 安全边界（重要）\n *\n * · 只在**该轮确实没发 tools** 时启用 —— 有工具时调用走结构化 `tool_calls`\n *   通道，正文里出现这些标记本身就是异常，此时清洗会掩盖真问题；\n * · 只删**成对**的标记，以及**整条以标记开头**的残片行。\n *\n * ⚠️ **未闭合残片不能\"删到结尾\"**（2026-10-08 修）。\n *\n * 上一版把未闭合形态写成 `/<seed:[^>]*>[\\s\\S]*$/` —— 语义是\"从这个标记一直删到\n * 本片结束\"。而本函数是按**内容分片**调用的，于是任何**提到**该标记的正常正文都会\n * 被截断，实测：\n *\n *   · `The tag <seed:tool_call> is emitted by GLM models. That is all.`\n *     → `The tag `（后半句全没了）\n *   · `You can write <seed:tool_call> in Trae.` → `You can write `\n *   · 代码块里的 ```` ```xml\\n<seed:tool_call>…</seed:tool_call>\\n``` ````\n *     会被挖空\n *\n * 也就是说原注释里\"正文中间正常提到这些词不会被误伤\"的保证**对成对标签和未闭合\n * 形态都不成立**。现在的规则收紧为：只有当标记**独占行首且该行剩余部分仍是标记\n * 形态**时才认定为残片（真正的残片一定长这样：上游把一整段调用标记塞在一行里，\n * 流被截断导致没有收尾标签）。正常行文提到标记时，行首是普通文字，不再命中。\n *\n * @param {string} text 上游正文分片\n * @param {boolean} toolsSent 本轮是否向上游发送了 tools\n * @param {boolean} [leading] 本分片是否是**本轮第一个**正文分片。\n *   只有它为 true 时才删\"行首复述前缀\"：本函数按分片调用，分片边界可能正好落在\n *   句子中间，此时该片\"行首\"其实是句中的词 —— 实测 `\"Sure. The \"` + `\"user says:\n *   hello was printed\"` 两片，第二片会被原实现删成 `\"hello was printed\"`，**句中\n *   的词被静默吃掉**。限制在首片即消除这个误伤（首片的行首才是真正的行首）。\n * @returns {string} 清洗后的正文（可能为空串）\n */\nexport function sanitizeAgentResidue(text, toolsSent, leading = true) {\n  if (toolsSent) return text;\n  if (typeof text !== \"string\" || text === \"\") return text;\n  let out = text;\n  // 1) 成对标记：GLM 原生 <seed:tool_call>…</seed:tool_call>、\n  //    <|FunctionCallBegin|>…<|FunctionCallEnd|>。\n  out = out.replace(/<seed:[^>]*>[\\s\\S]*?<\\/seed:[^>]*>/gi, \"\");\n  out = out.replace(/<\\|FunctionCallBegin\\|>[\\s\\S]*?<\\|FunctionCallEnd\\|>/g, \"\");\n  /**\n   * 2) 未闭合残片（流被截断时只收到半个标记）。\n   *\n   * 这里必须\"删到片尾\"—— 残片本身就是没有收尾标签的半截调用，只删标记本身会把\n   * `<function name=\"bash\">` 这类残骸留在正文里。所以维持原语义，但**收紧触发条件**：\n   * 只有当标记是**真实调用形态**（后面跟着 `<function`／`{`／`[` 这类调用内容）\n   * 时才删到结尾。这样：\n   *   · 真残片 `<seed:tool_call><function name=\"bash\">` → 清掉 ✓\n   *   · 正常行文 `The tag <seed:tool_call> is emitted by GLM.` → 标记后面是普通\n   *     英文/空格，不匹配，**不再截断后半句** ✓\n   */\n  out = out.replace(/<seed:[^>]*>\\s*(?=<function\\b|\\{|\\[)[\\s\\S]*$/gi, \"\");\n  out = out.replace(/<\\|FunctionCallBegin\\|>\\s*(?=<function\\b|\\{|\\[)[\\s\\S]*$/g, \"\");\n  // 3) 行首复述前缀。**只在本轮第一个内容分片里删**（见参数说明）。\n  //    `[ \\t]*` 而非 `\\s*`：不跨行吞并，避免把上一片留下的空行一起算进来。\n  if (leading === true) {\n    out = out.replace(/^[ \\t]*(?:the\\s+)?user(?:\\s+\\w+){0,2}\\s*(?:says|asks|wants|requests)\\s*[:：][ \\t]*/i, \"\");\n    out = out.replace(/^[ \\t]*(?:用户|提问者)\\s*(?:想要|要求|说|问)\\s*[:：][ \\t]*/, \"\");\n  }\n  return out;\n}\n\n/**\n * OpenAI `tools` → Trae `tools`。\n *\n * ## 为什么这个函数存在（2026-10-08 实测）\n *\n * 在此之前插件**从不向上游发送 `tools`**，模型因此看不到任何工具定义，\n * DSH 的 agent 回合只能失败：模型要么自造 Trae 原生文本标记\n * （`<|FunctionCallBegin|>[{\"name\":...}]<|FunctionCallEnd|>`，漏成正文），\n * 要么直接空回合收场。实测三个在用的模型（glm-5.3-flash / deepseek-v4.1-flash /\n * qwen3.8-flash）在**带上 tools 时全部返回结构化 `tool_calls`** ——\n * 缺口一直在插件侧，不在模型、也不在上游。\n *\n * ## 唯一必须记住的上游契约\n *\n * `tools[].function.parameters` 必须是 **JSON 字符串**，不能是对象：\n *   · 传对象 → HTTP 400 + code 4001：\n *     `json: cannot unmarshal object into Go struct field\n *      FunctionDefinition.tools.function.parameters of type string`\n *   · 传字符串 → 正常接受（实测）\n * 对照：某同题材插件的 `raw-chat.ts` 把 parameters 声明成 object，而那份文件\n * 开头自称 \"Evidence-bounded … draft … the upstream remains disabled until one\n * controlled probe\" —— 即从未通过实测。**以本函数的写法为准。**\n */\nexport function toTraeTools(tools) {\n  if (!Array.isArray(tools)) return undefined;\n  const out = [];\n  for (const t of tools) {\n    const fn = t?.function;\n    if (typeof fn?.name !== \"string\" || fn.name === \"\") continue;\n    let parameters;\n    if (typeof fn.parameters === \"string\") parameters = fn.parameters;\n    else if (fn.parameters === undefined || fn.parameters === null) parameters = \"{}\";\n    else {\n      try {\n        parameters = JSON.stringify(fn.parameters);\n      } catch {\n        parameters = \"{}\";\n      }\n    }\n    out.push({\n      type: \"function\",\n      function: {\n        name: fn.name,\n        ...(typeof fn.description === \"string\" && fn.description !== \"\" ? { description: fn.description } : {}),\n        parameters,\n      },\n    });\n  }\n  return out.length > 0 ? out : undefined;\n}\n\n/**\n * OpenAI `assistant.tool_calls` → Trae `assistant.tool_calls`。\n *\n * ## 为什么是 `function_call` 而不是 `function`（2026-10-08，两请求实测）\n *\n * 上游认**自己响应里的那种形状**（`function_call{name,arguments}`，且紧跟的\n * tool 消息**不带** `tool_call_id`）：\n *   · 形状 A（OpenAI 原味 `function{name,arguments}` + `tool_call_id`）\n *     → HTTP 200 但**零 output 事件**，静默失败：模型完全看不到这次往返\n *   · 形状 B（`function_call{name,arguments}`，tool 消息不带 tool_call_id）\n *     → 200 且模型正确接续（实测回复\"北京目前气温7℃…建议你穿上外套\"）\n * A 的失败形态是**静默**的，不会报错，只会让 agent 回合莫名空转 —— 所以这里\n * 必须用 B，且不能\"顺手\"补上 tool_call_id。\n */\nexport function toTraeToolCalls(toolCalls) {\n  if (!Array.isArray(toolCalls)) return undefined;\n  const out = [];\n  for (const tc of toolCalls) {\n    const fn = tc?.function ?? tc?.function_call;\n    if (fn === undefined || fn === null) continue;\n    const name = typeof fn.name === \"string\" ? fn.name : \"\";\n    let args = fn.arguments;\n    if (args !== undefined && args !== null && typeof args !== \"string\") {\n      try {\n        args = JSON.stringify(args);\n      } catch {\n        args = \"\";\n      }\n    }\n    out.push({\n      id: typeof tc?.id === \"string\" ? tc.id : \"\",\n      type: \"function\",\n      function_call: { name, arguments: typeof args === \"string\" ? args : \"\" },\n    });\n  }\n  return out.length > 0 ? out : undefined;\n}\n\n/**\n * OpenAI `role:\"tool\"` 消息的正文 → 文本。\n *\n * 工具结果可能是字符串，也可能是内容片段数组（pi-ai 两种都会发）。\n * 非字符串内容一律 JSON 化，避免工具结果被静默丢掉。\n */\nfunction toolResultText(content) {\n  if (typeof content === \"string\") return content;\n  if (Array.isArray(content)) {\n    const texts = [];\n    for (const p of content) {\n      if (typeof p === \"string\") texts.push(p);\n      else if (typeof p?.text === \"string\") texts.push(p.text);\n    }\n    if (texts.length > 0) return texts.join(\"\");\n  }\n  if (content === undefined || content === null) return \"\";\n  try {\n    return JSON.stringify(content);\n  } catch {\n    return String(content);\n  }\n}\n\n/**\n * OpenAI `messages` → Trae `messages`。\n *\n * Trae 的 `content` 是对象数组，不是字符串；图片按 `image_url` 形状透传，\n * 服务端不认识时会自行忽略，不会让整个请求失败。\n *\n * 工具往返：`assistant.tool_calls` 与 `role:\"tool\"` 的**正文都必须保留**，\n * 否则多轮 agent 会话断链（模型看不到自己请求过什么、也看不到工具结果）。\n * 形状细节见 `toTraeToolCalls`。\n */\nexport function toTraeMessages(messages, inlineSystemPrompt) {\n  const out = [];\n  /** 被并入首条 user 消息的 system 文本。 */\n  const systemTexts = [];\n  for (const m of Array.isArray(messages) ? messages : []) {\n    const role = typeof m?.role === \"string\" ? m.role : \"user\";\n    const parts = [];\n    const pushText = (t) => { if (typeof t === \"string\" && t.length > 0) parts.push(textPart(t)); };\n    if (typeof m?.content === \"string\") {\n      pushText(m.content);\n    } else if (Array.isArray(m?.content)) {\n      for (const p of m.content) {\n        if (p?.type === \"text\" && typeof p.text === \"string\") pushText(p.text);\n        else if (p?.type === \"image_url\" && p.image_url?.url) parts.push({ type: \"image_url\", image_url: { url: p.image_url.url } });\n      }\n    }\n    /**\n     * `developer` 是 OpenAI 对系统提示的新拼写（pi-ai 对声明 reasoning 的模型用它）。\n     * 语义等同 `system`：必须并进 system 分支，否则会掉进下面的兜底逻辑被当成\n     * `user`，把系统指令当用户输入发出去。\n     */\n    if (role === \"system\" || role === \"developer\") {\n      if (inlineSystemPrompt) {\n        for (const p of parts) if (typeof p.text === \"string\") systemTexts.push(p.text);\n        continue;\n      }\n      if (parts.length === 0) continue;\n      out.push({ role: \"system\", content: parts });\n      continue;\n    }\n    /**\n     * 工具结果：正文可能不是片段数组（pi-ai 会给字符串），单独走一遍转换。\n     * `tool_call_id` **刻意不带** —— 带上会让上游静默丢弃整段历史（见上文实测）。\n     */\n    if (role === \"tool\" || role === \"function\") {\n      const result = toolResultText(m?.content);\n      if (result === \"\" && parts.length === 0) continue;\n      out.push({ role: \"tool\", content: [textPart(result)] });\n      continue;\n    }\n    /**\n     * assistant 的工具调用请求：只保留正文非空的消息会让这一轮彻底消失，\n     * 所以下面 `parts.length === 0` 的提前返回对它必须放行。\n     */\n    const calls = role === \"assistant\" ? toTraeToolCalls(m?.tool_calls) : undefined;\n    if (parts.length === 0 && calls === undefined) continue;\n    const mapped = role === \"assistant\" ? \"assistant\" : \"user\";\n    out.push({\n      role: mapped,\n      content: parts.length > 0 ? parts : [textPart(\"\")],\n      ...(calls === undefined ? {} : { tool_calls: calls }),\n    });\n  }\n  if (systemTexts.length > 0) {\n    const prefix = textPart(systemTexts.join(\"\\n\\n\"));\n    const firstUser = out.find((m) => m.role === \"user\");\n    if (firstUser === undefined) out.unshift({ role: \"user\", content: [prefix] });\n    else firstUser.content = [prefix, ...firstUser.content];\n  }\n  if (out.length === 0) out.push({ role: \"user\", content: [textPart(\"\")] });\n  return out;\n}\n\n/** Trae function 被拒时，服务端返回的是这句；翻译成人话。 */\nfunction explainTraeError(message, allowedFunctions) {\n  const text = typeof message === \"string\" ? message : String(message ?? \"\");\n  const noFn = /no function config found for appId=\\S+, function=(\\S+)/.exec(text);\n  if (noFn !== null) {\n    const list = Array.isArray(allowedFunctions) && allowedFunctions.length > 0 ? allowedFunctions.join(\", \") : TRAE_FUNCTIONS.join(\", \");\n    return `Trae 未为该 appId 注册 function=\"${noFn[1]}\"（当前产品可用：${list}；换产品请用 export-trae-plain.mjs --app cn|solo 重导快照）`;\n  }\n  const unknownModel = /model is unknown/i.test(text);\n  if (unknownModel) return \"Trae 不认识这个模型名（先用 export-trae-plain.mjs 导出 models.json 取准确 id）\";\n  if (/param is invalid/i.test(text)) return \"Trae 拒绝了请求参数（4001）——多半是当前产品不支持这个 function，见面板的产品标签\";\n  if (/token|expired|unauthor/i.test(text)) return \"Trae 登录态失效，请重新登录后重跑 export-trae-plain.mjs\";\n  return text === \"\" ? \"Trae 上游返回了空错误\" : text;\n}\n\n//#endregion\n//#region 上游客户端\n\n/**\n * 上游客户端。`chatStream` 发一次 `/api/agent/v3/llm_utils_chat`，\n * 返回一个**已经把 Trae SSE 翻译成 OpenAI SSE** 的 ReadableStream，\n * 这样 shim 只要 pipe 出去就行。\n */\nexport function createTraeClient(options) {\n  const { logger } = options;\n  const endpoint = (gateway) => `${gateway.replace(/\\/+$/, \"\")}/api/agent/v3/llm_utils_chat`;\n\n  /**\n   * 发一次流式请求。\n   *\n   * 返回 `{ ok: true, response }`（response.body 是 OpenAI SSE）或\n   * `{ ok: false, status, kind, message }`。因为 Trae 永远回 HTTP 200 + SSE，\n   * 所以这里会先读到**首个事件**再决定是成功还是失败，避免已经把 200 写出去\n   * 才发现是错误。\n   */\n  async function chatStream(credential, body, signal) {\n    const url = endpoint(credential.gateway);\n    const payload = {\n      app_id: credential.appId,\n      app_version_code: credential.appVersionCode,\n      function: body.function,\n      model_name: body.model,\n      messages: body.messages,\n      stream: true,\n    };\n    if (Number.isFinite(body.maxTokens) && body.maxTokens > 0) payload.max_tokens = body.maxTokens;\n    /**\n     * 工具定义 —— **这一行是 agent 回合能不能跑起来的分水岭**。\n     *\n     * 不带 `tools` 时模型完全不知道有工具可用：它会自造 Trae 原生文本标记\n     * （`<|FunctionCallBegin|>…<|FunctionCallEnd|>`，于是漏成正文让用户看到一堆\n     * 怪东西），或者干脆空回合。带上之后实测三个在用的模型全部返回结构化\n     * `tool_calls`。字段形状细节与上游契约见 `toTraeTools`。\n     */\n    if (Array.isArray(body.tools) && body.tools.length > 0) {\n      payload.tools = body.tools;\n      if (typeof body.toolChoice === \"string\" && body.toolChoice !== \"\") payload.tool_choice = body.toolChoice;\n    }\n    /**\n     * 带档位时必须同时带 `custom_model` —— 档位字段挂在它里面。\n     *\n     * 字段照抄 Trae 客户端的真实请求（`renderer.log` 里的请求体），故意保持**完整**：\n     * 服务端按字段的存在性判断模型类型，少字段会被当成另一种模型处理。\n     * 空的写 `\"\"`/`null`、布尔的写 `false`，与客户端一致。\n     *\n     * ⚠️ **`config_source` 必须是数字 `1`，不能是字符串。**\n     * 这是整个功能最关键的一处坑：写成字符串时服务端解析不出模型来源，档位只被\n     * **部分**接受（同 prompt 下思考链的下降幅度明显小于正常档位差）；\n     * 改成数字后与 Trae App 内选同一档位的表现一致。\n     * （`1` 是内置模型的通用取值，见 `config_source` 枚举。）\n     */\n    if (body.effort !== undefined && body.effort !== null) {\n      payload.custom_model = {\n        provider: \"\",\n        is_preset: true,\n        config_name: body.model,\n        config_source: 1,\n        model_name: body.model,\n        display_model_name: body.model,\n        ak: \"\",\n        base_url: \"\",\n        use_remote_service: true,\n        multimodal: false,\n        prompt_max_tokens: null,\n        toolcall_history_max_tokens: null,\n        extra_config: null,\n        /**\n         * `persist_meta` 携带 Max 模式标记（2026-10-06 抓包实测）：\n         * Trae 客户端开「更大上下文(Max)」后，真实请求的 model_info 是\n         *   prompt_max_tokens: 936000   ← 从 168000 改成这个（≈1M 减预留）\n         *   persist_meta: {smart_selection:{strategy:\"max\", ...}}\n         * `context_window_sizes` 保持 null —— 窗口不在这个字段里表达。\n         * `body.maxMode` 由 shim 按当前 function 的目录声明算好传入。\n         */\n        persist_meta: body.maxMode === true\n          ? { smart_selection: { strategy: \"max\", fallback_to_advance_model: null, entitlement_id: null } }\n          : null,\n        raw_chat_function: null,\n        prompt_set: null,\n        context_window_sizes: null,\n        max_turn: null,\n        display_options: null,\n        max_tokens: null,\n        application_config: null,\n        sk: null,\n        auth_type: null,\n        region: null,\n        session_token: null,\n        custom_model_type: null,\n        reasoning_effort_level: body.effort,\n        /** Max 开启时同时改写 prompt_max_tokens（客户端实测值 936000 的来源见上）。 */\n        ...(body.maxMode === true && Number.isFinite(body.promptMaxTokens) && body.promptMaxTokens > 0\n          ? { prompt_max_tokens: body.promptMaxTokens }\n          : {}),\n      };\n    }\n    let response;\n    try {\n      response = await fetch(url, {\n        method: \"POST\",\n        headers: {\n          \"Content-Type\": \"application/json\",\n          Authorization: `Cloud-IDE-JWT ${credential.token}`,\n          \"x-ide-token\": credential.token,\n        },\n        body: JSON.stringify(payload),\n        signal,\n      });\n    } catch (error) {\n      return { ok: false, status: 0, kind: \"network\", message: `连不上 Trae 网关：${error instanceof Error ? error.message : String(error)}` };\n    }\n    if (!response.ok) {\n      const text = await response.text().catch(() => \"\");\n      return { ok: false, status: response.status, kind: response.status === 401 || response.status === 403 ? \"auth\" : \"upstream\", message: text.slice(0, 400) };\n    }\n    if (response.body === null) return { ok: false, status: response.status, kind: \"upstream\", message: \"Trae 返回了空响应体\" };\n\n    const reader = response.body.getReader();\n    const parser = createSseReader();\n    /**\n     * 先读首个事件：若上游直接报错，就在写响应头之前把它变成正经的 HTTP 错误。\n     *\n     * ⚠️ **两处都必须对**（2026-10-08 两次修，第一次只修了一半）：\n     *\n     *   1. 必须把这一批里剩余的事件一起带上。`parser.push()` 返回**整批**\n     *      已解析事件并清空内部队列，`events[1..]` 不接住就永久丢失。\n     *   2. **必须把同一个 parser 交给 translate 继续用**（第二次修）：\n     *      首读退出时 parser 里可能还留着**半截事件**（一个 TCP 分片正好切在\n     *      事件中间）和 `TextDecoder` 里不完整的多字节序列。上一版在\n     *      `translate` 里 `createSseReader()` 新建了一个 parser，于是这些残片\n     *      被丢掉 —— 丢掉的很可能是**带 id/name 的头部片**，剩下的参数分片\n     *      就变成「无名调用」，宿主按\"未知工具\"记进历史后，**对空名严格的\n     *      模型（deepseek 系）此后每一轮都 400/11133**（实测复现，见\n     *      workbuddy 侧 repairToolPairing 的注释）。done 事件也会一起丢，\n     *      导致真实的 `finish_reason`（如 `length`）被兜底硬编码成 `stop`。\n     */\n    let initialEvents = [];\n    while (initialEvents.length === 0) {\n      const { done, value } = await reader.read();\n      if (done) break;\n      initialEvents = parser.push(value);\n    }\n    const first = initialEvents[0];\n    if (first === undefined) return { ok: false, status: 502, kind: \"upstream\", message: \"Trae 流提前结束，没有读到任何事件\" };\n    if (first.event === \"error\") {\n      return { ok: false, status: 502, kind: \"upstream\", message: explainTraeError(first.data?.message, credential.product?.functions) };\n    }\n    return { ok: true, response: translate(reader, parser, initialEvents, body, signal, credential.product?.functions) };\n  }\n\n  /** 把已解析的 Trae 事件流翻译成 OpenAI SSE 字节流。 */\n  function translate(reader, parser, initialEvents, body, signal, allowedFunctions) {\n    const model = body.model;\n    const id = `chatcmpl-trae-${randomBytes(8).toString(\"hex\")}`;\n    const created = Math.floor(Date.now() / 1000);\n    const encoder = new TextEncoder();\n    let usage;\n    let finished = false;\n    /**\n     * 本轮是否出现过工具调用。用于把 done 的 `finish_reason` 从 `stop`\n     * 改写为 OpenAI 约定的 `tool_calls`（见下方 done 分支）。\n     */\n    let sawToolCall = false;\n    /**\n     * 本轮是否真的向上游发送了工具定义。\n     *\n     * 决定要不要对正文做 agent 模板清洗：带了 tools 时模型走结构化\n     * `tool_calls` 通道，正文里不该出现工具标记，此时出现的都是真内容；\n     * 没带 tools 时模型才会按 Trae agent 模板自编标记（见 sanitizeAgentResidue）。\n     */\n    const toolsSent = Array.isArray(body.tools) && body.tools.length > 0;\n    /**\n     * 本轮是否已经下发过正文分片。用于判断\"行首复述前缀\"该不该删\n     * （只在第一个分片删，见 sanitizeAgentResidue 的 `leading` 参数）。\n     */\n    let sawContentChunk = false;\n    /**\n     * 本轮收到过的上游 `error` 事件文案。\n     *\n     * 上游可能先发 error 事件、然后照常发 done（此时正文里已经有解释）；\n     * 也可能只发 error 就断流（此时若无提示，下游会把\"说一半\"当成完整回答）。\n     * 记下来，在\"没有 done 的兜底收尾\"时补一句，让截断始终可见。\n     */\n    let lastErrorHint;\n\n    const chunk = (delta, finishReason) => {\n      const payload = { id, object: \"chat.completion.chunk\", created, model, choices: [{ index: 0, delta, finish_reason: finishReason ?? null }] };\n      if (finishReason !== undefined && usage !== undefined) payload.usage = { prompt_tokens: usage.prompt_tokens ?? 0, completion_tokens: usage.completion_tokens ?? 0, total_tokens: usage.total_tokens ?? 0 };\n      return encoder.encode(`data: ${JSON.stringify(payload)}\\n\\n`);\n    };\n\n    /**\n     * 上游 `function_call` 形状 → 下游 OpenAI `function` 形状。\n     *\n     * ## 上游实测的流式形态（2026-10-08 抓包，见 `~/.dsh/trae-toolcall-raw-sample.txt`）\n     *\n     * 一次工具调用会分 **5 个** output 事件下发，形状和 OpenAI **不同**：\n     * ```\n     * #0 {\"index\":0,\"id\":\"call_xxx\",\"type\":\"function\",\n     *     \"function_call\":{\"name\":\"write_note\",\"arguments\":\"\"}}\n     * #1 {\"index\":0,\"id\":\"\",\"type\":\"\",\n     *     \"function_call\":{\"name\":\"\",\"arguments\":\"{\\\"path\\\": \\\"/tmp/x.md\\\", \\\"body\\\": \\\"\"}}\n     * #2..#4 同上，arguments 继续分片；partial_arguments 恒为 null\n     * ```\n     * 要点：\n     *   1. 字段名是 **`function_call`**，不是 OpenAI 的 `function`\n     *      —— 原样透传下游会认不出，等于工具调用被丢掉；\n     *   2. `id` / `name` / `type` **只在首片**有值，后续片一律是空串，\n     *      所以空串不能透传（会把已建立的名字覆盖成空）；\n     *   3. `index` 每片都有，下游按它累积 `arguments` ——\n     *      分片拼接后是合法 JSON（实测 4 片拼出完整对象）。\n     */\n    const normalizeToolCalls = (raw) => {\n      const out = [];\n      for (const tc of raw) {\n        if (tc === null || typeof tc !== \"object\") continue;\n        const fc = tc.function_call ?? tc.function ?? {};\n        /**\n         * `index` 必须保留 0 兜底（与 OpenAI 首片一致）。\n         *\n         * ⚠️ 不要改成\"缺失就不下发\"（2026-10-08 试过，被\n         * `verify-trae-tool-calling` 的端到端断言当场抓住）：上游的参数分片靠\n         * `index` 标识自己属于哪一次调用，缺了它下游无法累积参数，拼接后直接是\n         * 非法 JSON（`Unexpected end of JSON input`）。\n         *\n         * 这里的 `?? 0` 与上游实测形状一致：一次调用的所有分片（首片 + 4 个参数片）\n         * `index` 全是 0，多个并行调用才递增。真实风险是\"两次调用都缺 index 而\n         * 撞在 0 上\"，但按上游契约并行调用一定带 index，所以维持兜底更安全。\n         */\n        const entry = { index: Number.isInteger(tc.index) ? tc.index : 0 };\n        if (typeof tc.id === \"string\" && tc.id !== \"\") entry.id = tc.id;\n        if (typeof tc.type === \"string\" && tc.type !== \"\") entry.type = tc.type;\n        const fn = {};\n        const name = typeof fc.name === \"string\" ? fc.name.trim() : \"\";\n        if (name !== \"\") fn.name = name;\n        /**\n         * `arguments` 一律保留**空串**（与 OpenAI 首片一致）：\n         * 下游靠这个键建立条目，缺了它首片就只剩 id/name。\n         */\n        if (typeof fc.arguments === \"string\") fn.arguments = fc.arguments;\n        else if (fc.arguments !== undefined && fc.arguments !== null) {\n          try {\n            fn.arguments = JSON.stringify(fc.arguments);\n          } catch {\n            fn.arguments = \"\";\n          }\n        } else fn.arguments = \"\";\n        entry.function = fn;\n        /**\n         * ⚠️ **不能按\"无名\"丢弃分片**（2026-10-08 试过，被 `verify-trae-tool-calling`\n         * 的端到端断言当场抓住）：参数分片天然既无 id 也无 name（只有 index 和\n         * arguments），丢掉它们等于把工具参数整段删掉，拼接后不是合法 JSON。\n         *\n         * 真正要防的是\"整次调用永远没拿到 name\"（首片丢失），而那属于**流解析**\n         * 的问题 —— 已在本文件的 parser 交接处修掉（见 chatStream 的注释）。\n         * 历史里已经存在的空名调用由 WorkBuddy shim 的 repairToolPairing 兜底，\n         * 那是唯一能同时覆盖\"历史已污染\"的位置。\n         */\n        out.push(entry);\n      }\n      return out;\n    };\n\n    return new ReadableStream({\n      start(controller) {\n        // `finished` = 已收到 done 或已收尾；`closed` = 流已真正关闭。两者必须分开：\n        // done 事件内部就会 close()，pump() 结尾再 close 一次会抛 ERR_INVALID_STATE。\n        let closed = false;\n        const closeStream = () => {\n          if (closed) return;\n          closed = true;\n          try { controller.close(); } catch { /* 已被下游取消 */ }\n        };\n        const enqueue = (bytes) => {\n          if (closed) return;\n          try { controller.enqueue(bytes); } catch { closed = true; }\n        };\n        const emit = (event) => {\n          if (finished || closed) return;\n          if (event.event === \"output\") {\n            const data = event.data ?? {};\n            const reasoning = typeof data.reasoning_content === \"string\" ? data.reasoning_content : \"\";\n            const raw = typeof data.response === \"string\" ? data.response : \"\";\n            if (reasoning.length > 0) enqueue(chunk({ reasoning_content: reasoning }));\n            /**\n             * 正文要过一道清洗：本轮没发 tools 时，模型可能按 Trae agent 模板\n             * 自编工具标记/复述前缀（实测会漏进正文，见 sanitizeAgentResidue）。\n             * 清洗只在这里发生，**不碰 reasoning_content** —— 思考链里出现\n             * \"用户说…\" 属于正常推理表述。\n             *\n             * `leading` 只在**第一个非空正文分片**为 true：分片边界可能落在句子\n             * 中间，\"行首前缀\"规则若每片都跑，会吃掉句中连续的词（见该函数注释）。\n             */\n            const isLeading = !sawContentChunk && raw.length > 0;\n            const content = sanitizeAgentResidue(raw, toolsSent, isLeading);\n            if (content.length > 0) {\n              sawContentChunk = true;\n              enqueue(chunk({ content }));\n            }\n            /**\n             * 工具调用：上游给的是 `function_call` 形状且分片下发，必须先归一\n             * （原样透传下游认不出，等于整轮工具调用被丢弃）。\n             */\n            if (Array.isArray(data.tool_calls) && data.tool_calls.length > 0) {\n              const calls = normalizeToolCalls(data.tool_calls);\n              if (calls.length > 0) {\n                sawToolCall = true;\n                enqueue(chunk({ tool_calls: calls }));\n              }\n            }\n            return;\n          }\n          if (event.event === \"token_usage\") { usage = event.data ?? {}; return; }\n          if (event.event === \"error\") {\n            const message = explainTraeError(event.data?.message, allowedFunctions);\n            lastErrorHint = message;\n            enqueue(chunk({ content: `\\n\\n[Trae 错误] ${message}` }));\n            return;\n          }\n          if (event.event === \"done\") {\n            finished = true;\n            /**\n             * 上游有工具调用时**也**报 `finish_reason:\"stop\"`（实测），\n             * 但 OpenAI 语义里必须报 `tool_calls` —— 下游据此决定要不要执行工具。\n             * 不改写的话，pi-ai 会把这一轮当成\"普通回答结束\"，工具永远不会被执行。\n             */\n            const upstreamReason = event.data?.finish_reason;\n            const finishReason = sawToolCall ? \"tool_calls\" : (upstreamReason ?? \"stop\");\n            enqueue(chunk({}, finishReason));\n            enqueue(encoder.encode(\"data: [DONE]\\n\\n\"));\n            closeStream();\n          }\n        };\n        const pump = async () => {\n          try {\n            for (const event of initialEvents) emit(event);\n            while (!finished && !closed) {\n              const { done, value } = await reader.read();\n              if (done) break;\n              for (const event of parser.push(value)) emit(event);\n            }\n            /**\n             * 流读完先冲一次残留：最后一个事件可能没有尾随空行（被截断的流尤其\n             * 常见），而它可能正是 `done` —— 不冲就会丢掉真实 `finish_reason`，\n             * 让兜底把它硬编码成 `stop`（截断与正常结束就分不出来了）。\n             */\n            if (!finished && !closed) {\n              for (const event of parser.end()) emit(event);\n            }\n            if (!finished) {\n              finished = true;\n              /**\n               * 流自然结束（上游没给 done）时的兜底 finish_reason。\n               * 同样要吃 `sawToolCall`：否则「有工具调用但 done 丢失」会被报成\n               * 普通文本结束，工具永远不会被执行 —— 与原 done 分支保持一致。\n               *\n               * ⚠️ 还有一种情况：`done` 事件带 `error` 之类的异常收尾。上游此刻\n               * 已经不会再补内容，若下游只看到 finish_reason，会以为模型正常\n               * 说完 —— 于是\"说一半\"被当成完整回答。这里补一句可见说明。\n               */\n              const upstreamHint = lastErrorHint;\n              if (upstreamHint !== undefined && upstreamHint !== \"\") {\n                enqueue(chunk({ content: `\\n\\n[Trae 提示] ${upstreamHint.slice(0, 200)}` }));\n              }\n              enqueue(chunk({}, sawToolCall ? \"tool_calls\" : \"stop\"));\n              enqueue(encoder.encode(\"data: [DONE]\\n\\n\"));\n            }\n            closeStream();\n          } catch (error) {\n            /**\n             * 上游中途断流（2026-10-08 修）。\n             *\n             * 修之前这里只补一个 `[DONE]`，**既不给 finish_reason 也不给任何\n             * 正文**。下游只看到一个毫无来由的流结束，于是表现为「模型说了一半\n             * 就断了、没有任何提示」—— 用户看到的是无声消失，而不是可诊断的\n             * 错误。这不是\"上游抖了一下\"，而是失败被吞掉了。\n             *\n             * 现在补齐三样东西，让失败**可见**：\n             *   1. 一条明确的错误正文（说明是上游断流，不是模型没话说）；\n             *   2. `finish_reason: \"error\"`（OpenAI 没有这个值，但下游只看\n             *      非 null 就知道这轮不正常，比静默收尾好；DSH 会把它标成失败）；\n             *   3. `[DONE]` 收尾，保证流不会挂住。\n             *\n             * 注意：此时**已下发的内容不回滚** —— 用户仍能看到模型说到的那部分，\n             * 再加一句明确说明为什么停在这里。\n             */\n            logger?.warn(\"dsh-trae-connect: upstream stream failed mid-flight\", error);\n            if (!finished) {\n              finished = true;\n              const reason = error instanceof Error && error.message !== \"\" ? error.message : String(error);\n              enqueue(chunk({ content: `\\n\\n[Trae 上游中断] 本轮回答未完成：${reason.slice(0, 200)}。可重试一次。` }));\n              enqueue(chunk({}, \"error\"));\n              enqueue(encoder.encode(\"data: [DONE]\\n\\n\"));\n            }\n            closeStream();\n          }\n        };\n        if (signal?.aborted === true) { finished = true; closeStream(); return; }\n        pump();\n      },\n      cancel() { finished = true; reader.cancel().catch(() => {}); },\n    });\n  }\n\n  return { chatStream };\n}\n\n/**\n * 账号侧客户端：额度（剩余积分）与每日签到。\n *\n * 与推理完全无关的第二个上游 —— 它在 `api.trae.cn` 而不是 `trae-api-cn.mchost.guru`，\n * 走 `/trae/api/v2/**` 命名空间。接口是从 App 的 `out/main.js` 里挖出来的：\n *\n *   fetchCheckinCreditsStatus() → eb(\"/trae/api/v2/ug/checkin_credits/status\",\"POST\",…)\n *   claimCheckinCredits()       → eb(\"/trae/api/v2/ug/checkin_credits/claim\",\"POST\",…)\n *   ide_user_ent_usage          → 额度（consumed_amount / total_amount / consumption_ratio）\n *\n * 全部是**只读或幂等**的账号操作，不碰推理额度：签到是领取、状态是查询。\n */\nexport function createTraeAccountClient(options) {\n  const { logger } = options;\n  const TIMEOUT_MS = 20000;\n\n  /** 打一次账号网关。失败一律抛，由调用方决定降级方式。 */\n  async function post(credential, path, label) {\n    const base = String(credential.accountBase || DEFAULT_ACCOUNT_BASE).replace(/\\/+$/, \"\");\n    let response;\n    try {\n      response = await fetch(`${base}${path}`, {\n        method: \"POST\",\n        headers: {\n          \"Content-Type\": \"application/json\",\n          Authorization: `Cloud-IDE-JWT ${credential.token}`,\n          \"x-ide-token\": credential.token,\n          // 写接口（claim）会校验它；缺失时回 9004「order parameters are incorrect」，\n          // 而只读接口（额度、签到状态）不校验 —— 所以漏了它只会在点击签到时才暴露。\n          ...(credential.deviceId ? { \"x-device-id\": credential.deviceId } : {}),\n        },\n        body: JSON.stringify({ req_source: credential.product?.reqSource ?? TRAE_REQ_SOURCE }),\n        signal: AbortSignal.timeout(TIMEOUT_MS),\n      });\n    } catch (error) {\n      throw new Error(`${label} 连不上 ${base}：${error instanceof Error ? error.message : String(error)}`);\n    }\n    const text = await response.text().catch(() => \"\");\n    if (!response.ok) throw new Error(`${label} 返回 HTTP ${response.status}：${text.slice(0, 200)}`);\n    try {\n      return JSON.parse(text);\n    } catch {\n      throw new Error(`${label} 返回的不是 JSON：${text.slice(0, 200)}`);\n    }\n  }\n\n  /** 数字字段的宽容读取：非有限数或负数一律当缺失。 */\n  const num = (value) => (typeof value === \"number\" && Number.isFinite(value) && value >= 0 ? value : undefined);\n\n  return {\n    /**\n     * 剩余积分。\n     *\n     * Trae 只给「已消耗 / 总额」，剩余要自己减 —— 实测 `usage_summary` 里没有 remain 字段。\n     * 拿不到 usage_summary 时抛，由状态文档降级成 `creditsError`，不影响签到等信息。\n     */\n    async fetchCredits(credential) {\n      const doc = await post(credential, ENTITLEMENT_USAGE_PATH, \"额度\");\n      const summary = doc?.usage_summary;\n      const total = num(summary?.total_amount);\n      const consumed = num(summary?.consumed_amount);\n      if (total === undefined && consumed === undefined) throw new Error(\"额度接口没有返回 usage_summary\");\n      // 相减会带出浮点毛刺（4250 - 3429.47 = 820.5300000000002），\n      // 在源头就收敛到 2 位 —— 服务端给的本就是两位小数。\n      const remain = total !== undefined && consumed !== undefined\n        ? Math.max(0, Math.round((total - consumed) * 100) / 100)\n        : undefined;\n      return {\n        total,\n        consumed,\n        remain,\n        ratio: num(summary?.consumption_ratio),\n        isCreditsBilling: doc?.is_credits_billing === true,\n        unlimited: false,\n      };\n    },\n\n    /** 签到状态。`credits` 是今天签到可得，`extraCredits` 是额外奖励。 */\n    async fetchCheckinStatus(credential) {\n      const doc = await post(credential, CHECKIN_STATUS_PATH, \"签到状态\");\n      return {\n        enable: doc?.enable === true,\n        checkedIn: doc?.checked_in === true,\n        didCheckedIn: doc?.did_checked_in === true,\n        credits: num(doc?.credits),\n        extraCredits: num(doc?.extra_credits),\n        code: typeof doc?.code === \"number\" ? doc.code : undefined,\n      };\n    },\n\n    /**\n     * 领取当日签到积分。\n     *\n     * 返回归一化的 `{state}`：`claimed` / `already-claimed` / `disabled` / `failed`。\n     * 先读一次状态是为了区分「刚领到」和「今天已经领过」—— claim 接口本身\n     * 只回 `{code, message}`，重复领取时 code 非 0 但语义是\"今天领过了\"，\n     * 光看 code 分不出来。\n     */\n    async claimDailyCheckin(credential) {\n      // 提前给出可执行的错误，而不是把服务端那句 9004 原样抛给用户 ——\n      // 9004 的文案（\"order parameters are incorrect\"）完全指不到真正的原因。\n      if (typeof credential.deviceId !== \"string\" || credential.deviceId === \"\") {\n        return {\n          state: \"failed\",\n          message: \"凭据快照里没有设备号，签到会被服务端拒绝；请在宿主重跑 scripts/export-trae-plain.mjs\",\n        };\n      }\n      let before;\n      try {\n        before = await this.fetchCheckinStatus(credential);\n      } catch (error) {\n        logger?.warn(\"dsh-trae-connect: 签到前读状态失败，直接尝试领取\", error);\n      }\n      if (before?.enable === false) return { state: \"disabled\", message: \"Trae 当前未开放签到\" };\n      if (before?.checkedIn === true) return { state: \"already-claimed\", checkin: before };\n      const doc = await post(credential, CHECKIN_CLAIM_PATH, \"签到\");\n      if (typeof doc?.code === \"number\" && doc.code !== 0) {\n        return { state: \"failed\", code: doc.code, message: typeof doc?.message === \"string\" ? doc.message : `业务码 ${doc.code}` };\n      }\n      let after;\n      try {\n        after = await this.fetchCheckinStatus(credential);\n      } catch { /* 领取已成功，状态刷新失败不影响结论 */ }\n      return { state: \"claimed\", checkin: after };\n    },\n  };\n}\n\n/**\n * 倍率注册表客户端 —— 运行时现取每个模型的消耗倍率。\n *\n * 端点 `POST {gateway}/api/ide/v1/batch_get_detail_param`（与推理同网关，\n * 命名空间是 `/api/ide/v1/**`）。请求体照抄 App 的抓包，响应约 1.4 MB。\n *\n * ## 三个头，一个都不能少（实测矩阵）\n *\n * | 头 | 缺失/异常时的表现 |\n * |---|---|\n * | `X-Ide-Token` | 401 + `code:1001` |\n * | `X-App-Id` | 200，但正文只剩 **1304 B**（空壳，没有任何 config） |\n * | `X-Ide-Version-Code` | 见下 —— **静默降级**，最坑 |\n *\n * `X-Ide-Version-Code` 不是一个\"版本校验\"头，而是**配置注册表的筛选键**：\n *\n * ```\n * 1227681842690 (凭据里的 buildId) → 200, 1.45 MB, 302 条 config   ← 正确取值\n * 20260912      (App 抓包里的值)    → 200, 1.45 MB\n * 20260101                          → 200, 0.12 MB（只回一部分）\n * 1 / 不带                          → 200, 6.5 KB（空壳）\n * 非数字                             → 400\n * ```\n *\n * 也就是说用错值**不会报错**，只会拿到一份看似正常、实则没有 `function_configs`\n * 的文档 —— 表现就是\"倍率全空\"。所以这里取凭据里的 `appVersionCode`（就是\n * product.json 的 buildId），而不是另设一个魔法常量。\n *\n * ## 取值路径\n *\n * ```\n * function_configs[].config_info_list[]\n *   ├─ config_name                          → 模型 id（与 models.json 的 id 同名）\n *   ├─ display_contact_config.consumption_rate.data.rate        → 倍率\n *   ├─ display_contact_config.discount.data.consumption_rate    → 会员折扣价\n *   └─ display_contact_config.activity_discount.data.current.consumption_rate → 活动价\n * ```\n *\n * `display_contact_config` 是**字符串化的 JSON**（不是对象），要先解一层。\n * 同一个模型会出现在多个 function 下，取值完全一致（实测 81 个模型 0 冲突）。\n */\n\n/** 把 `display_contact_config` 这类\"JSON 藏在字符串里\"的字段解出来。 */\nexport function parseEmbeddedJson(value) {\n  if (typeof value === \"object\" && value !== null) return value;\n  if (typeof value !== \"string\" || value.trim() === \"\") return undefined;\n  try {\n    const parsed = JSON.parse(value);\n    return typeof parsed === \"object\" && parsed !== null ? parsed : undefined;\n  } catch {\n    return undefined;\n  }\n}\n\n/**\n * 倍率的宽容读取：非有限数一律当缺失（上游会用 `null` 表示\"无活动价\"）。\n *\n * 同时容忍数字串（`\"0.78\"`）—— 上游同一份文档里 `rate` 是 number，\n * 但这类\"配置下发\"接口换个版本改成字符串是很常见的事，而 trae 的倍率一旦读不出来\n * 只会静默消失、不会报错，所以这里宁松勿紧（与 qoder 的 `toNumber` 一致）。\n */\nfunction rateNumber(value) {\n  if (typeof value === \"number\") return Number.isFinite(value) ? value : undefined;\n  if (typeof value === \"string\" && value.trim() !== \"\") {\n    const parsed = Number(value);\n    return Number.isFinite(parsed) ? parsed : undefined;\n  }\n  return undefined;\n}\n\n/**\n * 从注册表文档里抽出 `id → {rate, rateDiscount, rateActivity}`。\n *\n * 纯函数，不碰网络 —— 自检脚本直接喂一份抓包文档就能验，见\n * `scripts/trae-rates-selftest.mjs`。\n */\nexport function parseRateRegistry(doc) {\n  const map = new Map();\n  const configs = Array.isArray(doc?.function_configs) ? doc.function_configs : [];\n  for (const fn of configs) {\n    const list = Array.isArray(fn?.config_info_list) ? fn.config_info_list : [];\n    for (const entry of list) {\n      const id = typeof entry?.config_name === \"string\" ? entry.config_name.trim() : \"\";\n      if (id === \"\") continue;\n      const contact = parseEmbeddedJson(entry?.display_contact_config);\n      if (contact === undefined) continue;\n\n      // `consumption_rate.data.rate` 是当前生效倍率。少数只有会员折扣、没有\n      // consumption_rate 的模型（如 glm-5.3）要退回折扣块里的原价，否则整条会丢。\n      const discountData = parseEmbeddedJson(contact?.discount)?.data ?? contact?.discount?.data;\n      const activityData = parseEmbeddedJson(contact?.activity_discount)?.data ?? contact?.activity_discount?.data;\n      const rate = rateNumber(parseEmbeddedJson(contact?.consumption_rate)?.data?.rate)\n        ?? rateNumber(discountData?.original_consumption_rate)\n        ?? rateNumber(discountData?.consumption_rate);\n      const rateDiscount = rateNumber(discountData?.consumption_rate);\n      const rateActivity = rateNumber(activityData?.current?.consumption_rate);\n      if (rate === undefined && rateDiscount === undefined && rateActivity === undefined) continue;\n      // 先到先得：跨 function 取值一致，真出现冲突时不该由遍历顺序决定显示。\n      if (!map.has(id)) map.set(id, { id, rate, rateDiscount, rateActivity });\n    }\n  }\n  return map;\n}\n\nexport function createTraeRateClient(options) {\n  const { logger } = options;\n\n  /**\n   * 一次注册表请求。\n   *\n   * ⚠️ **必须分批**：`functions` 数组长度对上游延迟的影响是**非线性**的 —— 实测\n   * 同一份凭据、同一批模型，CN 侧 9 个 function 约 10 s 回全量，12 个就要 60 s 以上\n   * 直接超时（而且**不是慢、是整条请求被上游掐住**）。一次全查历史上是\n   * 「偶发拿不到倍率」的根因。\n   *\n   * 分批后单批小、失败只丢那一批的模型，其余照常返回；比整份失败要好得多。\n   */\n  async function fetchOne(credential, functions, signal) {\n    const base = String(credential.gateway || DEFAULT_GATEWAY).replace(/\\/+$/, \"\");\n    const url = `${base}${DETAIL_PARAM_PATH}`;\n    const body = {\n      functions: [...functions],\n      agent_type: '',\n      current_config_info: { config_name: '', is_custom_model: false },\n      mode_type: 0,\n      access_type: 1,\n      ab_force_vids: '',\n      ab_autotest_advanced_mode: 0,\n      show_custom_model: true,\n    };\n    let response;\n    try {\n      response = await fetch(url, {\n        method: \"POST\",\n        headers: {\n          \"Content-Type\": \"application/json\",\n          Accept: \"*/*\",\n          \"X-Ide-Token\": credential.token,\n          \"X-App-Id\": credential.appId || DEFAULT_APP_ID,\n          // 必须是**当前产品**的真实 buildId（现役 CN=1238630385922、旧 SOLO=1227681842690）；\n          // 用小值或拿错产品的值都会静默降级成空壳（见上方矩阵）。\n          \"X-Ide-Version-Code\": String(credential.appVersionCode ?? credential.product?.appVersionCode ?? TRAE_PRODUCTS[TRAE_DEFAULT_PRODUCT].appVersionCode),\n          ...(credential.deviceId ? { \"X-Device-Id\": credential.deviceId } : {}),\n          \"User-Agent\": \"TraeClient/TTNet\",\n        },\n        body: JSON.stringify(body),\n        signal: signal ?? AbortSignal.timeout(RATE_TIMEOUT_MS),\n      });\n    } catch (error) {\n      throw new Error(`倍率注册表连不上 ${base}：${error instanceof Error ? error.message : String(error)}`);\n    }\n    const text = await response.text().catch(() => \"\");\n    if (!response.ok) throw new Error(`倍率注册表返回 HTTP ${response.status}：${text.slice(0, 200)}`);\n    let doc;\n    try {\n      doc = JSON.parse(text);\n    } catch {\n      throw new Error(`倍率注册表返回的不是 JSON：${text.slice(0, 200)}`);\n    }\n    return parseRateRegistry(doc);\n  }\n\n  return {\n    /**\n     * 打注册表拿倍率表：按 {@link RATE_QUERY_CHUNK} 分批、顺序合并。\n     *\n     * 失败一律抛 —— 由调用方决定降级（保留上一次的值），这里不吞。\n     * 但**单批失败不影响其它批**：只有第一批就失败（多半是 token 或 buildId 不对）\n     * 才整体抛，否则返回已经拿到的那部分，界面上就是\"部分模型有倍率\"而不是整列空白。\n     */\n    async fetchRates(credential, functions, signal) {\n      const list = Array.isArray(functions) && functions.length > 0\n        ? [...new Set(functions.filter((n) => typeof n === \"string\" && n.trim() !== \"\").map((n) => n.trim()))]\n        : defaultRateFunctions(credential?.product);\n      const merged = new Map();\n      let failures = 0;\n      for (let i = 0; i < list.length; i += RATE_QUERY_CHUNK) {\n        const chunk = list.slice(i, i + RATE_QUERY_CHUNK);\n        try {\n          const part = await fetchOne(credential, chunk, signal);\n          for (const [id, value] of part) if (!merged.has(id)) merged.set(id, value);\n        } catch (error) {\n          failures += 1;\n          logger?.warn?.(`dsh-trae-connect: 倍率分批 ${i / RATE_QUERY_CHUNK + 1}（${chunk.join(\",\")}）失败 — ${briefMessage(error)}`);\n          // 一批都没成 → 直接抛，让调用方走\"沿用上一次的值\"那条路，\n          // 别把「一次网络抖」显示成「这个渠道没有倍率」。\n          if (merged.size === 0) throw error;\n        }\n      }\n      if (merged.size === 0) {\n        // 最常见的成因是 X-Ide-Version-Code 被降级（200 + 6.5 KB 空壳）——\n        // 把它写进错误信息，省得下次再去比对整份响应。\n        throw new Error(\"倍率注册表没有返回任何 consumption_rate（多半是 X-Ide-Version-Code 被降级，检查凭据里的 appVersionCode 与产品是否匹配）\");\n      }\n      logger?.info?.(`dsh-trae-connect: 倍率已刷新，上游给出 ${merged.size} 个模型的消耗倍率${failures > 0 ? `（${failures} 批失败）` : \"\"}`);\n      return merged;\n    },\n  };\n}\n\n/** 逐字节喂入的 SSE 读取器：`event:<name>\\n` + `data:<json>\\n\\n`。 */\nexport function createSseReader() {\n  const decoder = new TextDecoder();\n  let buffer = \"\";\n  let eventName = \"\";\n  const dataLines = [];\n  const pending = [];\n\n  const flush = () => {\n    if (eventName === \"\" && dataLines.length === 0) return;\n    const raw = dataLines.join(\"\\n\");\n    let data;\n    try { data = JSON.parse(raw); } catch { data = raw; }\n    if (raw !== \"\" || eventName !== \"\") pending.push({ event: eventName || \"message\", data });\n    eventName = \"\";\n    dataLines.length = 0;\n  };\n\n  return {\n    push(bytes) {\n      buffer += decoder.decode(bytes, { stream: true });\n      let nl;\n      while ((nl = buffer.indexOf(\"\\n\")) !== -1) {\n        const line = buffer.slice(0, nl).replace(/\\r$/, \"\");\n        buffer = buffer.slice(nl + 1);\n        if (line === \"\") { flush(); continue; }\n        if (line.startsWith(\"event:\")) { eventName = line.slice(6).trim(); continue; }\n        if (line.startsWith(\"data:\")) { dataLines.push(line.slice(5).replace(/^ /, \"\")); continue; }\n      }\n      const out = pending.slice();\n      pending.length = 0;\n      return out;\n    },\n    /**\n     * 流结束时的收尾（2026-10-08 加）。\n     *\n     * 事件分隔靠空行（`\\n\\n`），所以最后一个事件**没有尾随换行**时会被一直留在\n     * `buffer` 里 —— 实测 `\"event: a\\ndata: 1\"` 返回 `[]`，那个事件永久丢失。\n     * 上游正常收尾时会给 `done`，但**被截断的流**正是最容易缺尾随空行的情况，\n     * 而丢掉的又恰恰可能是 `done`（真实 `finish_reason` 随之被兜底改写成 `stop`）。\n     *\n     * 这里把残留的最后一行按普通行处理并 flush 一次；同时冲掉 `TextDecoder`\n     * 里可能挂着的半个多字节字符（`decode()` 不带 stream 即为终态）。\n     */\n    end() {\n      buffer += decoder.decode();\n      const tail = buffer.replace(/\\r$/, \"\");\n      buffer = \"\";\n      if (tail !== \"\") {\n        if (tail.startsWith(\"event:\")) eventName = tail.slice(6).trim();\n        else if (tail.startsWith(\"data:\")) dataLines.push(tail.slice(5).replace(/^ /, \"\"));\n      }\n      flush();\n      const out = pending.slice();\n      pending.length = 0;\n      return out;\n    },\n    pending() {\n      const out = pending.slice();\n      pending.length = 0;\n      return out;\n    },\n  };\n}\n\n//#endregion\n//#region 回环 shim\n\nfunction writeOpenAIError(res, status, code, message) {\n  writeJson(res, status, { error: { message, type: code, code } });\n}\n\n/**\n * 回环 OpenAI shim。与 WorkBuddy 那条同构：随机端口 + 随机 bearer，\n * 只服务三个路由；上游换成 Trae 客户端，并把 Trae SSE 转成 OpenAI SSE。\n */\nexport function createTraeShim(options) {\n  const { store, client, catalog } = options;\n  const logger = options.logger;\n  /** 每次启动一个新的共享密钥；只在本机回环上使用。 */\n  const SHARED_SECRET = randomBytes(32).toString(\"base64url\");\n\n  function bearerOk(req) {\n    const header = req.headers.authorization;\n    if (typeof header !== \"string\") return false;\n    const match = /^Bearer\\s+(.+)$/i.exec(header.trim());\n    if (match === null) return false;\n    const a = Buffer.from(match[1]);\n    const b = Buffer.from(SHARED_SECRET);\n    return a.length === b.length && timingSafeEqual(a, b);\n  }\n\n  const server = createServer((req, res) => { handle(req, res); });\n  const ready = new Promise((resolve, reject) => {\n    server.once(\"listening\", () => resolve());\n    server.once(\"error\", reject);\n  });\n  server.listen(0, \"127.0.0.1\");\n  const baseUrl = () => {\n    const address = server.address();\n    if (address === null || typeof address === \"string\") throw new Error(\"dsh-trae-connect: shim 没有监听地址\");\n    return `http://127.0.0.1:${address.port}`;\n  };\n\n  async function handle(req, res) {\n    try {\n      if (!hostIsLoopback(req.headers.host)) { writeOpenAIError(res, 403, \"host_not_allowed\", \"Host 必须是回环地址\"); return; }\n      if (!originIsLoopback(req.headers.origin)) { writeOpenAIError(res, 403, \"origin_not_allowed\", \"Origin 必须是回环地址\"); return; }\n      if (!bearerOk(req)) { writeOpenAIError(res, 401, \"unauthorized\", \"Authorization bearer 缺失或不匹配\"); return; }\n      const url = req.url ?? \"/\";\n      if (req.method === \"GET\" && (url === \"/healthz\" || url === \"/healthz/\")) { writeJson(res, 200, { ok: true }); return; }\n      if (req.method === \"GET\" && (url === \"/v1/models\" || url === \"/v1/models/\")) {\n        writeJson(res, 200, { object: \"list\", data: catalog.current().map((m) => ({ id: m.id, object: \"model\", created: 0, owned_by: TRAE_PROVIDER })) });\n        return;\n      }\n      if (req.method === \"POST\" && (url === \"/v1/chat/completions\" || url === \"/v1/chat/completions/\")) { await chatCompletions(req, res); return; }\n      writeOpenAIError(res, 404, \"not_found\", `no such route: ${req.method} ${url}`);\n    } catch (error) {\n      if (!res.headersSent) writeOpenAIError(res, 500, \"internal\", String(error));\n      else res.end();\n    }\n  }\n\n  async function chatCompletions(req, res) {\n    if (typeof req.headers[\"content-type\"] !== \"string\" || !req.headers[\"content-type\"].toLowerCase().includes(\"application/json\")) {\n      writeOpenAIError(res, 415, \"unsupported_media_type\", \"Content-Type 必须是 application/json\");\n      return;\n    }\n    let credential;\n    try {\n      credential = await store.resolve();\n    } catch (error) {\n      writeOpenAIError(res, 401, \"not_signed_in\", error instanceof Error ? error.message : String(error));\n      return;\n    }\n    let request;\n    try {\n      request = JSON.parse((await readBody(req)).toString(\"utf8\"));\n    } catch {\n      writeOpenAIError(res, 400, \"invalid_json\", \"请求体不是合法 JSON\");\n      return;\n    }\n    const settings = options.settings();\n    const decoded = decodeModelId(request.model, settings.function, settings.functions);\n    const controller = new AbortController();\n    abortOnClientDisconnect(res, controller);\n    /**\n     * 把 pi-ai 下发的档位反查回 Trae 的线上值。\n     *\n     * pi-ai 依据模型的 `thinkingLevelMap` 把 UI 档位映射成 wire 值写进请求体\n     * （`reasoningEffort` → `reasoning_effort`），而 Trae 只认\n     * `light`/`high`/`extra_high`。未选择（或选了但映射不到）时回退目录默认档：\n     * 快照的 `reasoning_effort_config.default_level` 是上游给的默认（逐\n     * 模型 × function 不同），主动发出来 —— 不发的话走\"服务端默认档\"，\n     * 那个默认不受插件控制、也和 UI 展示的目录声明脱节。\n     *\n     * ⚠️ **`default_level` 已经是 Trae 的线上拼写，不能再过一层 `LEVEL_TO_TRAE_EFFORT`。**\n     * 那张反向表的键是 pi-ai 档位（low/high/xhigh），拿 `extra_high` 去查只会得到\n     * `undefined` —— 于是默认档为 `extra_high` 的模型（GLM-5.3 系、Kimi-K2.8/K3）\n     * 和 `light` 的模型全部丢掉默认档，唯独 `high` 因为两边同名而\"看起来是好的\"。\n     * 这里只做一件事：确认它确在该模型声明的 options 里（不在就别发，宁缺毋错）。\n     */\n    const level = typeof request.reasoning_effort === \"string\" && request.reasoning_effort !== \"\" ? request.reasoning_effort : undefined;\n    const tokensInfo = catalog.current().find((m) => m.id === decoded.model);\n    const fn = decoded.functionName;\n    const effortCfg = tokensInfo?.reasoningByGroup?.[fn];\n    const declaredOptions = Array.isArray(effortCfg?.options) ? effortCfg.options : [];\n    const defaultWire = effortCfg?.support_thinking === true\n      && typeof effortCfg.default_level === \"string\"\n      && declaredOptions.includes(effortCfg.default_level)\n      ? effortCfg.default_level\n      : undefined;\n    const effort = (level === undefined ? undefined : LEVEL_TO_TRAE_EFFORT.get(level)) ?? defaultWire;\n    /**\n     * Max 模式（更大上下文）按 (模型 × function) 的目录声明决定：\n     * `contextWindowByGroup[fn].max` 存在且 > dev 窗口，说明该模型在当前\n     * function 下有「更大上下文(Max)」档。\n     *\n     * 何时实际启用：请求的 max_tokens 超过 dev 窗口 ⇒ 对话确实需要大窗口。\n     * 实测（2026-10-06 抓包 Trae 客户端）：Max 开启后请求带\n     * prompt_max_tokens=936000（1M 的 93.6%）+ persist_meta.strategy=\"max\"。\n     */\n    const groupTokens = tokensInfo?.contextWindowByGroup?.[decoded.functionName];\n    const devWindow = Number.isFinite(groupTokens?.dev) && groupTokens.dev > 0\n      ? groupTokens.dev\n      : tokensInfo?.contextWindow;\n    const maxWindow = Number.isFinite(groupTokens?.max) && groupTokens.max > 0 ? groupTokens.max : undefined;\n    const requested = Number.isFinite(request.max_tokens) ? request.max_tokens : 0;\n    const maxMode = maxWindow !== undefined\n      && Number.isFinite(devWindow) && devWindow > 0\n      && maxWindow > devWindow\n      && requested > devWindow;\n    const promptMaxTokens = maxMode ? Math.floor(maxWindow * 0.936) : undefined;\n    const result = await client.chatStream(credential, {\n      model: decoded.model,\n      function: decoded.functionName,\n      /**\n       * system 并入首条 user：Trae 的 function 自带系统提示，直接传 system 角色\n       * 不保证被接受。原先这是可配置开关（`inlineSystemPrompt`），2026-10-08\n       * 收口后恒为 true —— 见本文件「配置」段的收口说明。\n       */\n      messages: toTraeMessages(request.messages, true),\n      maxTokens: request.max_tokens,\n      effort,\n      maxMode,\n      promptMaxTokens,\n      /**\n       * 工具定义必须一路带到上游，否则模型看不到有工具可用 ——\n       * 这正是「Trae 下工具调用漏成文本 / 回合空转」的根因。\n       * 转换与上游契约（`parameters` 必须是 JSON 字符串）见 `toTraeTools`。\n       *\n       * （2026-10-08 收口）原先这里的 `settings.toolsEnabled ? … : undefined`\n       * 是一个**不可达的分支**：开关的配置通道已关闭（见本文件「配置」段注释），\n       * `toolsEnabled` 恒为 true，所以条件恒真 —— 现在直接表达恒定行为。\n       * 这也顺带修正了一个误导：README/注释曾把它当成\"退回纯聊天\"的逃生阀，\n       * 实际那个阀门从来拧不动。\n       */\n      tools: toTraeTools(request.tools),\n      toolChoice: request.tool_choice,\n    }, controller.signal);\n\n    if (!result.ok) {\n      const status = result.kind === \"auth\" ? 401 : result.kind === \"network\" ? 502 : 502;\n      writeOpenAIError(res, status, result.kind, `trae upstream (http ${result.status}): ${result.message.slice(0, 500)}`);\n      return;\n    }\n    res.writeHead(200, {\n      \"Content-Type\": \"text/event-stream\",\n      \"Cache-Control\": \"no-cache\",\n      \"Connection\": \"keep-alive\",\n      \"X-Accel-Buffering\": \"no\",\n    });\n    let sawDone = false;\n    const body = Readable.fromWeb(result.response);\n    body.on(\"data\", (chunk) => { if (chunk.includes(\"[DONE]\")) sawDone = true; });\n    body.on(\"error\", (error) => {\n      logger?.warn(\"dsh-trae-connect: 上游流中断\", error);\n      if (!sawDone && res.writable) res.end(\"data: [DONE]\\n\\n\");\n    });\n    body.pipe(res);\n  }\n\n  return {\n    ready,\n    baseUrl,\n    token: () => SHARED_SECRET,\n    close: () => new Promise((resolve, reject) => {\n      server.close(() => resolve());\n      server.closeAllConnections();\n      server.once(\"error\", reject);\n    }),\n  };\n}\n\n//#endregion\n//#region 适配器\n\n/** 组装 pi-ai 的 provider + DSH 的 adapter。 */\n/**\n * [dsh-connect] 面板下发的\"禁用模型\"钩子：`(providerId) => 要隐藏的模型 id[]`。\n *\n * provider 自己不知道面板的存在；lib/index.js 在启动时用 setExternalHidden 注入，\n * 未注入时视为\"不隐藏\"。每次构建模型列表时重新调用，所以用户在面板里改完立即生效。\n */\nlet externalHidden = () => [];\nexport function setExternalHidden(fn) {\n  externalHidden = typeof fn === \"function\" ? fn : () => [];\n}\n\nexport function createTraeAdapter(options) {\n  const { shim, catalog } = options;\n  const providerId = options.providerId ?? TRAE_PROVIDER;\n  const displayName = options.displayName ?? TRAE_DISPLAY_NAME;\n  /** [dsh-connect] 面板禁用的模型 id（每次构建列表时重读，改完立即生效）。 */\n  const hidden = options.hidden ?? (() => []);\n\n  /**\n   * 把倍率挂到模型名上：`DeepSeek-V4-Pro` → `DeepSeek-V4-Pro · x0.72`。\n   *\n   * DSH 0.1.5 的模型下拉（dsh-client-ui-model-selection）只渲染 `model.name`\n   * （`modelLabel = currentChoice?.model.name`，列表项也是 `children: model.name`），\n   * `description` 根本不读 —— 想让每个模型都看到倍率，只能挂在名字上。\n   *\n   * 倍率本身是运行时从 `batch_get_detail_param` 现取的（见 `createCatalog` 的 rates 层），\n   * 拿不到就原样返回，不硬凑。写法与面板的 `modelRate()` 对齐 —— trae 给的是数字，\n   * 所以用 `x0.72` 而不是 qoder 那种 `0.5×`。\n   */\n  function withRateName(info) {\n    const rate = info.rate;\n    const text = typeof rate === \"number\" && Number.isFinite(rate) ? `x${rate}` : undefined;\n    return text === undefined ? info.name : `${info.name} · ${text}`;\n  }\n\n  /**\n   * 某个模型在**当前 function 下**支持的思考档位，转成 pi-ai 的 `thinkingLevelMap`。\n   *\n   * 为什么按 function 取：档位是 `(模型 × function)` 配对下发的。同一个\n   * `deepseek-v4.1-flash` 在 `solo_agent_lite` 下有 light/high/extra_high，\n   * 在 `solo_work_lite` 下 `support_thinking=false`。取错槽位就会得出\n   * \"这个模型不支持档位\"的错误结论。\n   *\n   * 支持的档位集合从 {@link TRAE_EFFORT_TO_LEVEL} 生成：该表里出现过、且**被服务端\n   * 声明**的线上值才映射成对应级；其余一律 `null`。置 null 而非省略是有意的 ——\n   * pi-ai 对\"缺失键\"与\"null\"的处理不对称：缺失会被当成支持并用默认值。\n   */\n  function reasoningFieldsFor(info, fn) {\n    const byGroup = info?.reasoningByGroup;\n    const cfg = byGroup !== undefined && typeof byGroup === \"object\" ? byGroup[fn] : undefined;\n    const declared = new Set(Array.isArray(cfg?.options) ? cfg.options : []);\n    if (cfg?.support_thinking !== true || declared.size === 0) return { reasoning: false };\n    const levels = {};\n    for (const [wire, level] of Object.entries(TRAE_EFFORT_TO_LEVEL)) {\n      levels[level] = declared.has(wire) ? wire : null;\n    }\n    return { reasoning: true, thinkingLevelMap: levels };\n  }\n\n  /**\n   * 某模型在当前 function 下的上下文窗口。\n   *\n   * 目录按 (模型 × function) 配对下发的又一例：`deepseek-v4.1-flash` 在\n   * `solo_agent_lite` 是 {dev:200000, max:1000000}，在 `solo_work_lite` 只有\n   * {dev:200000}。早期导出按模型名去重、只留一个数，1M 那份被 work 组覆盖丢失\n   * —— 用户在 Trae 客户端看得到「更大上下文扩至 1M」，插件里却只有 200k。\n   * 有 `max` 用 max（上游按它计费/放行），否则退回模型级字段。\n   */\n  function contextWindowFor(info, fn) {\n    const g = info?.contextWindowByGroup?.[fn];\n    if (Number.isFinite(g?.max) && g.max > 0) return g.max;\n    if (Number.isFinite(g?.dev) && g.dev > 0) return g.dev;\n    return Number.isFinite(info?.contextWindow) && info.contextWindow > 0 ? info.contextWindow : 128000;\n  }\n\n  const buildModels = () => {\n    const baseUrl = `${shim.baseUrl()}/v1`;\n    // hiddenMatcher 返回的是判定函数（(id) => boolean），按函数调用。\n    // 曾把它当 Set 调 .has() —— 每次构建列表都抛 TypeError，选择器里整个渠道消失。\n    const isHidden = hiddenMatcher(hidden());\n    const fn = options.settings().function;\n    return catalog.current().filter((info) => !isHidden(info.id)).map((info) => ({\n      id: info.id,\n      // 倍率挂在名字上：模型下拉只渲染 `name`（理由见 withRateName）。\n      name: withRateName(info),\n      api: \"openai-completions\",\n      provider: providerId,\n      baseUrl,\n      input: info.supportsImages === true ? [\"text\", \"image\"] : [\"text\"],\n      ...reasoningFieldsFor(info, fn),\n      cost: NO_COST,\n      /**\n       * 上下文窗口按当前 function 取目录声明（与档位同一教训：目录是\n       * (模型 × function) 配对的）。声明里有更大的 `max`（Max 模式档）时\n       * 直接上报 max —— pi-ai 会按它裁剪上下文，长会话才不会在 200k 被截。\n       * 请求侧 shim 再依据 max_tokens 是否超 dev 窗口决定是否带 Max 标记\n       * （见 chatStream 里的 maxMode / promptMaxTokens）。\n       */\n      contextWindow: contextWindowFor(info, fn),\n      maxTokens: info.maxTokens,\n      compat: { maxTokensField: \"max_tokens\" },\n    }));\n  };\n\n  const provider = {\n    ...createProvider({\n      id: providerId,\n      name: displayName,\n      auth: {\n        apiKey: {\n          name: \"Trae 会话 JWT（由 export-trae-plain.mjs 快照提供）\",\n          async resolve({ credential }) {\n            const apiKey = credential?.key;\n            return apiKey === undefined || apiKey.length === 0 ? undefined : { auth: { apiKey }, source: \"Trae\" };\n          },\n        },\n      },\n      models: buildModels(),\n      api: openAICompletionsApi(),\n    }),\n    getModels: () => buildModels(),\n  };\n\n  const profile = {\n    provider: providerId,\n    displayName,\n    streamIdleTimeoutMs: TRAE_STREAM_IDLE_TIMEOUT_MS,\n    retryPolicy: resolveRetryPolicy(undefined, \"dsh-trae-connect retryPolicy\"),\n    configuredMaxTokens: new Map(),\n    modelErrors: new Map(),\n    ...REQUEST_IMAGE_BUDGETS,\n    piProvider: provider,\n  };\n  let profiles = new Map([[providerId, profile]]);\n  return {\n    /**\n     * 附件服务解析器 —— **带图会话能跑通全靠它**。\n     *\n     * 宿主 `dsh-llm-pi-ai` 在把请求交给 pi-ai 之前会先问这个函数要附件仓库：\n     *\n     * ```js\n     * const attachments = containsImage ? this.config.resolveAttachments?.() : undefined;\n     * if (containsImage && attachments === undefined)\n     *   throw new LlmError(\"pi-ai image input requires the durable attachment service\", \"UNSUPPORTED_CONTENT\");\n     * ```\n     *\n     * 不传就是 `undefined`，于是**任何**带图片的请求都在这里被拒，请求根本到不了\n     * Trae 上游 —— 表现为「模型明明标着 multimodal 却报 UNSUPPORTED_CONTENT」，很容易\n     * 误判成模型不支持读图。WorkBuddy provider 一直是好的，正是因为它建 adapter 时把\n     * 这行传了进去；Trae / Qoder 两路一直漏了，所以只有它们报错（2026-10-07 定位）。\n     *\n     * `ctx.get(\"attachments\")` 在本插件这一层能取到服务：`dsh-base` 声明了\n     * `id: attachment-local`，且三个渠道共用同一个 ctx（见 lib/index.js 的 `mod.apply(ctx, {})`）。\n     * 套 `withLegacyImageBudget` 是为跨版本安装兜底（pi-ai 与附件服务的两代契约在\n     * `readImageRequest` 的第二个参数上不一致）；同代 store 上它是 no-op，恒定套用安全。\n     *\n     * 参考实现：dingminhua/dsh-connect-trae `src/index.ts` 同一写法。\n     *\n     * 注：这段说明刻意放在 `new PiAiAdapter(` **外面** —— 放进实参里会让\n     * `probes/verify-attachment-wiring.mjs` 把注释里的同名字符串当成接线证据。\n     */\n    adapter: new PiAiAdapter({\n      profiles: () => profiles,\n      auth: INERT_AUTH,\n      resolveApiKey: async () => shim.token(),\n      resolveAttachments: options.resolveAttachments,\n    }),\n    invalidate: () => { profiles = new Map([[providerId, profile]]); },\n  };\n}\n\n//#endregion\n//#region 渠道状态路由（供浏览器侧读取）\n\n/**\n * 组装给浏览器侧的状态文档。\n *\n * 设计原则与 WorkBuddy 那条一致：**签到与额度都是\"尽力而为\"**——\n * 上游任何一段失败都降级成该字段的错误，而不是让整份文档 500。\n * 否则网络抖一下，界面上连渠道名和签到按钮都会消失。\n */\n/**\n * 组装给浏览器侧的状态文档。\n *\n * 设计原则与 WorkBuddy 那条一致：**签到与额度都是\"尽力而为\"**——\n * 上游任何一段失败都降级成该字段的错误，而不是让整份文档 500。\n * 否则网络抖一下，界面上连渠道名和签到按钮都会消失。\n *\n * `deps.product()` 给出当前产品线，渠道名因此带上产品后缀（`Trae · Trae CN（IDE）`）。\n * 两条接法共用一个 provider id（`trae`）与同一份凭据文件，状态文档里的这一行是界面上\n * 唯一能区分「现在接的是哪一份快照」的地方 —— 缺了它，切换完从面板看不出区别，\n * 「换了快照但没重导」这类故障就无从定位。provider id 不变，\n * 所以 DSH 里已选中的模型不会因为切换产品而丢失。\n */\nexport async function traeWebStatus(deps) {\n  const p = typeof deps.product === \"function\" ? deps.product() : TRAE_PRODUCTS[TRAE_DEFAULT_PRODUCT];\n  const base = {\n    provider: TRAE_PROVIDER,\n    channel: `${TRAE_DISPLAY_NAME} · ${p.label}`,\n    product: p.id,\n    productLabel: p.label,\n    packageType: p.packageType,\n    appVersionCode: p.appVersionCode,\n  };\n  const credential = await deps.store.current();\n  if (credential === undefined) {\n    // 未登录也要把产品与目录说清楚：这时面板显示「签出」，用户得知道它读的是哪份快照、\n    // 哪个模型目录，否则「签出」到底是没凭据还是路径不对，完全分不开。\n    return {\n      ...base,\n      status: \"signed-out\",\n      credentialFile: typeof deps.credentialFile === \"function\" ? deps.credentialFile() : undefined,\n      catalogFile: typeof deps.catalogFile === \"function\" ? deps.catalogFile() : undefined,\n    };\n  }\n\n  const doc = {\n    ...base,\n    status: \"signed-in\",\n    userId: credential.userId,\n    account: credential.account,\n    function: deps.settings().function,\n    catalogFile: typeof deps.catalogFile === \"function\" ? deps.catalogFile() : undefined,\n    modelCount: deps.catalog.current().length,\n    // [dsh-connect] 面板要按渠道列出模型做\"禁用\"配置，这里把清单带上（只读、最多 200 条）。\n    models: deps.catalog.current().slice(0, 200).map((m) => ({\n      id: m.id,\n      name: m.name,\n      /**\n       * 面板要显示倍率，所以这里必须把它带出去。\n       *\n       * ⚠️ 这正是\"trae 永远没有倍率\"的**真正落点**：`/status` 文档此前只透出\n       * `{id, name}` 两个字段 —— 即使 catalog 里读到了 rate（见上方 createCatalog），\n       * 也会在这一步被抹掉。provider 内部\"重建对象时只挑几个字段\"是很常见的丢数据点，\n       * 而且没有任何报错，只能靠逐层比对字段发现。\n       */\n      ...Number.isFinite(m.rate) ? { rate: m.rate } : {},\n      ...Number.isFinite(m.rateDiscount) ? { rateDiscount: m.rateDiscount } : {},\n      ...Number.isFinite(m.rateActivity) ? { rateActivity: m.rateActivity } : {},\n    })),\n    expiresAt: credential.expiresAt,\n  };\n\n  try {\n    doc.credits = await deps.account.fetchCredits(credential);\n  } catch (error) {\n    doc.creditsError = briefMessage(error);\n  }\n  try {\n    doc.checkin = await deps.account.fetchCheckinStatus(credential);\n  } catch (error) {\n    doc.checkinError = briefMessage(error);\n  }\n  return doc;\n}\n\n/** 签到路由：GET 读状态（只读），POST 领取。 */\nexport async function traeCheckinAction(deps, method) {\n  const credential = await deps.store.current();\n  if (credential === undefined) return { state: \"signed-out\" };\n  if (method === \"GET\") {\n    try {\n      return { state: \"signed-in\", checkin: await deps.account.fetchCheckinStatus(credential) };\n    } catch (error) {\n      return { state: \"failed\", message: briefMessage(error) };\n    }\n  }\n  try {\n    return await deps.account.claimDailyCheckin(credential);\n  } catch (error) {\n    return { state: \"failed\", message: briefMessage(error) };\n  }\n}\n\n/**\n * 两个路由的共用外壳。\n *\n * 必须做 loopback 守卫：这两个端点挂在用户自己的 DSH 端口上，而 DSH 端口\n * 可能被反代/局域网暴露。没有这道门，任何能访问该端口的页面都能借同源请求\n * 替用户点签到。Host **和** Origin 都要求是回环，缺一不可\n * （只有 Host 挡不住 DNS rebinding，只有 Origin 挡不住非浏览器客户端，但\n * 这个接口本身不写敏感数据，两者齐备即可）。\n */\nfunction traeRouteHandler(handle) {\n  return async (req, res) => {\n    if (req.method !== \"GET\" && req.method !== \"POST\") {\n      writeJson(res, 405, { error: \"method not allowed\" });\n      return;\n    }\n    if (!loopbackRequest(req)) {\n      writeJson(res, 403, { error: \"request-not-trusted\" });\n      return;\n    }\n    try {\n      writeJson(res, 200, await handle(req.method));\n    } catch (error) {\n      writeJson(res, 500, { error: briefMessage(error) });\n    }\n  };\n}\n\n/** 注册 `/plugins/dsh-trae-connect/{status,checkin}`；webServer 缺失时整段跳过。 */\nexport function registerTraeStatusRoutes(ctx, deps) {\n  for (const [path, handle] of [\n    [TRAE_STATUS_ROUTE, () => traeWebStatus(deps)],\n    [TRAE_CHECKIN_ROUTE, (method) => traeCheckinAction(deps, method)],\n  ]) {\n    ctx.effect(() => {\n      const dispose = ctx.webServer.register({ kind: \"exact\", path, handler: traeRouteHandler(handle) });\n      return () => { dispose(); };\n    }, `dsh-trae-connect: ${path}`);\n  }\n}\n\n//#endregion\n//#region 插件入口\n\n/** 倍率刷新间隔。下限 60s，避免配错成 0 之后每轮巡检都去打一次 1.4 MB。 */\nfunction rateInterval(config) {\n  const override = config?.rateRefreshMs;\n  if (!Number.isFinite(override) || override < MIN_RATE_REFRESH_MS) return RATE_REFRESH_MS;\n  return Math.min(override, MAX_RATE_REFRESH_MS);\n}\n\n/**\n * 拉倍率时要查的 function 清单 = 该产品变体表里的 `rateFunctions`，一个都不再加。\n *\n * ⚠️ 这是**倍率注册表的查询键**，与推理用的 function 白名单（{@link TRAE_PRODUCTS}\n * 的 `functions`）是两件事，只是 CN 侧恰好重合（都等于 {@link TRAE_CN_SLOTS}）。\n * SOLO 那侧就不是了：它的注册表里另有 `assistant` / `builder` 两个只能查价、\n * 不能推理的名字，所以那张表单独列全。\n *\n * 为什么名单必须「刚好铺满目录」，多一个都不加：倍率对同一模型在各 function 下\n * **取值一致**（实测 CN 65 条、SOLO 60 条，0 处冲突），但**哪些模型挂在哪个 function\n * 下**不同，所以名单要能盖住目录里的每个模型；反过来，多出来的名字只会带回\n * `refactor_scoper` 这类**不在目录里**的内部模型的价格，白多一次上游往返。\n * 实测（2026-10-11）：CN 用 3 个分组名 250 ms 覆盖 24/24，扩到 11 个名字 962 ms\n * 仍是 24/24；SOLO 用 7 个分组名 299 ms 覆盖 26/26，扩到 11 个 681 ms 仍是 26/26。\n */\nfunction defaultRateFunctions(product) {\n  // 两种形态都要认：`store.resolve()` 传出来的是**产品对象**，而快照 JSON 和手工\n  // 调用手上只有 `product: \"cn\"` 这个串。只认对象的话，传串会在展开时抛 TypeError\n  // —— 探针和排查脚本就是这么调的，别让它死在取默认名单这一步。\n  const id = typeof product === \"string\" ? product.trim() : product?.id;\n  const p = TRAE_PRODUCTS[id] ?? TRAE_PRODUCTS[TRAE_DEFAULT_PRODUCT];\n  return [...p.rateFunctions];\n}\nfunction rateFunctions(config, product) {\n  const fallback = defaultRateFunctions(product);\n  const override = config?.rateFunctions;\n  if (!Array.isArray(override)) return fallback;\n  const cleaned = override.filter((name) => typeof name === \"string\" && name.trim() !== \"\").map((name) => name.trim());\n  return cleaned.length === 0 ? fallback : cleaned;\n}\n\nconst TRAE_STATE_FILENAME = \".trae-connect-state.json\";\n\n/**\n * 运行态落盘：`$DSH_HOME/.trae-connect-state.json`。\n *\n * 和 workbuddy 插件的 `-catalog.json` 同思路 —— DSH 的插件日志默认不进\n * `/app/.dsh-web.log`，只看日志无法判断一个渠道到底有没有注册成功、当前是\n * 「未登录」还是「已就绪」。这份文件把结果固化下来，排查时直接看它即可。\n *\n * 实现在 `shared/node.js`（与 qoder 共用同一份，只差文件名）。\n */\nfunction writeState(patch, logger) {\n  writeChannelState({ filename: TRAE_STATE_FILENAME, patch, logger });\n}\n\n/**\n * 启动：起回环 shim → 注册 `trae` provider → 按凭据轮询刷新。\n *\n * 无论有没有凭据都先注册 provider —— DSH 用「模型组为空」来隐藏一个模型组，\n * 所以登录发生在 DSH 已经跑起来之后也能生效，不需要重新注册。\n */\nexport function apply(ctx, config) {\n  let stopped = false;\n  const current = () => config ?? {};\n\n  /** 强制刷新句柄：shim ready 后挂上；面板「更新模型」走它，拿模型前后差异。 */\n  let forceRefreshImpl = null;\n\n  /**\n   * 当前生效的产品（cn / solo）—— 每次现读，不缓存。\n   *\n   * 为什么必须每次现读（这是这次切换的**核心机关**）：\n   * 用户换一份凭据快照（比如从 SOLO 换成 CN）后，`function` 白名单、默认槽位、\n   * models.json 目录、倍率查询集、`req_source` 必须**整套跟着换**。\n   * 任何一处缓存了旧产品，都会出现「用 CN 的 function 名去发 SOLO 的目录」这类\n   * 上游只回 4001/4023、根因完全看不出来的故障。\n   * 判定本身只是读一个小 JSON 文件，30 秒一轮的巡检频率下开销可以忽略。\n   */\n  const productOf = () => activeProduct(current);\n\n  /**\n   * 生效的 function 与系统提示拼法。\n   *\n   * 配置里的 `function` 只在**当前产品的白名单内**才被采纳，否则回落到该产品的\n   * 默认槽位（见 {@link TRAE_PRODUCTS} 里 `defaultFunction` 的注释 —— 那个槽位是\n   * 挑「档位 + 1M 上下文覆盖最广」的那个，不是随便选的）。\n   */\n  const settings = () => {\n    const p = productOf();\n    const wanted = current().function;\n    return {\n      product: p.id,\n      productLabel: p.label,\n      function: p.functions.includes(wanted) ? wanted : p.defaultFunction,\n      functions: p.functions,\n    };\n  };\n\n  const store = createCredentialStore({ config: current, logger: ctx.logger });\n  const catalog = createCatalog({ config: current });\n  const client = createTraeClient({ logger: ctx.logger });\n  const account = createTraeAccountClient({ logger: ctx.logger });\n  const rateClient = createTraeRateClient({ logger: ctx.logger });\n\n  /**\n   * 目录快照的实际路径 —— 只给状态文档透出，方便一眼看出\n   * 「CN 的产品却读着 trae/ 的旧目录」这类没重导快照的故障。\n   */\n  const catalogFile = () => current().modelCatalogFile || defaultCatalogPath(productOf());\n\n  const shim = createTraeShim({ store, client, catalog, settings, logger: ctx.logger });\n\n  // 渠道状态页（渠道名 / 剩余积分 / 签到）走的是 DSH 自己的 webServer，\n  // 不是回环 shim —— 前者给浏览器同源读取，后者只给 pi-ai 发 OpenAI 请求。\n  // webServer 在非 web profile 里不存在，所以用 ctx.inject 做可选依赖。\n  ctx.inject([\"webServer\"], (webCtx) => {\n    if (stopped) return;\n    try {\n      registerTraeStatusRoutes(webCtx, {\n        store,\n        catalog,\n        account,\n        settings,\n        // 状态文档要说明「现在接的是哪个产品、读的哪两份文件」——排查全靠这三行。\n        product: productOf,\n        credentialFile: () => store.path(),\n        catalogFile,\n      });\n    } catch (error) {\n      ctx.logger?.warn(\"dsh-trae-connect: 状态路由注册失败（渠道本身不受影响）\", error);\n    }\n  });\n\n  shim.ready.then(() => {\n    if (stopped) return;\n    const { adapter, invalidate } = createTraeAdapter({\n      shim,\n      catalog,\n      settings,\n      hidden: () => externalHidden(TRAE_PROVIDER),\n      /** 附件仓库解析器；缺了它，带图请求会被宿主在进 pi-ai 之前拒掉（UNSUPPORTED_CONTENT）。 */\n      resolveAttachments: () => {\n        const store = ctx.get(\"attachments\");\n        return store === undefined ? undefined : withLegacyImageBudget(store, REQUEST_IMAGE_BUDGETS.requestImagePixelBudget);\n      },\n    });\n    const release = ctx.llm.registerAdapter([TRAE_PROVIDER], adapter);\n    try {\n      ctx.effect(() => () => { release(); shim.close(); });\n    } catch {\n      release();\n      shim.close();\n    }\n    /**\n     * 倍率的刷新状态机。\n     *\n     * 与凭据/目录巡检**分开计时**（前者 30s，这里默认 15 分钟）：一次全